    public function actionPrimaverasync(){
        $upperCase  = ($_SERVER['HTTP_HOST'] == 'localhost') ? 0 : 1;
        $sqlite_con = Yii::$app->db_sqlite;
        ///$projId     = 4513;


        $sql        = "SELECT proj.*  
                       FROM ".Yii::$app->helper->changeStrCase('project', $upperCase)." as proj
                       LEFT JOIN ".Yii::$app->helper->changeStrCase('udfvalue', $upperCase)." as udfv
                       ON udfv.PROJ_ID=proj.PROJ_ID
                       LEFT JOIN ".Yii::$app->helper->changeStrCase('udftype', $upperCase)." as udft 
                       ON udft.UDF_TYPE_ID = udfv.UDF_TYPE_ID
                       WHERE  udfv.FK_ID=proj.PROJ_ID AND udft.UDF_TYPE_LABEL = 'Opiam Project'";
        $projects   = $sqlite_con->createCommand($sql)->query()->readAll();

        if($projects){
            foreach ($projects as $primavera_proj) {
                $projId     = $primavera_proj['PROJ_ID'];

                $sql        = "SELECT * FROM ".Yii::$app->helper->changeStrCase('projwbs', $upperCase)." 
                               WHERE PROJ_ID =".$projId." 
                               ORDER BY WBS_ID ASC LIMIT 1";
                $proj_wbs   = $sqlite_con->createCommand($sql)->query()->readAll();

                $proj_name = (isset($proj_wbs[0]['WBS_NAME'])) ? $proj_wbs[0]['WBS_NAME'] : '';
                if($proj_name){

                    $proj_id   = $proj_wbs[0]['PROJ_ID'];
                    //---Project Create/Update ------------
                    if(!$opiamProj = Projects::find()->where(['primavera_id' => $proj_id])->one())
                        $opiamProj               = new Projects();

                    $opiamProj->Name         = $proj_name;
                    $opiamProj->primavera_id = $proj_id;
                    $opiamProj->save(false);
                    //-------------------------------------

                    $proj_wbs_id = $proj_wbs[0]['WBS_ID'];

                    //---IOW GROUPS ------------------------------
                    $sql        = "SELECT * FROM ".Yii::$app->helper->changeStrCase('projwbs', $upperCase)." WHERE PARENT_WBS_ID=".$proj_wbs_id." ORDER BY WBS_ID ASC";
                    $iow_groups = $sqlite_con->createCommand($sql)->query()->readAll();
                    
                    $iow_grp_wbs_ids = [];
                    if($iow_groups){
                        foreach ($iow_groups as $iow_group) {

                            if(!$IowGroup = IowGroup::find()->where(['primavera_id' => $iow_group['WBS_ID']])->one())
                                $IowGroup = new IowGroup();
                            $IowGroup->name         = $iow_group['WBS_NAME'];
                            $IowGroup->project_id   = $opiamProj->Project_Id;
                            $IowGroup->primavera_id = $iow_group['WBS_ID'];
                            $IowGroup->save(false);

                            $iow_grp_wbs_ids[$IowGroup->id] = $iow_group['WBS_ID'];
                        }
                    }
                    //---IOWS ------------------------------
                    $sql        = "SELECT * FROM ".Yii::$app->helper->changeStrCase('projwbs', $upperCase)." WHERE PARENT_WBS_ID IN(".implode(",", $iow_grp_wbs_ids).") ORDER BY WBS_ID ASC";
                    $iows = $sqlite_con->createCommand($sql)->query()->readAll();
                    
                    $iow_wbs_ids = [];
                    $iow_schedule_ids = [];
                    if($iows){
                        foreach ($iows as $iow) {
                            if(!$workgroupsNew = WorkgroupsNew::find()->where(['primavera_id' => $iow['WBS_ID']])->one())
                                $workgroupsNew = new WorkgroupsNew();
                            $workgroupsNew->Name         = $iow['WBS_NAME'];
                            $workgroupsNew->Project_Id   = $opiamProj->Project_Id;
                            $workgroupsNew->iowGroupid   = array_search($iow['PARENT_WBS_ID'], $iow_grp_wbs_ids);
                            $workgroupsNew->primavera_id = $iow['WBS_ID'];
                            $workgroupsNew->save(false);
                            $iow_wbs_ids[$workgroupsNew->Workgroup_Id] = $iow['WBS_ID'];

                            if(!$wbsScheduleItem = Wbsscheduleitems::find()->where(['primavera_id' => $iow['WBS_ID']])->one())
                                $wbsScheduleItem = new Wbsscheduleitems();
                            $wbsScheduleItem->name          = $iow['WBS_NAME'];
                            $wbsScheduleItem->projectId     = $opiamProj->Project_Id;
                            $wbsScheduleItem->wbsid         = $workgroupsNew->Workgroup_Id;
                            $wbsScheduleItem->primavera_id  = $iow['WBS_ID'];
                            $wbsScheduleItem->save(false);
                            $iow_schedule_ids[$wbsScheduleItem->scheduleitem_id] = $iow['WBS_ID'];
                        }
                    }


                    //---ACTIVITIES & TASKS ------------------------------

                    $sql    = "SELECT * FROM ".Yii::$app->helper->changeStrCase('task', $upperCase)." WHERE PROJ_ID=".$proj_id." ORDER BY TASK_ID ASC";
                    $tasks  = $sqlite_con->createCommand($sql)->query()->readAll();
                    if($tasks){
                        foreach ($tasks as $task) {

                            $sql        = "SELECT * FROM ".Yii::$app->helper->changeStrCase('calendar', $upperCase)." WHERE CLNDR_ID= ".$task['CLNDR_ID'];
                            $calendar   = $sqlite_con->createCommand($sql)->query()->readAll();
                            $workhours  = ($calendar) ? $calendar[0]['DAY_HR_CNT'] : 24; 


                            $sql        = "SELECT udfv.*,udft.UDF_TYPE_LABEL  
                                           FROM ".Yii::$app->helper->changeStrCase('udfvalue', $upperCase)." as udfv
                                           LEFT JOIN ".Yii::$app->helper->changeStrCase('udftype', $upperCase)." as udft 
                                           ON udft.UDF_TYPE_ID = udfv.UDF_TYPE_ID
                                           WHERE udfv.PROJ_ID=".$proj_id." AND udfv.FK_ID=".$task['TASK_ID'];
                            $udf_data  = $sqlite_con->createCommand($sql)->query()->readAll();

                            $udfvalue_arr = [];
                            if($udf_data){
                                foreach ($udf_data as $udf_val) {
                                    if($udf_val['UDF_TYPE_LABEL'] == 'Unit')
                                        $udfvalue_arr[$udf_val['UDF_TYPE_LABEL']] = $udf_val['UDF_TEXT'];
                                    else
                                        $udfvalue_arr[$udf_val['UDF_TYPE_LABEL']] = $udf_val['UDF_NUMBER'];
                                }
                            }

                            $act_qty    = (isset($udfvalue_arr['Quantity'])) ? $udfvalue_arr['Quantity'] : 0;
                            $act_unit   = (isset($udfvalue_arr['Unit'])) ? $udfvalue_arr['Unit'] : 'Ls';
                            $rep_qty    = (isset($udfvalue_arr['Reporting period quantity'])) ? $udfvalue_arr['Reporting period quantity'] : 1;
                            $rep_period = (isset($udfvalue_arr['Reporting period in Hrs'])) ? $udfvalue_arr['Reporting period in Hrs'] : 1;

                            if(!$workgroupActivity = WorkgroupActivitiesNew::find()->where(['primavera_id' => $task['TASK_ID']])->one())
                                $workgroupActivity = new WorkgroupActivitiesNew();
                            $workgroupActivity->activity_Name = $task['TASK_NAME'];
                            $workgroupActivity->project_Id    = $opiamProj->Project_Id;
                            $workgroupActivity->wbs_id        = array_search($task['WBS_ID'], $iow_wbs_ids);
                            $workgroupActivity->primavera_id  = $task['TASK_ID'];
                            $workgroupActivity->activity_Unit = $act_unit;
                            $workgroupActivity->estimate      = 1;
                            $workgroupActivity->save(false);

                            if(!$pricingEstimateNew = PricingEstimateNew::find()->where(['primavera_id' => $task['TASK_ID']])->one())
                                $pricingEstimateNew = new PricingEstimateNew();
                            $pricingEstimateNew->activity_Id   = $workgroupActivity->id;
                            $pricingEstimateNew->project_Id    = $opiamProj->Project_Id;
                            $pricingEstimateNew->activity_qty  = $act_qty;
                            $pricingEstimateNew->process_Id    = 4;
                            $pricingEstimateNew->primavera_id  = $task['TASK_ID'];
                            $pricingEstimateNew->save(false);


                            /*$task_start_date = date_create(date('Y-m-d', strtotime($task['TARGET_START_DATE'])));
                            $task_end_date   = date_create(date('Y-m-d', strtotime($task['TARGET_END_DATE'])));
                            $diff            = date_diff($task_start_date, $task_end_date);
                            $duration        = $diff->format("%a");*/
                            

                            $duration   = $task['TARGET_DRTN_HR_CNT'] / $workhours;

                            $sql        = "SELECT * FROM ".Yii::$app->helper->changeStrCase('taskpred', $upperCase)." WHERE TASK_ID=".$task['TASK_ID'];
                            $task_pred  = $sqlite_con->createCommand($sql)->query()->readAll();

                            if($task_pred){
                                $pred_type       = $task_pred[0]['PRED_TYPE'];
                                $lag_days        = $task_pred[0]['LAG_HR_CNT'] / $workhours;
                                $pred_task_id    = $task_pred[0]['PRED_TASK_ID'];

                                $pred_activity   = Scheduleactivities::find()->where(['primavera_id'=>$pred_task_id])->one();
                                $pred_start_date = $pred_activity->actual_start_date;
                                $pred_end_date   = $pred_activity->actual_end_date;

                                if($pred_type == 'PR_FF'){
                                    $task_end_date   = date('Y-m-d', strtotime($pred_end_date. " +".$lag_days." days"));
                                    $task_start_date = date('Y-m-d', strtotime($task_end_date. " -".$duration." days"));
                                }
                                elseif($pred_type == 'PR_FS'){
                                    $task_start_date   = date('Y-m-d', strtotime($pred_end_date. " +".$lag_days." days"));
                                    $task_end_date = date('Y-m-d', strtotime($task_start_date. " +".$duration." days"));
                                }
                            }
                            else{
                                $task_start_date = date('Y-m-d', strtotime($task['TARGET_START_DATE']));
                                $task_end_date   = date('Y-m-d', strtotime($task['TARGET_END_DATE']));
                            }
                            

                            if(!$schActivity = Scheduleactivities::find()->where(['primavera_id'=>$task['TASK_ID']])->one())
                                $schActivity = new Scheduleactivities();
                            $schActivity->name              = $task['TASK_NAME'];
                            $schActivity->activity_id       = $workgroupActivity->id;
                            $schActivity->projectId         = $opiamProj->Project_Id;
                            $schActivity->unit              = $act_unit;
                            $schActivity->scheduleitem_id   = array_search($task['WBS_ID'], $iow_schedule_ids);
                            $schActivity->actual_start_date = $task_start_date;
                            $schActivity->actual_end_date   = $task_end_date;
                            $schActivity->old_duration      = $duration;
                            $schActivity->duration          = $duration;
                            $schActivity->quantity          = $act_qty;
                            $schActivity->primavera_id      = $task['TASK_ID'];
                            $schActivity->save(false);


                            if(!$schActivityNew = ScheduleActivityNew::find()->where(['primavera_id'=>$task['TASK_ID']])->one())
                                $schActivityNew = new ScheduleActivityNew();
                            $schActivityNew->activity_name     = $task['TASK_NAME'];
                            $schActivityNew->actvity_id        = $schActivity->id;
                            $schActivityNew->Project_Id        = $opiamProj->Project_Id;
                            $schActivityNew->Workhours         = $workhours;
                            $schActivityNew->Cycles            = $act_qty / $rep_qty;
                            $schActivityNew->cycle_qty         = $rep_qty;
                            $schActivityNew->cycle_units       = 0;
                            $schActivityNew->cycle_unit_type   = $act_unit;
                            $schActivityNew->primavera_id      = $task['TASK_ID'];
                            $schActivityNew->cycle_type        = 'variable_qty';
                            $schActivityNew->report_method     = 'daily';
                            $schActivityNew->save(false);

                            if(!$tasksNew = TasksNew::find()->where(['primavera_id'=>$task['TASK_ID']])->one())
                                $tasksNew = new TasksNew();
                            $tasksNew->Name             = $task['TASK_NAME'];
                            $tasksNew->activity_Id      = $schActivity->id;
                            $tasksNew->primavera_id     = $task['TASK_ID'];
                            $tasksNew->save(false);

                            if(!$schTasksNew = ScheduleTaskNew::find()->where(['primavera_id'=>$task['TASK_ID']])->one())
                                $schTasksNew = new ScheduleTaskNew();
                            $schTasksNew->activity_name     = $task['TASK_NAME'];
                            $schTasksNew->activity_Id       = $schActivity->id;
                            $schTasksNew->task_Id           = $tasksNew->task_Id;
                            $schTasksNew->Budgeted_Duration = $rep_period;
                            $schTasksNew->primavera_id      = $task['TASK_ID'];
                            $schTasksNew->save(false);

                        }
                    }
                    //-------------------------------------


                }
            }
        }

    }





    /**
     * Creates a new model.
     * If creation is successful, the browser will be redirected to the 'view' page.
     */
    public function actionCreate()
    {
        // Uncomment the following line if AJAX validation is needed
        // $this->performAjaxValidation($model);

        if (isset($_POST['projectname'])) {
            $model = new Projects;
            $model->Name = $_POST['projectname'];
            $model->Added_On = date('y-m-d h:i:s');
            $model->project_value = $_POST['projectvalue'];
            $model->start_date = $_POST['startdate'];
            $model->end_date = $_POST['enddate'];
            $model->duration = $_POST['duration'];
            $model->client_name = $_POST['clientname'];
            $model->location = trim($_POST['location'] ?? '');
            $model->wrkhours = $_POST['wrkhrss'];
            $model->favourite = 1;
            if ($model->save(false)):
                $connection = \Yii::$app->db;
                $sql = "UPDATE projects SET itemtype='project' WHERE Project_Id='" . $model->Project_Id . "' ";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                if (!empty($_POST['cashaccount'])) {
                    $sql = "UPDATE accounts_item set projectid='" . $model->Project_Id . "' where id='" . $_POST['cashaccount'] . "' ";
                    $connection->createCommand($sql)->query();
                }
                if (!empty($_POST['bankaccount'])) {
                    $sql = "UPDATE accounts_item set projectid='" . $model->Project_Id . "' where id='" . $_POST['bankaccount'] . "' ";
                    $connection->createCommand($sql)->query();
                }


                $uid = Yii::$app->user->Id;
                $projectid = $model->Project_Id;
                $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
                if($projuser){
                    $projuser->projectid = $projectid;
                    $projuser->save(false);
                }
                else{
                    $ProjuserSelection = new ProjuserSelection();
                    $ProjuserSelection->userid = $uid;
                    $ProjuserSelection->projectid = $projectid;
                    $ProjuserSelection->save(false);
                }

                $uploadDir = Yii::getAlias('@webroot') . '/uploads/projects/';
                $allowed = ['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'];
                $corrAddresse = trim($_POST['corr_addressee'] ?? '');
                $corrSubject  = trim($_POST['corr_subject'] ?? '');
                foreach (['project_documents' => 'documents', 'project_correspondence' => 'correspondence'] as $field => $type) {
                    if (!empty($_FILES[$field]['name'][0])) {
                        foreach ($_FILES[$field]['name'] as $i => $origName) {
                            $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                            if (!in_array($ext, $allowed)) continue;
                            $storedName = uniqid('pf_') . '.' . $ext;
                            move_uploaded_file($_FILES[$field]['tmp_name'][$i], $uploadDir . $storedName);
                            $addr = ($type === 'correspondence') ? $corrAddresse : '';
                            $subj = ($type === 'correspondence') ? $corrSubject  : '';
                            $connection->createCommand("INSERT INTO project_files (project_id, file_type, addressee, subject, filename, original_name, uploaded_by) VALUES (:pid,:type,:addr,:subj,:fn,:on,:uid)")
                                ->bindValues([':pid' => $model->Project_Id, ':type' => $type, ':addr' => $addr, ':subj' => $subj, ':fn' => $storedName, ':on' => $origName, ':uid' => $uid])
                                ->execute();
                        }
                    }
                }

                $arr = array('Id' => $model->Project_Id, 'Name' => $model->Name, 'error' => 'No');
                return json_encode($arr);
            else:
                $arr = array('error' => 'Yes', 'errortext' => 'Cannot add now. Please try again later');
                return json_encode($arr);
            endif;
        }
    }

    /* Global popup: get one project for editing */
    public function actionGlobalgetproject()
    {
        $id = intval($_POST['project_id'] ?? 0);
        if (!$id) { echo json_encode(['error'=>'Yes','errortext'=>'Invalid ID']); return; }
        $p = Projects::findOne($id);
        if (!$p) { echo json_encode(['error'=>'Yes','errortext'=>'Not found']); return; }
        $fmtDate = function($d) {
            if (!$d) return '';
            $ts = strtotime($d);
            return $ts ? date('Y-m-d', $ts) : '';
        };
        echo json_encode([
            'error'         => 'No',
            'Project_Id'    => $p->Project_Id,
            'Name'          => $p->Name,
            'duration'      => $p->duration,
            'start_date'    => $fmtDate($p->start_date),
            'end_date'      => $fmtDate($p->end_date),
            'project_value' => $p->project_value,
            'client_name'   => $p->client_name,
            'location'      => $p->location,
            'wrkhours'      => $p->wrkhours,
        ]);
    }

    /* Global popup: update a project */
    public function actionGlobalupdateproject()
    {
        $id = intval($_POST['project_id'] ?? 0);
        if (!$id) { echo json_encode(['error'=>'Yes','errortext'=>'Invalid ID']); return; }
        $p = Projects::findOne($id);
        if (!$p) { echo json_encode(['error'=>'Yes','errortext'=>'Not found']); return; }
        $p->Name          = trim($_POST['projectname'] ?? '');
        $p->duration      = intval($_POST['duration'] ?? 0);
        if (!empty($_POST['startdate'])) $p->start_date = $_POST['startdate'];
        if (!empty($_POST['enddate']))   $p->end_date   = $_POST['enddate'];
        $p->project_value = $_POST['projectvalue'] ?? '';
        $p->client_name   = trim($_POST['clientname'] ?? '');
        $p->location      = trim($_POST['location'] ?? '');
        $p->wrkhours      = intval($_POST['wrkhrss'] ?? 0);
        if ($p->save(false)) {
            $connection = \Yii::$app->db;
            $uploadDir = Yii::getAlias('@webroot') . '/uploads/projects/';
            $allowed = ['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'];
            $uid = Yii::$app->user->Id;
            $corrAddresse = trim($_POST['corr_addressee'] ?? '');
            $corrSubject  = trim($_POST['corr_subject'] ?? '');
            foreach (['project_documents' => 'documents', 'project_correspondence' => 'correspondence'] as $field => $type) {
                if (!empty($_FILES[$field]['name'][0])) {
                    foreach ($_FILES[$field]['name'] as $i => $origName) {
                        $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                        if (!in_array($ext, $allowed)) continue;
                        $storedName = uniqid('pf_') . '.' . $ext;
                        move_uploaded_file($_FILES[$field]['tmp_name'][$i], $uploadDir . $storedName);
                        $addr = ($type === 'correspondence') ? $corrAddresse : '';
                        $subj = ($type === 'correspondence') ? $corrSubject  : '';
                        $connection->createCommand("INSERT INTO project_files (project_id, file_type, addressee, subject, filename, original_name, uploaded_by) VALUES (:pid,:type,:addr,:subj,:fn,:on,:uid)")
                            ->bindValues([':pid' => $id, ':type' => $type, ':addr' => $addr, ':subj' => $subj, ':fn' => $storedName, ':on' => $origName, ':uid' => $uid])
                            ->execute();
                    }
                }
            }
            echo json_encode(['error'=>'No','Name'=>$p->Name]);
        } else {
            echo json_encode(['error'=>'Yes','errortext'=>'Could not update.']);
        }
    }

    /* Global popup: list uploaded files for a project */
    public function actionGlobalprojectfiles()
    {
        $id = intval($_POST['project_id'] ?? 0);
        if (!$id) { echo json_encode(['error'=>'Yes','files',[]]); return; }
        $connection = \Yii::$app->db;
        $files = $connection->createCommand(
            "SELECT id, file_type, original_name, filename, DATE_FORMAT(uploaded_at,'%d %b %Y') AS uploaded_at
             FROM project_files WHERE project_id=:pid ORDER BY uploaded_at DESC"
        )->bindValue(':pid', $id)->queryAll();
        echo json_encode(['error'=>'No','files'=>$files]);
    }

    /* Global popup: soft-delete a project */
    public function actionGlobaldeleteproject()
    {
        $id = intval($_POST['project_id'] ?? 0);
        if (!$id) { echo json_encode(['error'=>'Yes','errortext'=>'Invalid ID']); return; }
        $connection = \Yii::$app->db;
        $connection->createCommand()->update('projects', ['Project_Delete_Status' => 1], 'Project_Id = :id', [':id' => $id])->execute();
        /* clear projuser_selection if deleted project was active */
        $connection->createCommand()->delete('projuser_selection', 'projectid = :id', [':id' => $id])->execute();
        echo json_encode(['error'=>'No']);
    }

    //status active
    public function actionProjectsearch()
    {
         $connection = \Yii::$app->db; 
         $uid = Yii::$app->user->Id; 
        $row = User::findOne($uid);
        $roleid = $row->superuser;

        if ($roleid==1) {
