    public function actionGetmusterdata()
    {  
        $connection = \Yii::$app->db; 
        
        $sql = "SELECT muster_id FROM `muster` WHERE   `date` IN ('".$_POST['date']."') AND `activity_id` IN ('".$_POST['actid']."') AND `status` = 0 AND `order_id` = '".$_POST['orderid']."'  ";
        
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resources = $dataReader->readAll();
        
            foreach ($resources as $key => $value) {
               $musterarray[] = $value['muster_id'];
            }        
        $mustersession =  Yii::$app->session->get('mustersession'); 
        $mustermerge = array_merge($mustersession,$musterarray);
        $mustersession = array_unique($mustermerge);
        Yii::$app->session->set('mustersession',$mustersession);
        
        $arr = array('resourcerows'=>$musterarray,'error' => 'No');
        return json_encode($arr);
    }

    public function actionRemovemusterdata()
    {
        $connection = \Yii::$app->db; 
        $sql = "SELECT muster_id FROM `muster` WHERE   `date` IN ('".$_POST['date']."') AND `activity_id` IN ('".$_POST['actid']."') AND `status` = 0 AND `order_id` = '".$_POST['orderid']."'  ";
        
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resources = $dataReader->readAll();
        $musterarray = array();
            foreach ($resources as $key => $value) {
               $musterarray[] = $value['muster_id'];
            }        
           
        $mustersessions =  Yii::$app->session->get('mustersession');    
        $mustersession = array_diff($mustersessions,$musterarray);
        
        Yii::$app->session->set('mustersession',$mustersession);

        $arr = array('resourcerows'=>$musterarray,'error' => 'No');
        return json_encode($arr);
    }

    public function actionSaveotrate()
    {
        //$orderesources = OrderedResource::find()->where(['order_id' => $_POST['orderid']])->andWhere(['resource_id' => $_POST['resid']])->all();
        $orderesources = OrderedResource::find()->where(['order_id' => $_POST['orderid']])->all();

        foreach($orderesources as $orderesource)
        {
            $orderesource->ot_rate = $_POST['otrate'];
            $orderesource->save(false);

            $wages=($_POST['nodays'] * $orderesource->rate) + ($_POST['othourstot'] * $orderesource->ot_rate);

        }

        



        $arr = array('error'=> 'No','wages' => $wages);
        return json_encode($arr);

    }
    public function actionLogactivity()
    {

        $connection = Yii::$app->db;
        $sql1 = "SELECT b.* FROM workgroup_activities_new AS a INNER JOIN pricing_estimate_new AS b ON a.id=b.activity_Id INNER JOIN pricing_estimate_resources_new AS c ON b.activity_Id=c.activity_id WHERE  b.project_Id=".$_POST['projectid']." AND a.pricing_status=0 AND b.activity_qty!=0 AND b.pricing_status=0 AND c.resource_Id=".$_POST['resourceid']." ORDER BY b.process_Id ASC";
