    public function actionLogdatevalidate()
    {
        $connection = Yii::$app->db;
        $sql="SELECT a.received_date  FROM `ordered_resource` as a 
            INNER JOIN orders as b ON b.order_id=a.order_id
            INNER JOIN resources as c ON a.resource_id=c.Resource_Id
            WHERE b.project_id='".$_POST['projectid']."' AND c.Resource_group_Id=102 AND a.resource_id='".$_POST['resourceid']."'";
       /* $sql="SELECT od.received_date  FROM jobcard as job
              INNER JOIN ordered_resource as od ON od.jobcard_id=job.job_id
              WHERE job.resource LIKE '".$_POST['resourceid']."' AND job.project_id = '".$_POST['projectid']."' AND job.app_activity = '".$_POST['activityid']."'";*/
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $data = $dataReader->read();

        if($data)
        {
             $arr = array('recievedDate'=>$data['received_date'],'error' => 'No');
        
        }else
        {
            $arr = array('Message'=>'Something went wrong','error' => 'Yes');
        }

        return json_encode($arr);


    }

