        $sql1.="c.Name FROM musterroll as a left join resources as c on a.trade_id=c.Resource_Id WHERE groupid='$id' ORDER BY a.musterroll_id DESC";
       
        $command=$connection->createCommand($sql1);
        $dataReader=$command->query();
        $dataProvider=$dataReader->readAll();
        $sql="SELECT DATE_FORMAT(a.date,'%d %b %y') AS date,a.process,a.activity_id,a.trade_id,a.order_id,b.username FROM musterroll as a left join user as b on a.userid=b.id WHERE groupid='".$id."' ";  
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $data=$dataReader->read();
        //$fromdate=Musterroll::find()->where(['project_id' => $projuser->projectid])->andWhere(['activity_id'=>$data['activity_id']])->andWhere(['trade_id'=>$data['trade_id']])->orderBy(['date' => SORT_ASC])->one();
        //$todate=Musterroll::find()->where(['project_id' => $projuser->projectid])->andWhere(['activity_id'=>$data['activity_id']])->andWhere(['trade_id'=>$data['trade_id']])->orderBy(['date' => SORT_DESC])->one();

        //$fromdate=Muster::find()->where(['project_id' => $projuser->projectid])->andWhere(['activity_id'=>$data['activity_id']])->andWhere(['trade_id'=>$data['trade_id']])->andWhere(['order_id'=>$data['order_id']])->orderBy(['date' => SORT_ASC])->one();
        //$todate=Muster::find()->where(['project_id' => $projuser->projectid])->andWhere(['activity_id'=>$data['activity_id']])->andWhere(['trade_id'=>$data['trade_id']])->andWhere(['order_id'=>$data['order_id']])->orderBy(['date' => SORT_DESC])->one();

        // $connection = Yii::$app->db;
        // $sqlf = "SELECT a.date as fromdate FROM muster as a INNER JOIN musterroll as b ON a.activity_id=b.activity_id AND a.trade_id=b.trade_id WHERE a.activity_id=".$data['activity_id']." AND a.trade_id=".$data['trade_id']." AND a.order_id=".$data['order_id']." AND a.date<=b.date ORDER BY a.date ASC";
        // $command=$connection->createCommand($sqlf);
        // $dataReader=$command->query();
        // $fromdate=$dataReader->read();


        // $sqlf = "SELECT a.date as todate FROM muster as a INNER JOIN musterroll as b ON a.activity_id=b.activity_id AND a.trade_id=b.trade_id WHERE a.activity_id=".$data['activity_id']." AND a.trade_id=".$data['trade_id']." AND a.order_id=".$data['order_id']." AND a.date<=b.date ORDER BY a.date DESC";
        // $command=$connection->createCommand($sqlf);
        // $dataReader=$command->query();
        // $todate=$dataReader->read();

        $dates=Musterroll::find()->where(['activity_id'=>$data['activity_id']])->andWhere(['trade_id'=>$data['trade_id']])->andWhere(['groupid'=>$id])->one();

        $fromdate = $dates->reported_fromdate;
        $todate = $dates->reported_todate;
        $reporteddate = $dates->date;

       /* if($fromdate!='' && $todate!=''){
                $dateinfo='<h6  class="muster-date-from-to">From: '.date('d-m-Y',strtotime($fromdate)).' To: '.date('d-m-Y',strtotime($todate)).'</h6>';

            }
            else{
                $dateinfo='';
            }*/

