            $sql2.="c.Name FROM musterroll as a left join resources as c on a.trade_id=c.Resource_Id WHERE groupid='$id'";
           
            $command=$connection->createCommand($sql1);
            $dataReader=$command->query();
            $data_date=$dataReader->read();

            $date_arr = explode(",", $data_date['selected_date']); 
             
             usort($date_arr, function($a, $b) {
                $dateTimestamp1 = strtotime($a);
                $dateTimestamp2 = strtotime($b);
            
                return $dateTimestamp1 < $dateTimestamp2 ? -1: 1;
            });
            
            $from_date = $date_arr[0];
            
            $to_date = $date_arr[count($date_arr) - 1]; 

            if($from_date!='' && $to_date!=''){
                $dateinfo='<h6  class="muster-date-from-to">From: '.date('d-m-Y',strtotime($from_date)).' To: '.date('d-m-Y',strtotime($to_date)).'</h6>';
            }else{
                $dateinfo='';
            }

