    public function getresourcecost($resource,$project)
    {
        $excrow= "SELECT Max(log_id) FROM logbook WHERE equipment_id =".$resource." AND project_id=".$project." ";
        $connection = Yii::$app->db;
        $sql= "SELECT MAX(log_id) AS logid From logbook WHERE log_id < (".$excrow.") AND equipment_id =".$resource." AND project_id=".$project." ";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $endlog = $dataReader->read();
        $sql1="SELECT log_id FROM logbook WHERE equipment_id =".$resource." AND project_id=".$project." ORDER BY log_id ASC";
        $command = $connection->createCommand($sql1);
        $dataReader = $command->query();
        $firstlog = $dataReader->read();
        $startreading=Logbook::findOne($firstlog['log_id']);
        $endreading=Logbook::findOne($endlog['logid']);
        if(!empty($startreading['worked_hours'])){
            $startread=$startreading['worked_hours'];
        }else{
            $startread=0;
        }
        if(!empty($endreading['worked_hours'])){
            $endread=$endreading['worked_hours'];
        }else{
            $endread=0;
        }
        $nohoursworked=$endread - $startread;
        //echo $nohoursworked;exit;
        $sql2 = "SELECT SUM(diesel) as dieseliss FROM logbook WHERE log_id < (".$excrow.") AND equipment_id =".$resource." AND project_id=".$project." ";
        //echo $sql;exit;
        $command = $connection->createCommand($sql2);
        $dataReader = $command->query();
        $issueddiesel = $dataReader->read();
        //echo $issueddiesel['dieseliss'];exit;
        if(!empty($endreading['worked_hours'])){
            $dslconsumed=$issueddiesel['dieseliss'] / $nohoursworked;
        }else{
            $dslconsumed=$issueddiesel['dieseliss'];
        }
        //echo $dslconsumed;exit;
        $avgratedsl=72.63;
        $dslcost=$dslconsumed * $avgratedsl;
        //echo $dslcost;exit;
        $resacnt=Resources::findOne($resource)->Resource_Acc_Id;
        $sql3="SELECT SUM(amount) as schdamount FROM voucher WHERE account_id=".$resacnt." AND sub_schedule=".$resource." ";
        //echo $sql3;
        $command = $connection->createCommand($sql3);
        $dataReader = $command->query();
        $data = $dataReader->read();
        //echo $data['schdamount'];
        if(!empty($endreading['worked_hours'])){
            $repaircost=$data['schdamount'] / $nohoursworked;
        }else{
            $repaircost=$data['schdamount'];
        }
        //echo $repaircost;
        $resourcecost=$dslcost + $repaircost;
        return $resourcecost;
    }

    public function actionCheckname()
    {
        if (isset($_POST['name'])):
            //echo $_POST['name'];exit;
            $connection = \Yii::$app->db;
            $sql = "SELECT COUNT(*) AS total FROM projects WHERE Name='" . $_POST['name'] . "'";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $data = $dataReader->read();
            if ($data['total'] > 0):
                return 'Yes';
            else:
                return 'No';
            endif;
        endif;
    }

