    public function actionScheduleactivity()
    {
        if (isset($_POST['workgroupid'])) {
            $connection = CActiveRecord::getDbConnection();
            $sqlqry = "SELECT activity_Id,process_Id,pro_estimate_id FROM pro_activities WHERE wg_Id='".$_POST['workgroupid']."'";
            $command1 = $connection->createCommand($sqlqry);
            $dataReader1 = $command1->query();
            $dataProvider1 = $dataReader1->readAll();
            if (count($dataProvider1) > 0){//checking for allready saved activities on selected workgroup
                $datarows='';
                foreach ($dataProvider1 AS $key1 => $data1){
                    $activityid = $data1['activity_Id'];
                    $processid = $data1['process_Id'];
                    if($processid==2){
                        $type="Project Setup";
                        $qry = "SELECT PS_Name AS activity FROM project_setup WHERE PS_Id='".$activityid."'";
                        // echo $qry;exit;
                    }elseif($processid==5){
                        $type="Construction";
                        $qry = "SELECT CO_Name AS activity FROM construction WHERE Construction_Id='".$activityid."'";
                    }
                    $command2 = $connection->createCommand($qry);
                    $dataReader2 = $command2->query();
                    $dataProvider2 = $dataReader2->read();
                    $sqlst = "SELECT COUNT(*) AS total,activity_Id FROM schedule_task WHERE Budgeted_Duration=0 AND End_Duration=0 AND activity_Id='" . $activityid . "'AND process_Id='".$processid."'AND wbs_id='".$_POST['workgroupid']."'";
                    $command = $connection->createCommand($sqlst);
                    $dataReader = $command->query();
                    $status = $dataReader->read();
                    $changestat = '';
                    if ($status['total'] == 0):
                        $changestat = 'Completed';
                    else:
                        $changestat = 'Not Completed';
                    endif;
                    $sqlqry2 = "SELECT activity_name FROM project_estimate WHERE project_estimate_Id='".$data1['pro_estimate_id']."'";
                    $command1 = $connection->createCommand($sqlqry2);
                    $dataReader1 = $command1->query();
                    $dataProvider1 = $dataReader1->read();
                    if($dataProvider1['activity_name']!=''){
                        $name = $dataProvider1['activity_name'];
                    }else{
                        $name = $dataProvider2['activity'];
                    }
                    $datarows .= '<tr>
                                        <td>' . $activityid . '</td>
                                        <td>' . $name . '</td>
                                        <td>'.$changestat.'</td>
                                        <input type="hidden" id="wbs" value="'.$_POST['workgroupid'].'">
