            }
            $arr = array('result' => $datarows, 'error' => 'No');
            echo json_encode($arr);

        }
    }

    public function actionCostingiows()
    {
        if (isset($_POST['workgroupid'])) {
            $connection = CActiveRecord::getDbConnection();
            $sql = "SELECT IOW_Id,Name,Unit,Quantity FROM itemofworks WHERE Workgroup_Id='" . $_POST['workgroupid'] . "' ORDER BY sortorder ASC ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $iows = $dataReader->readAll();
            $datarows = '';
            if (count($iows) > 0):
                foreach ($iows AS $iow):
                    $sqlst = "SELECT SUM(Price) AS totalcost FROM iowproducts WHERE IOW_Id='" . $iow['IOW_Id'] . "'";
                    $command = $connection->createCommand($sqlst);
                    $dataReader = $command->query();
                    $status = $dataReader->read();
                    if ($status['totalcost'] == '')
                        $totalcost = '0';
                    else
                        $totalcost = $status['totalcost'];
                    $datarows .= '<tr>
                                <td>' . $iow['IOW_Id'] . '</td>
                                <td>' . $iow['Name'] . '</td>
                                <td>' . $iow['Unit'] . '</td>
                                <td>' . $iow['Quantity'] . '</td>
                                <td>' . round($totalcost, 2) . '</td>
