    public function actionReportiow()
    {
        $report_id = $_POST['reportid'];
        $activityid = $_POST['activityid'];
        $projid = $_POST['projid'];
        $wbsactid=$_POST['wbsactid'];
        $connection = CActiveRecord::getDbConnection();
        $count = count($_POST['taskid']);
        $totalduration = 0;
        for ($i = 0; $i < $count; $i++) {
            $totalduration = $totalduration + $_POST['eduration'][$i];
            $taskid = $_POST['taskid'][$i];
            $actualdays = $_POST['eduration'][$i];
            // $reportid = $report_id;
            $sql2 = "UPDATE reporttasks SET actualduration='$actualdays' where taskid='$taskid' AND reportid='$report_id'";
            //echo $sql2;exit;
            $command = $connection->createCommand($sql2);
            $dataReader = $command->query();
        }
        $sqlfordates = "SELECT startdate FROM new_report WHERE activity_Id='$activityid' AND reportid='$report_id' ";
        $command = $connection->createCommand($sqlfordates);
        $dataReader = $command->query();
        $startdate = $dataReader->read();
        $starteddate = $startdate['startdate'];
        $enddate = date("Y-m-d");
        // var_dump($starteddate);
        // var_dump($enddate);
        // exit;
        $datediff=date_diff(new DateTime($starteddate),new DateTime($enddate));
        // echo $datediff->d;exit;
        $diff = $datediff->d;
        //echo $diff;exit;
        if($totalduration == $diff){


            $repquery = "SELECT reportid,totalduration FROM new_report WHERE wbs_activity_Id=".$wbsactid." AND activity_Id='".$activityid."' AND process_Id='".$_POST['processid']."' AND wbsid='".$_POST['wbsid']."' AND projid='".$projid."' AND status=1 ";
            //echo $repquery;exit;
            $command1 = $connection->createCommand($repquery);
            $dataReader1 = $command1->query();
            $report = $dataReader1->readAll();
            //echo count($report);exit;

            if(count($report)!=0){
                $totalofactual = 0;
                $count = 0;

                foreach($report AS $reportid){
                    // echo "tesst";exit;

                    $totalofactual+=  $reportid['totalduration'];
                    $count++;
                }
            }
            $averageactulal =  substr($totalofactual/$count, 0, 4);
            //echo $averageactulal;exit;
            /*$sql = "UPDATE schedule_activity SET duration='".$averageactulal."' WHERE actvity_id='$activityid' AND Project_Id='$projid' AND process_id='".$_POST['processid']."' AND wbs_id='".$_POST['wbsid']."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();*/

            //updating totalduration and status
            $sql = "UPDATE new_report SET totalduration='$totalduration',status='1',enddate='$enddate' WHERE wbs_activity_Id='$wbsactid' AND activity_Id='$activityid' AND reportid='$report_id' ";
            //echo $sql;exit;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $reportmodel=NewReport::model()->findByPk($report_id);
            $sql= "UPDATE new_report SET status='1',enddate='$enddate' WHERE projid='$reportmodel->projid' AND wbsid='$reportmodel->wbsid' AND wbs_activity_Id='$reportmodel->wbs_activity_Id' AND activity_Id='$reportmodel->activity_Id' AND process_Id='$reportmodel->process_Id' AND cycle='$reportmodel->cycle' ";
            //echo $sql;exit;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            // exit;
            $arr = array('error' => 'No');
        }
        else{
            // $arr = array('error' => 1);
            $exactdiff = $diff - $totalduration;
            $arr = array('result' => $exactdiff, 'error' => 1);
        }
        echo json_encode($arr);
    }
