    public function actionHolidaysearch()
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "SELECT id,Project_Id,date FROM gantt_holidays WHERE status='0' ";
        if ($_POST['Project_id'] == '0') {
            $sql .= " AND Project_Id='" . $_POST['Project_id'] . "'";
        } else {
            $sql .= " AND Project_Id IN ('" . $_POST['Project_id'] . "','0')";
        }
        if ($_POST['holidaydate'] != '') {
            $sql .= " AND date='" . $_POST['holidaydate'] . "'";
        }
        $sql .= "ORDER BY id ASC";
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $holidays = $dataReader->readAll();
        $table = '';
        if (count($holidays) > 0):

            foreach ($holidays AS $off) {

                if ($off['Project_Id'] == 0):
                    $project = 'For All Projects';
                else:
                    $project = Projects::model()->findByPk($off['Project_Id'])->Name;
                endif;
                $table .= '<tr id="holidayrow' . $off['id'] . '"><td>' . $off['id'] . '</td><td>' . $project . '</td><td>' . $off['date'] . '</td><td><button title="Delete Holiday" id="deletholidaybutton' . $off['id'] . '" value="' . $off['id'] . '" class="btn btn-primary deletholidaybutton" type="button"> <span class="glyphicon glyphicon-trash"></span></button></td></tr>';
                $project = '';
            }
        else:
            $table = '<tr><td colspan="4">No Holidays Found</td></tr>';
        endif;
        $arr = array('result' => $table, 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionDeleteholiday()
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "DELETE FROM gantt_holidays WHERE id='" . $_POST['holidayid'] . "'";
        $command = $connection->createCommand($sql);
        if ($dataReader = $command->query()):
            $arr = array('Id' => $_POST['holidayid'], 'error' => 'No');
            echo json_encode($arr);
        else:
            $arr = array('Id' => $_POST['holidayid'], 'error' => 'Yes', 'errortext' => 'Can not Delete Holiday with ID ' . $_POST['holidayid'] . '.');
            echo json_encode($arr);
        endif;
    }

    private function formatDate($date)
    {
        $dateonly = explode(' ', $date);
        $newdate = explode('-', $dateonly[0]);
        $formateddate = $newdate[2] . '-' . $newdate[1] . '-' . $newdate[0];
        return $formateddate;
    }

    /**
     * Returns the data model based on the primary key given in the GET variable.
     * If the data model is not found, an HTTP exception will be raised.
     * @param integer $id the ID of the model to be loaded
     * @return projects the loaded model
     * @throws CHttpException
     */
    public function loadModel($id)
    {
        $model = Projects::model()->findByPk($id);
        if ($model === null)
            throw new CHttpException(404, 'The requested page does not exist.');
        return $model;
    }

    public function actionCheckholiday()
    {
        $connection = CActiveRecord::getDbConnection();
        $date = explode('/', $_POST['date']);
        $checkindate = $date[2] . '-' . $date[0] . '-' . $date[1];
        $sql = "SELECT COUNT(*) AS total FROM gantt_holidays WHERE date='" . $checkindate . "' AND Project_Id='" . $_POST['Project_Id'] . "'";
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $isholiday = $dataReader->read();
        $formated = date('j-m-Y', strtotime($date[1] . '-' . $date[0] . '-' . $date[2]));
        if ($isholiday['total'] > 0) {
            $sql = "DELETE FROM  gantt_holidays WHERE date='" . $checkindate . "' AND Project_Id='" . $_POST['Project_Id'] . "'";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $arr = array('action' => 'remove', 'date' => $formated);
        } else {
            $sql = "INSERT INTO gantt_holidays (date,Project_Id) VALUES ('" . $checkindate . "','" . $_POST['Project_Id'] . "')";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $arr = array('action' => 'add', 'date' => $formated);
        }
        echo json_encode($arr);
        // echo $formated;
    }

    public function actionDeleteLinks($id)
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "delete a.* FROM gantt_links a INNER JOIN itemofworks b on (a.source=b.IOW_Id or a.target=b.IOW_Id) WHERE b.Project_Id='$id'";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $sql1 = "SELECT  IOW_Id,start_date,end_date,duration FROM itemofworks WHERE Project_Id ='$id' ORDER BY start_date ASC ";
        $command = $connection->createCommand($sql1);
        $dataReader = $command->query();
        $date = $dataReader->readAll();
        $startdate = $date[0]['start_date'];
        $datexplode = explode('-', $startdate);
        foreach ($date AS $actdate):
            $endday = $datexplode[2] + $actdate['duration'];
            $endate = date('Y-m-d', mktime(0, 0, 0, $datexplode[1], $endday, $datexplode[0]));
            $sql2 = "UPDATE itemofworks SET start_date='$startdate',end_date='$endate' WHERE Project_Id='$id' AND IOW_Id='" . $actdate['IOW_Id'] . "'";

            $command = $connection->createCommand($sql2);
            $dataReader = $command->query();
        endforeach;

        $this->redirect(array('GanttChart', 'id' => $id));
    }

