    public function actionEdit()
    {
          $projectid=$_POST['projectid'];
          $connection = \Yii::$app->db;
          $sql = "SELECT * FROM projects where Project_Id=".$projectid."";
          $command = $connection->createCommand($sql);
          $dataReader = $command->query();
          $project = $dataReader->read();
          if (isset($_POST['projectid'])) {
            /*$startdate = explode("-",$_POST['start_date']);
            $start_date = $startdate[2]."-".$startdate[1]."-".$startdate[0]." 00:00:00";*/

            $accntsitems=AccountsItem::find()->where(['projectid' =>$projectid])->all();

            if($accntsitems){

                foreach($accntsitems as $accntsitem):

                    $accntsitem->projectid = 0;
                    $accntsitem->save(false);

                endforeach;

            }

            $sql = "UPDATE accounts_item set projectid='" . $projectid . "' where id='" . $_POST['cashaccount'] . "' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $sql = "UPDATE accounts_item set projectid='" . $projectid . "' where id='" . $_POST['bankaccount'] . "' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
           
            $location = addslashes(trim($_POST['location'] ?? ''));
            $sql="UPDATE projects SET Name='".$_POST['projectname']."',start_date='".$_POST['startdate']."',end_date='".$_POST['enddates']."',duration='".$_POST['duration']."',project_value='".$_POST['projectvalue']."',client_name='".$_POST['clientname']."',location='".$location."',wrkhours='".$_POST['wrkhrs']."' where Project_Id=".$projectid." ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();

            $uid = Yii::$app->user->Id; 
            $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
            if($projuser){
                $projuser->projectid = $projectid;
                $projuser->save(false);
            }
            else{
                $ProjuserSelection = new ProjuserSelection();
                $ProjuserSelection->userid = $uid;
                $ProjuserSelection->projectid = $projectid;
                $ProjuserSelection->save(false);
            }

          }
          $uploadDir = Yii::getAlias('@webroot') . '/uploads/projects/';
          $allowed = ['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'];
          $uid = Yii::$app->user->Id;
          foreach (['project_documents' => 'documents', 'project_correspondence' => 'correspondence'] as $field => $type) {
              if (!empty($_FILES[$field]['name'][0])) {
                  foreach ($_FILES[$field]['name'] as $i => $origName) {
                      $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                      if (!in_array($ext, $allowed)) continue;
                      $storedName = uniqid('pf_') . '.' . $ext;
                      move_uploaded_file($_FILES[$field]['tmp_name'][$i], $uploadDir . $storedName);
                      $connection->createCommand("INSERT INTO project_files (project_id, file_type, filename, original_name, uploaded_by) VALUES (:pid,:type,:fn,:on,:uid)")
                          ->bindValues([':pid' => $projectid, ':type' => $type, ':fn' => $storedName, ':on' => $origName, ':uid' => $uid])
                          ->execute();
                  }
              }
          }

          $arr = array('error' => 'No', 'Name' => $_POST['projectname']);
          return json_encode($arr);
    }


