    public function actionSearchprojectfiles()
    {
        $connection = \Yii::$app->db;
        $type     = isset($_POST['file_type']) ? $_POST['file_type'] : 'documents';
        $subject  = isset($_POST['subject'])   ? $_POST['subject']   : '';
        $ref      = isset($_POST['ref'])       ? $_POST['ref']       : '';
        $date     = isset($_POST['date'])      ? $_POST['date']      : '';
        $keywords = isset($_POST['keywords'])  ? $_POST['keywords']  : '';

        $conditions = ["pf.file_type = :type"];
        $params = [':type' => $type];

        if ($subject !== '') {
            $conditions[] = "pf.original_name LIKE :subject";
            $params[':subject'] = '%' . $subject . '%';
        }
        if ($keywords !== '') {
            $conditions[] = "(pf.original_name LIKE :keywords OR p.Name LIKE :keywords2)";
            $params[':keywords']  = '%' . $keywords . '%';
            $params[':keywords2'] = '%' . $keywords . '%';
        }
        if ($ref !== '') {
            $conditions[] = "p.Name LIKE :ref";
            $params[':ref'] = '%' . $ref . '%';
        }
        if ($date !== '') {
            $conditions[] = "DATE(pf.uploaded_at) = :date";
            $params[':date'] = $date;
        }

        $where = implode(' AND ', $conditions);
        $sql = "SELECT pf.id, pf.filename, pf.original_name,
                       DATE_FORMAT(pf.uploaded_at, '%d %b %Y') AS uploaded_at,
                       p.Name AS project_name
                FROM project_files pf
                JOIN projects p ON p.Project_Id = pf.project_id
                WHERE $where
                ORDER BY pf.uploaded_at DESC
                LIMIT 100";

        $files = $connection->createCommand($sql)->bindValues($params)->queryAll();
        return json_encode(['files' => $files, 'error' => 'No']);
    }

    public function actionDeleteprojectfile()
    {
        $fileId = (int)$_POST['fileid'];
        $connection = \Yii::$app->db;
        $row = $connection->createCommand("SELECT filename FROM project_files WHERE id=:id")
            ->bindValue(':id', $fileId)->queryOne();
        if ($row) {
            $path = Yii::getAlias('@webroot') . '/uploads/projects/' . $row['filename'];
            if (file_exists($path)) unlink($path);
            $connection->createCommand("DELETE FROM project_files WHERE id=:id")
                ->bindValue(':id', $fileId)->execute();
            return json_encode(['error' => 'No']);
        }
        return json_encode(['error' => 'Yes']);
    }

    public function actionGetprojectfiles()
    {
        $projectId = (int)($_POST['project_id'] ?? 0);
        $files = \Yii::$app->db->createCommand(
            'SELECT id, filename, original_name, file_type FROM project_files WHERE project_id = :pid ORDER BY uploaded_at DESC',
            [':pid' => $projectId]
        )->queryAll();
        return json_encode(['error' => 'No', 'files' => $files]);
    }

    public function actionUploadprojectfiles()
    {
        try {
            $projectId = (int)($_POST['project_id'] ?? 0);
            $fileType  = ($_POST['file_type'] ?? '') === 'correspondence' ? 'correspondence' : 'documents';
            $field     = $fileType === 'documents' ? 'pf_documents' : 'pf_correspondence';

            if (!$projectId) {
                return json_encode(['error' => 'Yes', 'errortext' => 'No project selected']);
            }

            $uploadDir = Yii::getAlias('@webroot') . '/uploads/projects/';
            if (!is_dir($uploadDir)) mkdir($uploadDir, 0755, true);
            $allowed = ['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'];

            if (!empty($_FILES[$field]['name'][0])) {
                foreach ($_FILES[$field]['name'] as $i => $origName) {
                    $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                    if (!in_array($ext, $allowed)) continue;
                    $storedName = uniqid('pf_') . '.' . $ext;
                    if (move_uploaded_file($_FILES[$field]['tmp_name'][$i], $uploadDir . $storedName)) {
                        \Yii::$app->db->createCommand()->insert('project_files', [
                            'project_id'    => $projectId,
                            'file_type'     => $fileType,
                            'filename'      => $storedName,
                            'original_name' => $origName,
                            'uploaded_at'   => date('Y-m-d H:i:s'),
                        ])->execute();
                    }
                }
            }

            $files = \Yii::$app->db->createCommand(
                'SELECT id, filename, original_name, file_type FROM project_files WHERE project_id = :pid ORDER BY uploaded_at DESC',
                [':pid' => $projectId]
            )->queryAll();
            return json_encode(['error' => 'No', 'files' => $files]);
        } catch (\Exception $e) {
            return json_encode(['error' => 'Yes', 'errortext' => $e->getMessage()]);
        }
    }

