    {
        $db = \Yii::$app->db;
        $projects = $db->createCommand(
            "SELECT Project_Id AS id, Name AS name FROM projects WHERE status='0' AND Project_Delete_Status='0' ORDER BY Name ASC"
        )->queryAll();
        echo json_encode(['error' => 'No', 'projects' => $projects]);
    }

    public function actionPdoclist()
    {
        $db = \Yii::$app->db;

        $where = ['1=1'];
        $params = [];

        $projectId = (int)($_POST['project_id'] ?? 0);
        if ($projectId) {
            $where[] = 'pf.project_id = :pid';
            $params[':pid'] = $projectId;
        }

        $addressee = trim($_POST['addressee'] ?? '');
        if ($addressee !== '') {
            $where[] = 'pf.addressee LIKE :addr';
            $params[':addr'] = '%' . $addressee . '%';
        }

        $subject = trim($_POST['subject'] ?? '');
        if ($subject !== '') {
            $where[] = 'pf.subject LIKE :subj';
            $params[':subj'] = '%' . $subject . '%';
        }

        $dateFilter = trim($_POST['date_filter'] ?? '');
        if ($dateFilter !== '') {
            $where[] = 'DATE(pf.uploaded_at) = :dfilter';
            $params[':dfilter'] = $dateFilter;
        }

        $fileType = trim($_POST['file_type'] ?? '');
        if ($fileType !== '') {
            $where[] = 'pf.file_type = :ftype';
            $params[':ftype'] = $fileType;
        }

        $whereStr = implode(' AND ', $where);

        $files = $db->createCommand(
            "SELECT pf.id, pf.filename, pf.original_name, pf.file_type,
                    COALESCE(pf.addressee,'') AS addressee,
                    COALESCE(pf.subject,'') AS subject,
                    DATE_FORMAT(pf.uploaded_at,'%d %b %Y') AS uploaded_at,
                    p.Name AS project_name
             FROM project_files pf
             JOIN projects p ON p.Project_Id = pf.project_id
             WHERE $whereStr
             ORDER BY pf.uploaded_at DESC
             LIMIT 500",
            $params
        )->queryAll();

        echo json_encode(['error' => 'No', 'files' => $files]);
    }

    public function actionPdocupload()
    {
        $uid = \Yii::$app->user->id;
        $pid = (int)($_POST['project_id'] ?? 0);
        if (!$pid) { echo json_encode(['error'=>'Yes','errortext'=>'No project selected.']); return; }

        $type = trim($_POST['file_type'] ?? '');
        if (!in_array($type, ['documents','correspondence'])) { echo json_encode(['error'=>'Yes','errortext'=>'Invalid file type.']); return; }

        $addr = ($type === 'correspondence') ? trim($_POST['addressee'] ?? '') : '';
        $subj = ($type === 'correspondence') ? trim($_POST['subject']   ?? '') : '';

        $uploadDir = \Yii::getAlias('@webroot') . '/uploads/projects/';
        $allowed   = ['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'];
        $db        = \Yii::$app->db;
        $saved     = 0;

        $field = ($type === 'correspondence') ? 'project_correspondence' : 'project_documents';
        if (!empty($_FILES[$field]['name'][0])) {
            foreach ($_FILES[$field]['name'] as $i => $origName) {
                $ext = strtolower(pathinfo($origName, PATHINFO_EXTENSION));
                if (!in_array($ext, $allowed)) continue;
                $storedName = uniqid('pf_') . '.' . $ext;
                if (move_uploaded_file($_FILES[$field]['tmp_name'][$i], $uploadDir . $storedName)) {
                    $db->createCommand("INSERT INTO project_files (project_id, file_type, addressee, subject, filename, original_name, uploaded_by) VALUES (:pid,:type,:addr,:subj,:fn,:on,:uid)")
                        ->bindValues([':pid'=>$pid,':type'=>$type,':addr'=>$addr,':subj'=>$subj,':fn'=>$storedName,':on'=>$origName,':uid'=>$uid])
                        ->execute();
                    $saved++;
                }
            }
        }

        if ($saved === 0) { echo json_encode(['error'=>'Yes','errortext'=>'No valid file uploaded.']); return; }
        echo json_encode(['error'=>'No','saved'=>$saved]);
    }

    public function actionDuplicate(){
        $connection = \Yii::$app->db;
        $projectid = $_POST['projectid'];

        //------Copy Project------
        $exist_project  = Projects::find()->where(['Project_Id' => $projectid])->one();
        $exist_project_name = $exist_project['Name'];
        $projNameCnt    = 1;
        while ($exist_project) {
            $projName = $exist_project_name.' '.$projNameCnt;
            $exist_project = Projects::find()->where(['Name' => $projName])->one();
            $projNameCnt++;
        }

        $sql     =  "CREATE TEMPORARY TABLE tmp_project SELECT * FROM projects WHERE Project_Id=".$projectid.";
                     ALTER TABLE tmp_project DROP COLUMN `Project_Id`;
                     UPDATE tmp_project set  Name = '".$projName."';
                     INSERT INTO projects SELECT 0, tmp_project.* FROM tmp_project;
                     DROP TEMPORARY TABLE tmp_project;";
        $command =  $connection->createCommand($sql)->execute();

        $newProject     = Projects::find()->orderBy(['Project_Id' => SORT_DESC])->one();
        $newProjectId   = $newProject->Project_Id;
        
        //---------------------------------------

        //------Copy Item of work, Group----------------

        $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM workgroups_new WHERE Project_Id=".$projectid.";
                     ALTER TABLE tmp_table DROP COLUMN `Workgroup_Id`;
                     UPDATE tmp_table set  Project_Id = ".$newProjectId.", parent = ".$newProjectId.";
                     INSERT INTO workgroups_new SELECT 0, tmp_table.* FROM tmp_table;
                     DROP TEMPORARY TABLE tmp_table;";
        $command =  $connection->createCommand($sql)->execute();


        $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM wbsscheduleitems WHERE projectId=".$projectid.";
                     ALTER TABLE tmp_table DROP COLUMN `scheduleitem_id`;
                     UPDATE tmp_table set  projectId = ".$newProjectId.";
                     INSERT INTO wbsscheduleitems SELECT 0, tmp_table.* FROM tmp_table;
                     DROP TEMPORARY TABLE tmp_table;";
        $command =  $connection->createCommand($sql)->execute();

        if($workGroups = WorkgroupsNew::find()->where(['Project_Id' => $newProjectId])->all()){
            foreach ($workGroups as $key => $workGroup) {
                $workGroupOld   = WorkgroupsNew::find()->where(['Project_Id' => $projectid, 'Name' => $workGroup->Name])->one();
                $wbsSchItem     = Wbsscheduleitems::find()->where(['projectId' => $newProjectId, 'wbsid' => $workGroupOld->Workgroup_Id])->one();
                if($wbsSchItem){
                    $wbsSchItem->wbsid = $workGroup->Workgroup_Id;
                    $wbsSchItem->save(false);
                }
            }
        }

        $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM iow_groups WHERE project_id=".$projectid.";
                     ALTER TABLE tmp_table DROP COLUMN `id`;
                     UPDATE tmp_table set  project_id = ".$newProjectId.";
                     INSERT INTO iow_groups SELECT 0, tmp_table.* FROM tmp_table;
                     DROP TEMPORARY TABLE tmp_table;";
        $command =  $connection->createCommand($sql)->execute();

        if($iowGroups = IowGroup::find()->where(['project_id' => $newProjectId])->all()){
            foreach ($iowGroups as $key => $iowGroupNew) {
                $iowGroupOld    = IowGroup::find()->where(['project_id' => $projectid, 'name' => $iowGroupNew->name])->one();
                $sql     =  "UPDATE workgroups_new SET iowGroupid='".$iowGroupNew->id."' 
                             WHERE project_id='".$newProjectId."' AND iowGroupid=".$iowGroupOld->id;
                $connection->createCommand($sql)->execute();
            }
        }
        //---------------------------------------

        //-----Copy Activities ----------------

        $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM workgroup_activities_new WHERE project_Id=".$projectid.";
                     ALTER TABLE tmp_table DROP COLUMN `id`;
                     UPDATE tmp_table set  project_Id = ".$newProjectId.";
                     INSERT INTO workgroup_activities_new SELECT 0, tmp_table.* FROM tmp_table;
                     DROP TEMPORARY TABLE tmp_table;";
        $command =  $connection->createCommand($sql)->execute();

        if($workGroups = WorkgroupsNew::find()->where(['Project_Id' => $newProjectId])->all()){
            foreach ($workGroups as $key => $workGroup) {
                $workGroupOld   =   WorkgroupsNew::find()->where(['Project_Id' => $projectid, 'Name' => $workGroup->Name])->one();
                $sql            =  "UPDATE workgroup_activities_new SET wbs_id='".$workGroup->Workgroup_Id."' 
                                    WHERE project_id='".$newProjectId."' AND wbs_id=".$workGroupOld->Workgroup_Id;
                $connection->createCommand($sql)->execute();
            }
        }

        $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM scheduleactivities WHERE projectId=".$projectid." AND status = 0;
                     ALTER TABLE tmp_table DROP COLUMN `id`;
                     UPDATE tmp_table set projectId = ".$newProjectId.", act_start_date = NULL;
                     INSERT INTO scheduleactivities SELECT 0, tmp_table.* FROM tmp_table;
                     DROP TEMPORARY TABLE tmp_table;";
        $command =  $connection->createCommand($sql)->execute();

        if($workgroupActivities = WorkgroupActivitiesNew::find()->where(['Project_Id' => $newProjectId])->all()){
            foreach ($workgroupActivities as $key => $workgroupActivity) {
                $workGroupActOld = WorkgroupActivitiesNew::find()->where(['Project_Id'=>$projectid,'activity_Name'=>$workgroupActivity->activity_Name])->one();
                if($workGroupActOld->schedule){
                    $scheduleItem    = Scheduleactivities::find()->where(['projectId' => $newProjectId,'activity_id' => $workGroupActOld->id])->one();
                    $scheduleItem->activity_id = $workgroupActivity->id;
                    $scheduleItem->save(false);
                }
            }
        }

        if($wbsSchItems = Wbsscheduleitems::find()->where(['projectId' => $newProjectId])->all()){
            foreach ($wbsSchItems as $key => $wbsSchItem) {
                $wbsSchItemOld  =   Wbsscheduleitems::find()->where(['projectId' => $projectid, 'name' => $wbsSchItem->name])->one();
                $sql            =   "UPDATE scheduleactivities SET scheduleitem_id='".$wbsSchItem->scheduleitem_id."' 
                                    WHERE projectId='".$newProjectId."' AND scheduleitem_id=".$wbsSchItemOld->scheduleitem_id;
                $connection->createCommand($sql)->execute();
            }
        }
        //---------------------------------------

        //--------Copy Estimate---------
        if($workGrpActivities = WorkgroupActivitiesNew::find()->where(['Project_Id' => $newProjectId])->all()){
            foreach ($workGrpActivities as $key => $workGrpActivity) {
                $workGrpActOld = WorkgroupActivitiesNew::find()->where(['Project_Id'=>$projectid,'activity_Name'=>$workGrpActivity->activity_Name])->one();
                $tempTable = "tmp_table_".$key;
                $sql     =  "CREATE TEMPORARY TABLE ".$tempTable." SELECT * FROM pricing_estimate_new 
                             WHERE activity_id = ".$workGrpActOld->id." AND project_id = ".$projectid." AND pricing_status = 0;
                             ALTER TABLE ".$tempTable." DROP COLUMN `pricing_estimate_Id`;
                             UPDATE ".$tempTable." set project_id = ".$newProjectId.", activity_id = ".$workGrpActivity->id.", activity_qty = 0;
                             INSERT INTO pricing_estimate_new SELECT 0, ".$tempTable.".* FROM ".$tempTable.";
                             DROP TEMPORARY TABLE ".$tempTable.";";
                $command =  $connection->createCommand($sql)->execute();

                $tempTable = "tmp_table_est".$key;
                $sql     =  "CREATE TEMPORARY TABLE ".$tempTable." SELECT * FROM pricing_estimate_resources_new 
                             WHERE activity_id = ".$workGrpActOld->id." AND project_id = ".$projectid." AND pricing_status = 0;
                             ALTER TABLE ".$tempTable." DROP COLUMN `pricing_resourceid`;
                             UPDATE ".$tempTable." set project_id = ".$newProjectId.", activity_Id = ".$workGrpActivity->id.";
                             INSERT INTO pricing_estimate_resources_new SELECT 0, ".$tempTable.".* FROM ".$tempTable.";
                             DROP TEMPORARY TABLE ".$tempTable.";";
                $command =  $connection->createCommand($sql)->execute();
            }
        }

        //---------------------------------------

        //---- Copy Tasks------------------
        $taskIdMapArr = [];

        if($scheduleActivities = Scheduleactivities::find()->where(['projectId' => $newProjectId, 'status' => 0])->all()){
            foreach ($scheduleActivities as $key => $scheduleActivity) {
                $scheduleActOld  = Scheduleactivities::find()->where(['projectId' => $projectid, 'name' => $scheduleActivity->name, 'status' => 0])->one();

                $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM schedule_activity_new 
                             WHERE Project_Id =".$projectid." AND actvity_id = ".$scheduleActOld->id.";
                             ALTER TABLE tmp_table DROP COLUMN `id`;
                             UPDATE tmp_table set Project_Id = ".$newProjectId.", actvity_id = $scheduleActivity->id;
                             INSERT INTO schedule_activity_new SELECT 0, tmp_table.* FROM tmp_table;
                             DROP TEMPORARY TABLE tmp_table;";
                $command =  $connection->createCommand($sql)->execute();

                $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM tasks_new WHERE activity_Id =".$scheduleActOld->id." AND status = 0;
                             ALTER TABLE tmp_table DROP COLUMN `task_Id`;
                             UPDATE tmp_table set activity_Id = ".$scheduleActivity->id.";
                             INSERT INTO tasks_new SELECT 0, tmp_table.* FROM tmp_table;
                             DROP TEMPORARY TABLE tmp_table;";
                $command =  $connection->createCommand($sql)->execute();

                $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM schedule_task_new 
                             WHERE activity_Id =".$scheduleActOld->id.";
                             ALTER TABLE tmp_table DROP COLUMN `id`;
                             UPDATE tmp_table set activity_Id = ".$scheduleActivity->id.";
                             INSERT INTO schedule_task_new SELECT 0, tmp_table.* FROM tmp_table;
                             DROP TEMPORARY TABLE tmp_table;";
                $command =  $connection->createCommand($sql)->execute();

                if($tasks = TasksNew::find()->where(['activity_Id' => $scheduleActivity->id])->all()){
                    foreach ($tasks as $task) {
                        $taskOld =  TasksNew::find()->where(['activity_Id' => $scheduleActOld->id, 'Name' => $task->Name, 'status' => 0])->one();

                        if($scheduleTaskNew = ScheduleTaskNew::find()->where(['activity_Id'=>$scheduleActivity->id, 'task_Id' => $taskOld->task_Id])->one()){
                            $scheduleTaskNew->task_Id = $task->task_Id;
                            $scheduleTaskNew->save(false);

                            $taskIdMapArr[$taskOld->task_Id] = $task->task_Id;
                        }
                    }
                }
            }
        }
        //---------------------------------------

        //--------Update Estimate---------
        $estResources   = PricingEstimateResourcesNew::find()->where(['project_id' => $newProjectId])->all();
        if($estResources){
            foreach ($estResources as $estResource) {
                if($estResource->task_ids){
                    $taskIdArr = explode(",", $estResource->task_ids);
                    $newTaskIdArr = [];
                    foreach ($taskIdArr as $taskId) {
                        $newTaskIdArr[] = $taskIdMapArr[$taskId];
                    }
                    $estResource->task_ids = implode(",", $newTaskIdArr);
                    $estResource->save(false);
                }
            }
        }
        //---------------------------------------


        //---- Copy Relationships------------------

        $sql     =  "CREATE TEMPORARY TABLE tmp_table SELECT * FROM activity_relations WHERE projectId =".$projectid." AND status = 0;
                     ALTER TABLE tmp_table DROP COLUMN `id`;
                     UPDATE tmp_table set projectId = ".$newProjectId.";
                     INSERT INTO activity_relations SELECT 0, tmp_table.* FROM tmp_table;
                     DROP TEMPORARY TABLE tmp_table;";
        $command =  $connection->createCommand($sql)->execute();

        if($activityRelations = ActivityRelations::find()->where(['projectId' => $newProjectId])->all()){
            foreach ($activityRelations as $key => $activityRelation) {
                $schActPre      = Scheduleactivities::findOne($activityRelation->precedent_activity);
                $schActPreNew   = Scheduleactivities::find()->where(['projectId' => $newProjectId, 'name' => $schActPre->name, 'status' => 0])->one();

                $schActDep      = Scheduleactivities::findOne($activityRelation->dependent_activity);
                $schActDepNew   = Scheduleactivities::find()->where(['projectId' => $newProjectId, 'name' => $schActDep->name, 'status' => 0])->one();

                $activityRelation->precedent_schedule_item  = $schActPreNew->scheduleitem_id;
                $activityRelation->precedent_activity       = $schActPreNew->id;
                $activityRelation->dependent_schedule_item  = $schActDepNew->scheduleitem_id;
                $activityRelation->dependent_activity       = $schActDepNew->id;
                $activityRelation->save(false);
            }
        }
        //---------------------------------------

      $arr = array('error' => 'No');
      return json_encode($arr);

    }


    public function actionUpdatesave()
    {
         $projectid=$_POST['projectid'];
          $connection = \Yii::$app->db;
          $sql = "SELECT * FROM projects where Project_Id=".$projectid."";
          //echo $sql;exit;
          $command = $connection->createCommand($sql);
          $dataReader = $command->query();
          $project = $dataReader->read();
          
            $prjname=$project['Name'];
            $strtdate=date("Y-m-d", strtotime($project['start_date']));
            $endddate=date("Y-m-d", strtotime($project['end_date']));
            $durat=$project['duration'];
            $prvalue=$project['project_value'];
            $clientnamesss=$project['client_name'];
            $wrkhrss=$project['wrkhours'];

            $cashacnts = AccountsItem::find()->where(['account_type'=> 1])->orderBy(['name' => SORT_ASC])->all();

            $cashaccntrow = '<option value="0">Select Account</option>';

            foreach($cashacnts AS $accounts):
                if($accounts->projectid==$projectid){
                    $cashselected = 'selected';
                }
                else{
                    $cashselected = '';
                }
                $cashaccntrow.= "<option value='".$accounts->id."' ".$cashselected.">".$accounts->name."</option>";
            endforeach;

            $bankacnts = AccountsItem::find()->where(['account_type'=> 2])->orderBy(['name' => SORT_ASC])->all();

            $bankaccntrow = '<option value="0">Select Account</option>';

            foreach($bankacnts AS $accounts):
                if($accounts->projectid==$projectid){
                    $bankselected = 'selected';
                }
                else{
                    $bankselected = '';
                }
                $bankaccntrow.= "<option value='".$accounts->id."' ".$bankselected.">".$accounts->name."</option>";
            endforeach;
          
          $files = $connection->createCommand("SELECT id, file_type, filename, original_name FROM project_files WHERE project_id=:pid")
              ->bindValue(':pid', $projectid)
              ->queryAll();
          $arr = array('prjname'=>$prjname,'strtdate'=>$strtdate,'endddate'=>$endddate,'durat'=>$durat,'prvalue'=>$prvalue,'clientnamesss'=>$clientnamesss,'location'=>$project['location'] ?? '','wrkhrss'=>$wrkhrss,'cashrow'=>$cashaccntrow,'bankrow'=>$bankaccntrow,'files'=>$files,'error' => 'No');
          return json_encode($arr);
    }

    public function actionDeactivateproject()
    {

        if (isset($_POST['projectid'])):
            $connection = \Yii::$app->db;
            $sql2 = "UPDATE projects SET favourite='0' WHERE Project_Id='".$_POST['projectid']."'";

            $command = $connection->createCommand($sql2);
            $dataReader = $command->query();

            $model = Projects::findOne($_POST['projectid']);
            $model->Project_Delete_Status = 1;
            if ($model->save(false)):


                $arr = array('Id' => $_POST['projectid'], 'error' => 'No');
                return  json_encode($arr);
            else:
                $arr = array('Id' => $_POST['projectid'], 'error' => 'Yes', 'errortext' => 'Can not Deactivate Project with ID ' . $_POST['projectid'] . '.');
                return json_encode($arr);
            endif;
        endif;
    }

