    public function actionBillsqtyiow()
    {
        $iows=IowWbs::model()->findAll(array('condition'=>'Project_Id='.$_POST['projectid'].' ','order'=>'sortorder ASC, iow_wbs_id ASC, Name ASC'));
        $datarows = '<tr><th>IOW</th>
                                <th>Resource Type</th>
                                <th>Sl No</th>
                                <th>Resource Name</th>
                                <th>Unit</th>
                                <th>Quantity</th>
                                <th>Rate</th>
                                <th>Amount</th>
                     </tr>';
        $iowtotal=0;
        foreach($iows AS $iow):
            $wbsactivities=IowWbsActivities::model()->findAll(array('condition'=>'wbs_id='.$iow['iow_wbs_id'].' ','order'=>'sortorder ASC'));
            //$dataProvider = PricingEstimate::model()->findAll(array('condition'=>'project_Id='.$_POST['projectid'].' AND process_Id='.$resgroup['Resource_group_Id'].' AND activity_qty!=0'));
            if(count($wbsactivities) > 0):
                $datarows .= '<tr> <td colspan="8"><b>' . $iow['Name'] . '</b></td></tr>';
                $iowrows='';
                $wbstotal=0;
                $wbsids='';
                $processids='';
                foreach($wbsactivities AS $key=>$wbsactivity):
                    if($key==0):
                        $wbsids.=$wbsactivity['activity_Id'];
                        $processids.=$wbsactivity['process_Id'];
                    else:
                        $wbsids.=','.$wbsactivity['activity_Id'];
                        $processids.=','.$wbsactivity['process_Id'];
                    endif;
                endforeach;
                //echo $wbsids;exit;
                $estresources=PricingEstimateResources::model()->findAll(array('condition'=>'project_id='.$_POST['projectid'].' AND est_activity_Id IN ('.$wbsids.') AND process_Id IN ('.$processids.')','group'=>'resourcetype_Id','order'=>'resourcetype_Id ASC'));
                foreach($estresources AS $estresource):
                    $resources=PricingEstimateResources::model()->findAll(array('condition'=>'project_id='.$_POST['projectid'].' AND est_activity_Id IN ('.$wbsids.') AND process_Id IN ('.$processids.') AND resourcetype_Id='.$estresource['resourcetype_Id'].''));
                    $resourcerow='';
                    $resourcetotal=0;
                    foreach($resources AS $key=>$resource):
                        $restype = Resourcetype::model()->findByPk($resource['resourcetype_Id']);
                        $resdetails = Resources::model()->findByPk($resource['resource_Id']);
                        $activitydetails=IowEstimate::model()->find(array('condition'=>'project_Id='.$_POST['projectid'].' AND iow_id='.$iow['iow_wbs_id'].' AND activity_Id='.$resource['est_activity_Id'].' '));
                        $pricingest=PricingEstimate::model()->find(array('condition'=>'project_Id='.$_POST['projectid'].' AND est_activity_Id='.$resource['est_activity_Id'].' '));
                        //$resourcerow .= '<tr><td></td><td></td><td colspan="6"></td></tr>';
                        if($activitydetails['activity_qty']==0):
                            $estqty=$pricingest['activity_qty'];
                        else:
                            $estqty=$activitydetails['activity_qty'];
                        endif;
                        $quantity=$estqty * $resource['quantity'];
                        $amount=$quantity * $resource['rate'];
                        if($quantity!=0):
                            $resourcerow .= "<tr>
                                    <td></td>
                                    <td>".$restype->Name."</td>
                                    <td>" . ($key + 1) . "</td>
                                    <td>" . $resdetails['Name'] . "</td>
                                    <td>" . $resdetails['Unit'] . "</td>
                                    <td>" . number_format($quantity, 2) . "</td>
                                    <td>" . number_format($resource['rate'], 2) . "</td>
                                    <td>" . number_format($amount, 2) . "</td></tr>";
                        endif;
                        $resourcetotal=$resourcetotal + $amount;
                    endforeach;

                    $resourcerow.='<tr><td></td><td colspan="2">Total:</td><td colspan="5" style="text-align: right"><b>' . number_format($resourcetotal, 2) . '</b></td></tr>';
                    $wbstotal=$wbstotal + $resourcetotal;
                    $iowrows.=$resourcerow;
                endforeach;
                $datarows.=$iowrows;
                $iowtotal=$iowtotal + $wbstotal;
                $datarows .= '<tr><td colspan="3">Group Total:</td><td colspan="5" style="text-align: right"><b>' . number_format($wbstotal, 2) . '</b></td></tr>';
            endif;
        endforeach;
        $arr = array('result' => $datarows, 'error' => 'No');

        echo json_encode($arr);
    }
