        $iows = itemofworks::model()->findAll(array("condition" => "Project_Id = '".$_POST['projectid']. "' AND start_date<'".$startdate."' AND end_date>'".$enddate."'"));
        $ar = array("Projectid" => $_POST['projectid']);
        $str = http_build_query($ar);
