                        <td>'.$this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d', strtotime('+1 month'))).'</td>
                        <td>'.$this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d', strtotime('+2 month'))).'</td>
                        <td>'.$this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d', strtotime('+3 month'))).'</td>
                        </tr>';
            $total1=$total1 + ($this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d')));
            $total2=$total2 + ($this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d', strtotime('+1 month'))));
            $total3=$total3 + ($this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d', strtotime('+2 month'))));
            $total4=$total4 + ($this->GetcashFlowsum($_POST['projectid'],$group->id,$group->spread,date('Y-m-d', strtotime('+3 month'))));
