    public function actionCorporatecashflow()
    {
        $connection = CActiveRecord::getDbConnection();
        $startdate=date('Y-m-d', strtotime('first day of +4 month'));
        $enddate=date('Y-m-d', strtotime('first day of this month'));
        $projectbank=AccountsItem::model()->find(array('condition'=>"account_type=2 AND projectid='12'",'order'=>'name ASC'));
        $ar = array("Projectid" => $_POST['projectid']);
        $str = http_build_query($ar);
        if(isset($_POST['quarter'])){
            $quesrter=$_POST['quarter'];
        }
        else
        {
            $quesrter=$this->GetCurrentQuarter();
        }
        $monthsdetails=$this->getQuartermonths($quesrter);
        //$print = "<a href='" . Yii::app()->request->baseUrl . "/Projects/Billsestimateiowprint?" . $str . "' target='_blank'><i class='glyphicon glyphicon-print'></i>Print</a>";
        $datarows = '<tr>
                                <th colspan="2">Accounts</th>
                                <th>'.$monthsdetails['monthhead1'].'</th>
                                <th>'.$monthsdetails['monthhead2'].'</th>
                                <th>'.$monthsdetails['monthhead3'].'</th>
                     </tr>';
        $subgeoups=AccountsItem::model()->findAll();
        $total1=0;
        $total2=0;
        $total3=0;
        $total4=0;
        foreach($subgeoups AS $group):
            $accounttotal='0';
            $monthtotal1=$this->GetcorporatecashFlowsum('12',$projectbank->id,$group->id,$monthsdetails['monthdate1']);
            $monthtotal2=$this->GetcorporatecashFlowsum('12',$projectbank->id,$group->id,$monthsdetails['monthdate2']);
            $monthtotal3=$this->GetcorporatecashFlowsum('12',$projectbank->id,$group->id,$monthsdetails['monthdate3']);
            $accounttotal=$monthtotal1+$monthtotal2+$monthtotal3;
            if($accounttotal!='0'):
                $datarows.='<tr>
                            <td colspan="2">'.$group->name.'</td>
                            <td >'.$monthtotal1.'</td>
                            <td >'.$monthtotal2.'</td>
                            <td >'.$monthtotal3.'</td>
                            </tr>';
                $total1=$total1 + $monthtotal1;
                $total2=$total2 + $monthtotal2;
                $total3=$total3 + $monthtotal3;
            endif;
        endforeach;
        $datarows.="<tr>
                    <td colspan='2'>Total</td>
                    <td >".$total1."</td>
                    <td >".$total2."</td>
                    <td >".$total3."</td>
                    </tr>";
        $arr = array('result' => $datarows, 'error' => 'No','quarter'=>$quesrter);

        echo json_encode($arr);
    }
    public function GetCurrentQuarter()
    {
        $quearter='';
        switch(date('n'))
        {
            case '1':
                $quearter='4';
                break;
            case '2':
                $quearter='4';
                break;
            case '3':
                $quearter='4';
                break;
            case '4':
                $quearter='1';
                break;
            case '5':
                $quearter='1';
                break;
            case '6':
                $quearter='1';
                break;
            case '7':
                $quearter='2';
                break;
            case '8':
                $quearter='2';
                break;
            case '9':
                $quearter='2';
                break;
            case '10':
                $quearter='3';
                break;
            case '11':
                $quearter='3';
                break;
            case '12':
                $quearter='3';
                break;
        }
        return $quearter;
    }
    public function getQuartermonths($quarter)
    {
        $returnarray=array('monthhead1'=>'','monthdate1'=>'','monthhead2'=>'','monthdate2'=>'','monthhead2'=>'','monthdate2'=>'','monthhead3'=>'','monthdate3'=>'');
        switch($quarter)
        {
            case '1':
                $returnarray=array(
                    'monthhead1'=>date('F Y', strtotime('first day of april')),'monthdate1'=>date('Y-m-d', strtotime('first day of april')),
                    'monthhead2'=>date('F Y', strtotime('first day of may')),'monthdate2'=>date('Y-m-d', strtotime('first day of may')),
                    'monthhead3'=>date('F Y', strtotime('first day of june')),'monthdate3'=>date('Y-m-d', strtotime('first day of june')));
                break;
            case '2':
                $returnarray=array(
                    'monthhead1'=>date('F Y', strtotime('first day of july')),'monthdate1'=>date('Y-m-d', strtotime('first day of april')),
                    'monthhead2'=>date('F Y', strtotime('first day of august')),'monthdate2'=>date('Y-m-d', strtotime('first day of august')),
                    'monthhead3'=>date('F Y', strtotime('first day of september')),'monthdate3'=>date('Y-m-d', strtotime('first day of september')));
                break;
            case '3':
                $returnarray=array(
                    'monthhead1'=>date('F Y', strtotime('first day of october')),'monthdate1'=>date('Y-m-d', strtotime('first day of october')),
                    'monthhead2'=>date('F Y', strtotime('first day of november')),'monthdate2'=>date('Y-m-d', strtotime('first day of november')),
                    'monthhead3'=>date('F Y', strtotime('first day of december')),'monthdate3'=>date('Y-m-d', strtotime('first day of december')));
                break;
            case '4':
                $returnarray=array(
                    'monthhead1'=>date('F Y', strtotime('first day of january next year')),'monthdate1'=>date('Y-m-d', strtotime('first day of january next year')),
                    'monthhead2'=>date('F Y', strtotime('first day of february next year')),'monthdate2'=>date('Y-m-d', strtotime('first day of february next year')),
                    'monthhead3'=>date('F Y', strtotime('first day of march next year')),'monthdate3'=>date('Y-m-d', strtotime('first day of march next year')));
                break;
        }
        return $returnarray;
    }
    public function GetcorporatecashFlowsum($place,$account,$debitaccount,$date)
    {
        $monthstartthis=date('Y-m-01', strtotime($date));
        $monthendthis=date('Y-m-t', strtotime($date));
        $connection = CActiveRecord::getDbConnection();
        $sql="SELECT SUM(amount) AS  total FROM voucher WHERE bank_id='".$account."' AND type='Payment' AND account_id='".$debitaccount."' AND date BETWEEN '$monthstartthis' AND '$monthendthis' AND place='".$place."'";
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $dataProvider = $dataReader->read();
        return ($dataProvider['total']?$dataProvider['total']:'0');

    }
