    public function GetcashFlowsum($project,$account,$spread,$date)
    {
        $connection = CActiveRecord::getDbConnection();
        $startfirstday=date('Y-m-d', strtotime('first day of this month'));
        $startlasttday=date('Y-m-d', strtotime('last day of this month'));
        $endfirstday=date('Y-m-d', strtotime('first day of +3 month'));
        $endlastday=date('Y-m-d', strtotime('last day of +3 month'));
        $resourcetypes=Resourcetype::model()->findAll(array('condition'=>'accountsub_id='.$account));
        $types='';
        $testval=0;
        if($date==date('Y-m-d', strtotime('+3 month')))
        {
            $testval=1;
        }
        foreach($resourcetypes AS $rstype):
            $types.=$rstype->ResourceType_Id.',';
        endforeach;
        $types=rtrim($types,',');
        if($types!=''):
            $startdate=date('Y-m-d', strtotime('first day of +4 month'));
            $enddate=date('Y-m-d', strtotime('first day of this month'));
            $monthstartthis=date('Y-m-01', strtotime($date));
            $monthendthis=date('Y-m-t', strtotime($date));
            $iows = itemofworks::model()->findAll(array("condition" => "Project_Id = '".$project. "' AND start_date<'".$monthendthis."' AND end_date>'".$monthstartthis."'"));

            $total=0;
            //to find number of days taken in this month for the iow
            $thismonthstart=strtotime($monthstartthis);
            $thismonthend=strtotime($monthendthis);
            //echo $thismonthstart.' '.$thismonthend.' ';
            //to find number of days taken in this month for the iow
            foreach ($iows as $key => $iow) {
                $iowstartdate=strtotime($iow->start_date);
                $iowenddate=strtotime($iow->end_date);
                // echo $thismonthstart.' '.$thismonthend.' '.$iowstartdate.' '.$iowenddate.' '.date('Y-m-t', strtotime($date)).' <br>';
                switch ($spread) {
                    case '0':
                        $rate=$this->GetSpecificRate($iow->IOW_Id,$types);
                        if (($iowstartdate >= $thismonthstart) && ($iowstartdate < $thismonthend)):
                            $total+=$rate;
                        endif;
                        break;
                    case '1':
                        $numberofdays=0;
                        // starts in this month and ends in this month
                        if($iowstartdate>=$thismonthstart && $iowenddate<=$thismonthend):
                            $datediff = $iowenddate - $iowstartdate;
                            $numberofdays=floor($datediff/(60*60*24));
                        //iow starts in this month and not ends in this month
                        elseif($iowstartdate>=$thismonthstart && $iowenddate>$thismonthend):
                            $datediff = $thismonthend - $iowstartdate;
                            $numberofdays=floor($datediff/(60*60*24));
                        //iow not starts in this month and not ends in this month
                        elseif($iowstartdate<$thismonthstart & $iowenddate>$thismonthend):
                            $datediff = $thismonthend - $thismonthstart;
                            $numberofdays=(floor($datediff/(60*60*24))+1);
                        //iow not starts in this month and ends in this month
                        elseif($iowstartdate<$thismonthstart && $iowenddate<=$thismonthend):
                            $datediff = $iowenddate - $thismonthstart;
                            $numberofdays=(floor($datediff/(60*60*24))+1);
                        //iow not starts and ends in this month
                        elseif($iowstartdate<$thismonthstart && $iowenddate<=$thismonthstart):
                            $numberofdays=0;
                        endif;

                        $numberofdays=abs($numberofdays);
                        $rate=$this->GetSpecificRate($iow->IOW_Id,$types);
                        $average=($rate/$iow->duration)*$numberofdays;
                        $total+=$average;
                        break;
                    case '2':
                        $rate=$this->GetSpecificRate($iow->IOW_Id,$types);
                        if (($iowenddate > $endfirstday) && ($iowenddate < $endlastday)):
                            $total+=$rate;
                        endif;
                        break;

                    default:
                        $rate=$this->GetSpecificRate($iow->IOW_Id,$types);
                        if (($iowstartdate > $startfirstday) && ($iowstartdate < $startlasttday)):
                            $total+=$rate;
                        endif;
                        break;
                }
            }
            //  echo $total.'<br>';
            return round($total,2);
        else:
            return 0;
        endif;
    }
    public function GetSpecificRate($iow,$account)
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "SELECT a.Item_Id,a.Quantity,a.Resource_group_Id,IOW_Id FROM iowproducts AS a WHERE a.IOW_Id=".$iow;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $iowproducts = $dataReader->readAll();
        $rstotal=0;
        if(count($iowproducts)>0):
            //print_r($iowproducts);
            foreach($iowproducts AS $key=>$product):
                switch ($product['Resource_group_Id']){
                    case '1':
                        $sqltemvals="SELECT SUM(b.IR_Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN investment_resources AS b ON a.Resource_Id=b.IR_Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.IR_Investments_Id='".$product['Item_Id']."'";

                        break;
                    case '2':
                        $sqltemvals="SELECT SUM(b.PSR_Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN project_setup_resources AS b ON a.Resource_Id=b.PSR_Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.PSR_PS_Id='".$product['Item_Id']."'";

                        break;
                    case '3':
                        $sqltemvals="SELECT SUM(b.Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN product_resources AS b ON a.Resource_Id=b.Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.Product_Id='".$product['Item_Id']."'";

                        break;
                    case '4':
                        $sqltemvals="SELECT SUM(b.Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN  logistics_resources AS b ON a.Resource_Id=b.Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.Logistics_Id='".$product['Item_Id']."'";

                        break;
                    case '5':
                        $sqltemvals="SELECT SUM(b.COR_Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN  construction_resources AS b ON a.Resource_Id=b.COR_Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.COR_CO_Id='".$product['Item_Id']."'";

                        break;
                    case '6':
                        $sqltemvals="SELECT SUM(b.Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN  pi_resources AS b ON a.Resource_Id=b.Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.Purchase_Id='".$product['Item_Id']."'";

                        break;
                    case '7':
                        $sqltemvals="SELECT SUM(b.MCR_Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN  major_consumables_resources AS b ON a.Resource_Id=b.MCR_Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.MCR_MC_Id='".$product['Item_Id']."'";

                        break;
                    case '8':
                        $sqltemvals="SELECT SUM(b.Price*".$product['Quantity'].") AS total,a.Name AS resource FROM resources AS a INNER JOIN  overheads_resources AS b ON a.Resource_Id=b.Resource_Id WHERE a.ResourceType_Id IN (".$account.") AND b.Overhead_id='".$product['Item_Id']."'";

                        break;
                }
                $command = $connection->createCommand($sqltemvals);
                $dataReader = $command->query();
                $resourcesum = $dataReader->read();
                $rstotal+=$resourcesum['total'];
            endforeach;
        endif;
        return $rstotal;
    }

