    public function actionSiteReport($id)
    {
        $connection = CActiveRecord::getDbConnection();
        $project = Projects::model()->findByPk($id);

        $sqltemvals1 = "SELECT * FROM project_estimate WHERE Project_Id=' $id ' ORDER BY Resource_group_Id ASC,sortorder ASC ";
        $command = $connection->createCommand($sqltemvals1);
        $dataReader = $command->query();
        $dataProvider = $dataReader->readAll();
        $datarows='';
        foreach ($dataProvider AS $key => $data):
            $sql = "SELECT DISTINCT a.Name,a.ResourceType_Id,a.Resource_Id,a.Resource_group_Id,b.Proj_Id,b.Product_Id FROM resources AS a
                    INNER JOIN estimate_project_resources AS b ON  a.Resource_Id=b.Resource_Id
                    WHERE b.Proj_Product_Id='" . $data['project_estimate_Id'] . "' ORDER BY a.Resource_Id ";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resources = $dataReader->readAll();
            $datavalues='';
            foreach($resources AS $resource):
                $sql="SELECT * FROM estimate_project_resources WHERE Resource_Id='".$resource['Resource_Id']."' AND Proj_Product_Id='" . $data['project_estimate_Id'] ."' ";
                //echo $sql;
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $resourcedetails = $dataReader->readAll();
                $esttotal=0;
                foreach($resourcedetails AS $key=>$resourcedetail):
                    $esttotal=$esttotal + $resourcedetail['Quantity'];
                endforeach;
                $sql="SELECT quantity_used FROM site_report_resources WHERE resource_id='".$resource['Resource_Id']."' AND activityid='".$resource['Product_Id']."' ";
                //echo $sql;
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $siteresources = $dataReader->readAll();
                $sql="SELECT quantity_total FROM site_report WHERE resourcegroup_id='".$resource['Resource_group_Id']."' AND activityid='".$resource['Product_Id']."'";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $siteresourceqty = $dataReader->read();
                $qtyconsumed=0;
                foreach($siteresources AS $siteresource):
                    $qtyconsumed=$qtyconsumed + ($siteresource['quantity_used'] / $siteresourceqty['quantity_total']);
                endforeach;
                $variation=$qtyconsumed - $esttotal;
                if($variation>0):
                    $excess=$variation;
                    $tospent='';
                else:
                    $excess='';
                    $tospent=abs($variation);
                endif;
                $datavalues.='<tr>
                        <td>'.$resource['Name'].'</td>
                        <td>'.number_format($esttotal,2).'</td>
                        <td>'.number_format($qtyconsumed,2).'</td>
                        <td>'.number_format($excess,2).'</td>
                        <td>'.number_format($tospent,2).'</td>
                        </tr>';
            endforeach;
            $datarows.=$datavalues;
        endforeach;
        $this->render('sitereport',array(
            'id'=>$id,
            'datarows'=>$datarows,
            'project'=>$project,
        ));
    }

    public function actionCostvariation($id)
    {
        $connection = CActiveRecord::getDbConnection();
        $project = Projects::model()->findByPk($id);

        $resourcegroups=array(array( 'Resource_group_Id'=>'2','name'=>'Project Setup'),
            array( 'Resource_group_Id'=>'3','name'=>'Production'),
            array( 'Resource_group_Id'=>'4','name'=>'Logistics'),
            array( 'Resource_group_Id'=>'5','name'=>'Construction'),
            array( 'Resource_group_Id'=>'8','name'=>'Overheads'),);
        $datarows="";
        $grandtotal = 0;
        $grandatot = 0;
        $grandvartot = 0;
        foreach ($resourcegroups AS $resgroup):
            if($resgroup['Resource_group_Id']==2):
                $sql = "SELECT a.PS_Name AS resname,a.PS_Unit AS unit,SUM(b.Price) AS amounttotal,SUM(b.Quantity) AS quantitytotal,b.project_estimate_Id FROM project_estimate  AS b
                    INNER JOIN project_setup AS a ON  b.Item_Id=a.PS_Id
                    WHERE b.Project_Id='" .$id. "' AND b.Resource_group_Id='" . $resgroup['Resource_group_Id'] . "'  GROUP BY  b.Item_Id";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $dataProvider = $dataReader->readAll();
                if (count($dataProvider) > 0):
                    $datarows .= '<tr> <td colspan="10"><b>' . $resgroup['name'] . '</b></td></tr>';
                    $grouptotal = 0;
                    $acttotal=0;
                    $vartotal=0;
                    foreach ($dataProvider AS $key => $data):
                        $costvariation=$data['quantitytotal'] * number_format($this->getcostvariation($data['project_estimate_Id']), 2);
                        $variation=$costvariation - $data['amounttotal'];
                        $datarows .= "<tr>

                                    <td></td>
                                    <td>" . ($key + 1) . "</td>
                                    <td><a href='javascript:void(0);' onclick='print(\"".$data["project_estimate_Id"]."\")'> " . $data['resname'] . "</a></td>
                                    <td>" . $data['unit'] . "</td>
                                    <td>" . number_format($data['quantitytotal'], 2) . "</td>
                                    <td>" . number_format($data['amounttotal'] / $data['quantitytotal'], 2) . "</td>
                                    <td>" .number_format($costvariation / $data['quantitytotal'],2)."</td>
                                    <td>" . number_format($data['amounttotal'], 2) . "</td>
                                    <td>" . number_format($costvariation, 2) . "</td>
                                    <td>" .number_format($variation,2)."</td></tr>";
                        $grouptotal = $grouptotal + $data['amounttotal'];
                        $acttotal = $acttotal + $costvariation;
                        $vartotal = $vartotal + $variation;
                    endforeach;
                    $grandtotal = $grandtotal + $grouptotal;
                    $grandatot = $grandatot + $acttotal;
                    $grandvartot = $grandvartot + $vartotal;
                    $datarows .= '<tr>
                                <td ></td>
                                <td >Total</td>
                                <td colspan="6" style="text-align: right"><b>' . number_format($grouptotal,2) . '</b></td>
                                <td style="text-align: right"><b>' . number_format($acttotal,2) . '</b></td>
                                <td style="text-align: right"><b>' . number_format($vartotal,2) . '</b></td></tr>';
                endif;
            elseif($resgroup['Resource_group_Id']==3):
                $sql = "SELECT a.Name AS resname,a.Unit AS unit,SUM(b.Price) AS amounttotal,SUM(b.Quantity) AS quantitytotal,b.project_estimate_Id FROM  project_estimate AS b
                    INNER JOIN products AS a ON  a.Product_Id=b.Item_Id
                    WHERE b.Project_Id='" . $id . "' AND b.Resource_group_Id='" . $resgroup['Resource_group_Id'] . "'  GROUP BY  b.Item_Id";

                $command = $connection->createCommand($sql);
