    public function getcostvariation($itemid)
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "SELECT DISTINCT a.Name,a.ResourceType_Id,a.Resource_Id,a.Resource_group_Id,b.Proj_Id,b.Product_Id FROM resources AS a
                    INNER JOIN estimate_project_resources AS b ON  a.Resource_Id=b.Resource_Id
                    WHERE b.Proj_Product_Id='" . $itemid . "' ORDER BY a.Resource_Id ";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resources = $dataReader->readAll();
        $total=0;
        foreach($resources AS $resource):
            $sql="SELECT * FROM estimate_project_resources WHERE Resource_Id='".$resource['Resource_Id']."' AND Proj_Product_Id='" . $itemid ."' ";
            //echo $sql;exit;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resourcedetails = $dataReader->readAll();
            $estprojres='';
            foreach($resourcedetails AS $key=>$resourcedetail):
                $estprojres.=($key=='0'?$resourcedetail['Est_Proj_Res_Id']:','.$resourcedetail['Est_Proj_Res_Id']);
            endforeach;
            $sql="SELECT Source_unit FROM resourcetype WHERE ResourceType_Id='".$resource['ResourceType_Id']."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resourcetype = $dataReader->read();
            $spendamount=$this->getspendamount($resource['Resource_Id'],$resourcetype['Source_unit'],$estprojres,$resource['Proj_Id']);
            $sql="SELECT quantity_used FROM site_report_resources WHERE resource_id='".$resource['Resource_Id']."' AND activityid='".$resource['Product_Id']."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $siteresources = $dataReader->readAll();
            $sql="SELECT quantity_total FROM site_report WHERE resourcegroup_id='".$resource['Resource_group_Id']."' AND activityid='".$resource['Product_Id']."'";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $siteresourceqty = $dataReader->read();
            $qtyconsumed=0;
            foreach($siteresources AS $siteresource):
                $qtyconsumed=$qtyconsumed + ($siteresource['quantity_used'] / $siteresourceqty['quantity_total']);
            endforeach;
            //echo (round($qtyconsumed,2) * $spendamount);
            $total=$total + (round($qtyconsumed,2) * $spendamount);
        endforeach;
        return $total;
    }
    public function actionRescostvariation($id)
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "SELECT DISTINCT a.Name,a.ResourceType_Id,a.Resource_Id,a.Resource_group_Id,a.Unit,b.Proj_Id,b.Product_Id,b.Price,b.actual_price,b.Quantity FROM resources AS a
                    INNER JOIN estimate_project_resources AS b ON  a.Resource_Id=b.Resource_Id
                    WHERE b.Proj_Product_Id='" . $id . "' ORDER BY a.Resource_Id ";
        //echo $sql;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resources = $dataReader->readAll();
        $datarows='';
        $eamounttot=0;
        $aamounttot=0;
        $vartot=0;
        foreach($resources AS $count=>$resource):
            $project=Projects::model()->findByPk($resource['Proj_Id']);
            if($resource['Resource_group_Id']==2):
                $activity=ProjectSetup::model()->findByPk($resource['Product_Id']);
                $name=$activity->PS_Name;
            elseif($resource['Resource_group_Id']==3):
                $activity=Products::model()->findByPk($resource['Product_Id']);
                $name=$activity->Name;
            elseif($resource['Resource_group_Id']==4):
                $activity=Logistics::model()->findByPk($resource['Product_Id']);
                $name=$activity->Name;
            elseif($resource['Resource_group_Id']==5):
                $activity=Construction::model()->findByPk($resource['Product_Id']);
                $name=$activity->CO_Name;
            elseif($resource['Resource_group_Id']==8):
                $activity=Overheads::model()->findByPk($resource['Product_Id']);
                $name=$activity->Name;
            endif;
            $sql="SELECT * FROM estimate_project_resources WHERE Resource_Id='".$resource['Resource_Id']."' AND Proj_Product_Id='" . $id ."' ";
            //echo $sql;exit;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resourcedetails = $dataReader->readAll();
            $esttotal=0;
            $estprojres='';
            foreach($resourcedetails AS $key=>$resourcedetail):
                $esttotal=$esttotal + $resourcedetail['actual_price'];
                $estprojres.=($key=='0'?$resourcedetail['Est_Proj_Res_Id']:','.$resourcedetail['Est_Proj_Res_Id']);
            endforeach;
            $sql="SELECT Source_unit FROM resourcetype WHERE ResourceType_Id='".$resource['ResourceType_Id']."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resourcetype = $dataReader->read();
            $spendamount=$this->getspendamount($resource['Resource_Id'],$resourcetype['Source_unit'],$estprojres,$resource['Proj_Id']);
            $sql="SELECT quantity_used FROM site_report_resources WHERE resource_id='".$resource['Resource_Id']."' AND activityid='".$resource['Product_Id']."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $siteresources = $dataReader->readAll();
            $sql="SELECT quantity_total FROM site_report WHERE resourcegroup_id='".$resource['Resource_group_Id']."' AND activityid='".$resource['Product_Id']."'";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $siteresourceqty = $dataReader->read();
            $qtyconsumed=0;
            foreach($siteresources AS $siteresource):
                $qtyconsumed=$qtyconsumed + ($siteresource['quantity_used'] / $siteresourceqty['quantity_total']);
            endforeach;
            $cost=(round($qtyconsumed,2) * $spendamount);
            $erate=$resource['actual_price'];
            $eqty=$resource['Quantity'];
            $eamount=$erate * $eqty;
            $arate=$spendamount;
            $aqty=$qtyconsumed;
            $aamount=$arate * $aqty;
            $variation=abs($aamount - $eamount);
            $datarows.='<tr>
                        <td>'.($count + 1).'</td>
                        <td>'.$resource['Name'].'</td>
                        <td>'.$resource['Unit'].'</td>
                        <td>'.number_format($erate,2).'</td>
                        <td>'.number_format($arate,2).'</td>
                        <td>'.number_format($eqty,2).'</td>
                        <td>'.number_format($aqty,2).'</td>
                        <td>'.number_format($eamount,2).'</td>
                        <td>'.number_format($aamount,2).'</td>
                        <td>'.number_format($variation,2).'</td>
                        </tr>';
            $eamounttot=$eamounttot + $eamount;
            $aamounttot=$aamounttot + $aamount;
            $vartot=$vartot + $variation;
        endforeach;
        $datarows.="<tr>
                    <td colspan='7'><b>Total</b></td>
                    <td><b>".number_format($eamounttot,2)."</b></td>
                    <td><b>".number_format($aamounttot,2)."</b></td>
                    <td><b>".number_format($vartot,2)."</b></td>
                </tr>";
        $this->render('rescostvariation',
            array(
                'id'=>$id,
                'project'=>$project,
                'activityname'=>$name,
                'datarows'=>$datarows,
            ));
    }
    public function actionResourcecostvariance()
    {
        $connection = CActiveRecord::getDbConnection();
        $resourceid=$_GET['resid'];
        $productid=$_GET['prodid'];
        $sql="SELECT * FROM estimate_project_resources WHERE Resource_Id='".$resourceid."' AND Proj_Product_Id='" . $productid ."' ";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resourcedetails = $dataReader->readAll();
        $esttotal=0;
        $estqtytotal=0;
        $estprojres='';
        $projectid='';
        foreach($resourcedetails AS $key=>$resourcedetail):
            $esttotal=$esttotal + $resourcedetail['actual_price'];
            $estqtytotal=$estqtytotal + $resourcedetail['Quantity'];
            $estprojres.=($key=='0'?$resourcedetail['Est_Proj_Res_Id']:','.$resourcedetail['Est_Proj_Res_Id']);
            $projectid=$resourcedetail['Proj_Id'];
        endforeach;
        $resource=Resources::model()->findByPk($resourceid);
        $project=Projects::model()->findByPk($projectid);
        $sql="SELECT Source_unit FROM resourcetype WHERE ResourceType_Id='".$resource->ResourceType_Id."' ";
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resourcetype = $dataReader->read();
        $spendamount=$this->getspendamount($resourceid,$resourcetype['Source_unit'],$estprojres,$projectid);
        $variation=$spendamount - $esttotal;
        $sql="SELECT a.Product_Id,b.Resource_group_Id FROM estimate_project_resources AS a LEFT JOIN resources AS b ON a.Resource_Id=b.Resource_Id WHERE a.Resource_Id='".$resourceid."' AND a.Proj_Product_Id='".$productid."' ";
        //echo $sql;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $resgrp = $dataReader->read();
