        //echo $sql;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $siteresources = $dataReader->readAll();
        $sql="SELECT quantity_total FROM site_report WHERE resourcegroup_id='".$resgrp['Resource_group_Id']."' AND activityid='".$resgrp['Product_Id']."'";
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $siteresourceqty = $dataReader->read();
        $qtyconsumed=0;
        foreach($siteresources AS $siteresource):
            $qtyconsumed=$qtyconsumed + ($siteresource['quantity_used'] / $siteresourceqty['quantity_total']);
        endforeach;
        $qtyvariation=$qtyconsumed - $estqtytotal;
        $costvariance=$spendamount * $qtyconsumed;
        $datarows="<tr>
                    <td>".$resource->Name."</td>
                    <td>".number_format(abs($spendamount),2)."</td>
                    <td>".number_format(abs($qtyconsumed),2)."</td>
                    <td>".number_format($costvariance,2)."</td>
                    </tr>";
        $this->render('rescostvariance',
            array(
                'id'=>$resourceid,
                'project'=>$project,
                'datarows'=>$datarows,
            ));
    }
    public function getspendamount($resid,$type,$estprojres,$projectid)
    {
        $connection = CActiveRecord::getDbConnection();
        if($type==1):
            $sql="SELECT PI_ID,PI_Resource_Id,PI_PO_Id FROM purchase_items WHERE PI_Resource_Id IN(".$estprojres.") AND PI_Status='1' ";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $purchaseitems = $dataReader->readAll();
            $spendamount=0;
            foreach($purchaseitems AS $purchaseitem):
                $sql="SELECT bill_id,billno FROM bills WHERE Status='1' AND bill_Purchase_Order='".$purchaseitem['PI_PO_Id']."' ";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $bills = $dataReader->read();
                $sql="SELECT item,rate,amount,quantity FROM billitems WHERE billid ='".$bills['bill_id']."' AND item='".$purchaseitem['PI_ID']."' ";
                //echo $sql;
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $billitems = $dataReader->read();
                $spendamount=$spendamount + ($billitems['amount'] / $billitems['quantity']);
                //$spendamount=$spendamount + ($billitems['rate']);
            endforeach;
        elseif($type==3):
            $sql="SELECT SUM(wages) as total FROM muster WHERE trade_id='".$resid."' AND project_id='".$projectid."'";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $wages = $dataReader->read();
            $totalwages=$wages['total'];
            $sql="SELECT DATE_FORMAT(date,'%Y-%m-%d') AS date FROM muster WHERE trade_id='".$resid."' ORDER BY DATE_FORMAT(date,'%Y-%m-%d') ASC LIMIT 0,1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $startdate = $dataReader->read();
            $sql="SELECT DATE_FORMAT(date,'%Y-%m-%d') AS date FROM muster WHERE trade_id='".$resid."' ORDER BY DATE_FORMAT(date,'%Y-%m-%d') DESC LIMIT 0,1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $enddate = $dataReader->read();
            $date1 = $startdate['date'];
            $date2 = $enddate['date'];
            $ts1 = strtotime($date1);
            $ts2 = strtotime($date2);
            $datediff = $ts2 - $ts1;
            $totaldays=($datediff / (60 * 60 * 24)) + 1;
            $spendamount=$totalwages / $totaldays;
        elseif($type==4):
            $sql="SELECT WI_Id FROM work_items WHERE WI_Item IN(".$estprojres.") AND WI_Status='1' ";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $workitems = $dataReader->readAll();
            $spendamount=0;
            foreach($workitems AS $workitem):
                $sql="SELECT item,amount FROM billitems WHERE item='".$workitem['WI_Id']."' ";
                //echo $sql;
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $billitems = $dataReader->read();
                $spendamount=$spendamount + $billitems['amount'];
            endforeach;
        elseif($type==6):
            $sql="SELECT SUM(diesel) as total,SUM(worked_hours) as totalhrs FROM logbook WHERE equipment_id='".$resid."' AND project_id='".$projectid."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $diesel = $dataReader->read();
            $totaldiesel=$diesel['total'];
            $totalhrs=$diesel['totalhrs'];
            $resource=Resources::model()->find(array('condition'=>'Name=:name','params'=>array(':name'=>'diesel')));
            $sql="SELECT PI_ID FROM purchase_items WHERE PI_Resource_Id='".$resource->Resource_Id."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $pitems = $dataReader->readAll();
            $qty=0;
            $amount=0;
            foreach($pitems AS $pitem):
                $sql="SELECT amount,quantity FROM billitems WHERE item='".$pitem['PI_ID']."' ";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $bill = $dataReader->read();
                $qty=$qty + $bill['quantity'];
                $amount=$amount + $bill['amount'];
            endforeach;
            $perrate=$amount / $qty;
            $dieselamount=$totaldiesel * $perrate;
            $sql="SELECT actual_price FROM estimate_project_resources WHERE Resource_Id='".$resid."' AND Proj_Id='".$projectid."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resrate = $dataReader->read();
            $workamount=$totalhrs * $resrate['actual_price'];
            $sql="SELECT groupid FROM schedule WHERE resource_id='".$resid."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $data = $dataReader->read();
            $schedule=$data['groupid'];
            $sql="SELECT id,voucher_no,DATE_FORMAT(date,'%d/%m/%y') AS date,narration,amount,type,creditacnt,";
            $sql.="bank_id,contra,account_id,'Voucher' AS rawtype FROM voucher WHERE (account_id IN (15) OR creditacnt IN (15)) ";
            $sql.=" AND sub_schedule='" . $schedule . "' AND place='" . $projectid . "'  ";
            //echo $sql;
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $ledgeritems = $dataReader->readAll();
            $credittotal=0;
            $debittotal=0;
            foreach($ledgeritems AS $ledgeritem):
                if($ledgeritem['contra']==0):
                    if($ledgeritem['creditacnt']==15):
                        $credittotal=$credittotal + $ledgeritem['amount'];
                    elseif($ledgeritem['account_id']==15):
                        $debittotal=$debittotal + $ledgeritem['amount'];
                    endif;
                else:
                    if($ledgeritem['type']=='Payment' && $ledgeritem['creditacnt']==15 ):
                        $credittotal=$credittotal + $ledgeritem['amount'];
                    elseif($ledgeritem['type']=='Receipt' && $ledgeritem['account_id']==15):
                        $debittotal=$debittotal + $ledgeritem['amount'];
                    endif;
                endif;
            endforeach;
            $ledgtotal=abs($credittotal - $debittotal);
            $spendamount=($dieselamount + $ledgtotal) / $totalhrs;
        elseif($type==7):
            $sql="SELECT Resource_Acc_Id,Resource_Id FROM resources WHERE Resource_Id='".$resid."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resacnt = $dataReader->read();
            $accountid=$resacnt['Resource_Acc_Id'];
            //echo $accountid;
            $sql="(SELECT id,voucher_no,DATE_FORMAT(date,'%d/%m/%y') AS date,narration,amount,type,creditacnt,bank_id,contra,account_id,'Voucher' AS rawtype FROM voucher WHERE (account_id='".$accountid."' OR creditacnt='".$accountid."') AND place='".$projectid."'  )
                        UNION
                        (SELECT id,voucher_no,DATE_FORMAT(date,'%d/%m/%y') AS date,narration,amount,type,creditacnt,bank_id,contra,debitacnt AS account_id,'Journal' AS rawtype FROM journalvoucher WHERE (debitacnt='".$accountid."' OR creditacnt='".$accountid."') AND project_id='".$projectid."'  ) ORDER BY DATE_FORMAT(date,'%d/%m/%y') ASC,id DESC";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $ledgeritems = $dataReader->readAll();
            $credittotal=0;
            $debittotal=0;
            $sql="(SELECT DATE_FORMAT(date,'%Y-%m-%d') AS date FROM voucher WHERE (account_id='".$accountid."' OR creditacnt='".$accountid."') AND place='".$projectid."')
                        UNION
                       (SELECT DATE_FORMAT(date,'%Y-%m-%d') AS date FROM journalvoucher WHERE (debitacnt='".$accountid."' OR creditacnt='".$accountid."') AND project_id='".$projectid."'  ) ORDER BY DATE_FORMAT(date,'%Y-%m-%d') ASC LIMIT 0,1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $startdate = $dataReader->read();
            $sql="(SELECT DATE_FORMAT(date,'%Y-%m-%d') AS date FROM voucher WHERE (account_id='".$accountid."' OR creditacnt='".$accountid."') AND place='".$projectid."')
                        UNION
                       (SELECT DATE_FORMAT(date,'%Y-%m-%d') AS date FROM journalvoucher WHERE (debitacnt='".$accountid."' OR creditacnt='".$accountid."') AND project_id='".$projectid."'  ) ORDER BY DATE_FORMAT(date,'%Y-%m-%d') DESC LIMIT 0,1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $enddate = $dataReader->read();
            foreach($ledgeritems AS $key=>$ledgeritem):
                $date1 = $startdate['date'];
                $date2 = $enddate['date'];

                $ts1 = strtotime($date1);
                $ts2 = strtotime($date2);

                $year1 = date('Y', $ts1);
                $year2 = date('Y', $ts2);

                $month1 = date('m', $ts1);
                $month2 = date('m', $ts2);

                $diff = (($year2 - $year1) * 12) + ($month2 - $month1);
                if($ledgeritem['contra']==0):
                    if($ledgeritem['creditacnt']==$accountid):
                        $credittotal=$credittotal + $ledgeritem['amount'];
                    elseif($ledgeritem['account_id']==$accountid):
                        $debittotal=$debittotal + $ledgeritem['amount'];
                    endif;
                else:
                    if($ledgeritem['type']=='Payment' && $ledgeritem['creditacnt']==$accountid ):
                        $credittotal=$credittotal + $ledgeritem['amount'];
                    elseif($ledgeritem['type']=='Receipt' && $ledgeritem['account_id']==$accountid):
                        $debittotal=$debittotal + $ledgeritem['amount'];
                    endif;
                endif;
            endforeach;
            $month=$diff + 1;
            $spendamount=(abs($credittotal - $debittotal)) / $month;
        elseif($type==8):
            $sql="SELECT Resource_Acc_Id,Resource_Id FROM resources WHERE Resource_Id='".$resid."' ";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $resacnt = $dataReader->read();
            $accountid=$resacnt['Resource_Acc_Id'];
            //echo $accountid;
            $sql="(SELECT id,voucher_no,DATE_FORMAT(date,'%d/%m/%y') AS date,narration,amount,type,creditacnt,bank_id,contra,account_id,'Voucher' AS rawtype FROM voucher WHERE (account_id='".$accountid."' OR creditacnt='".$accountid."') AND place='".$projectid."'  )
                        UNION
                        (SELECT id,voucher_no,DATE_FORMAT(date,'%d/%m/%y') AS date,narration,amount,type,creditacnt,bank_id,contra,debitacnt AS account_id,'Journal' AS rawtype FROM journalvoucher WHERE (debitacnt='".$accountid."' OR creditacnt='".$accountid."') AND project_id='".$projectid."'  ) ORDER BY DATE_FORMAT(date,'%d/%m/%y') ASC,id DESC";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $ledgeritems = $dataReader->readAll();
            $credittotal=0;
            $debittotal=0;
            foreach($ledgeritems AS $key=>$ledgeritem):
                if($ledgeritem['contra']==0):
                    if($ledgeritem['creditacnt']==$accountid):
                        $credittotal=$credittotal + $ledgeritem['amount'];
                    elseif($ledgeritem['account_id']==$accountid):
                        $debittotal=$debittotal + $ledgeritem['amount'];
                    endif;
                else:
                    if($ledgeritem['type']=='Payment' && $ledgeritem['creditacnt']==$accountid ):
                        $credittotal=$credittotal + $ledgeritem['amount'];
                    elseif($ledgeritem['type']=='Receipt' && $ledgeritem['account_id']==$accountid):
                        $debittotal=$debittotal + $ledgeritem['amount'];
                    endif;
                endif;
            endforeach;
            $spendamount=abs($credittotal - $debittotal);
        endif;
        return $spendamount;
    }
