    public function Receiveorders($orderid)
    {

        $order=Orders::findOne($orderid);
        if($order['order_type']==2){
            $orders=Orders::find()->where(['project_id' => $order['project_id']])->andWhere(['vendor_id' => $order['vendor_id']])->andWhere(['status' => 2])->andWhere(['order_type' => 2])->andWhere(['delete_status' => 0])->orderBy(['order_id' => SORT_DESC])->all();
            $datarows='';
            $billitems='';
            $total=0;
            $billtotal=0;
            $key = 0;
            foreach($orders AS $order1):
                $id = $order1['order_id'];
                $connection = Yii::$app->db;
                $sql="SELECT resource_id, COUNT(*) as count FROM ordered_resource where order_id=".$id." GROUP BY rate,resource_id HAVING COUNT(*) > 1";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $dataProvider = $dataReader->read();
                if(empty($dataProvider)):
                    $resourceitems=OrderedResource::find()->where(['order_id' => $id])->all();
                else:
                    $resourceitems=OrderedResource::find()->where(['order_id' => $id])->andWhere(['group' => 'resource_id'])->all();
                endif;
                foreach($resourceitems AS $resourceitem):
                    if($resourceitem['resource_name']==''):
                        $resname=Resources::findOne($resourceitem['resource_id'])->Name;
                    else:
                        $resname=$resourceitem['resource_name'];
                    endif;
                    $resitems=OrderedResource::find()->where(['resource_id' => $resourceitem['resource_id']])->andWhere(['order_id' => $id])->all();
                    $totalqty=0;
                    foreach($resitems AS $resitem):
                        $totalqty=$totalqty + $resitem['qnty'];
                    endforeach;
                    if(empty($dataProvider)):
                        $orderresqty=$resourceitem['qnty'];
                    else:
                        $orderresqty=$totalqty;
                    endif;
                    $invoiceresqty=InvoiceResources::find()->where(['order_id' => $id])->andWhere(['resource_id' => $resourceitem['resource_id']])->all();
                    $totresqty=0;
                    if(!empty($invoiceresqty)){
                        foreach($invoiceresqty AS $item):
                            $totresqty=$totresqty + $item['resource_qty'];
                        endforeach;
                        if($invoiceresqty['resource_qty']==''):
                            $resqty=$resourceitem['qnty'];
                        else:
                            $resqty=$invoiceresqty['resource_qty'];
                        endif;
                    }else{
                        $totresqty=0;
                        $resqty='';
                    }
                    $rate=$resourceitem['rate'];
                    $remqty=$orderresqty - $totresqty;
                    $amount=$rate * $remqty;
                    if($resourceitem['cgst']!=0):
                        $gst=$resourceitem['cgst'] + $resourceitem['sgst'];
                    else:
                        $gst=$resourceitem['igst'];
                    endif;
                    if($resourceitem['cgst']!=0 & $resourceitem['sgst']!=0):
                        $gstper=$resourceitem['cgst'] + $resourceitem['sgst'];
                        $gsttype=1;
                    elseif($resourceitem['igst']!=0):
                        $gstper=$resourceitem['igst'];
                        $gsttype=2;
                    else:
                        $gstper=0;
                        $gsttype=0;
                    endif;
                    //var_dump($gsttype);exit;
                    $gstamount=($amount * $gstper) / 100;
                    $amntincgst=$amount + $gstamount;
                    if($order['order_type']!=3):
                        $datarows.='<tr>
                            <td>'.($key + 1).'</td>
                            <td>
                            <input type="hidden" name="resourceid[]" value="'.$resourceitem['resource_id'].'">
                            <input type="hidden" id="resmaxqty'.$resourceitem['order_res_id'].'" value="'.$remqty.'">
                            <input type="hidden" name="OrderID[]" value="'.$id.'">
                            '.$resname.'</td>
                            <td>'.$resourceitem['unit'].'</td>
                            <td>'.$resourceitem['rate'].'<input type="hidden" id="poresrate'.$resourceitem['order_res_id'].'" value="'.$resourceitem['rate'].'">
                            </td>
                            <td>
                                <input type="text" class="form-control resourceqnty" id="resourceqnty'.$resourceitem['order_res_id'].'" data-id="'.$resourceitem['order_res_id'].'" name="resourceqnty[]" value="'.$remqty.'" size="1"  />
                                <span class="error"></span>
                            </td>
                            <td style="text-align:right;" id="poresamount'.$resourceitem['order_res_id'].'">'.number_format((float)$amount, 2).'</td>
                            <td style="text-align:right;"><span id="poresnetht'.$resourceitem['order_res_id'].'">'.number_format((float)$amntincgst, 2).'</span><input type="hidden" class="poresnet" id="poresnet'.$resourceitem['order_res_id'].'" value="'.$amntincgst.'">
                            </td>
                            </tr>
                            <tr>';
                        $total=$total + $amntincgst;
                    else:
                        $datarows.='<tr>
                            <td>'.($key + 1).'</td>
                            <td>
                            <input type="hidden" name="resourceid[]" value="'.$resourceitem['resource_id'].'">
                            <input type="hidden" id="resmaxqty'.$resourceitem['order_res_id'].'" value="'.$remqty.'">
                            <input type="hidden" name="OrderID[]" value="'.$id.'">
                            '.$resname.'</td>
                            <td>'.$resourceitem['unit'].'</td>
