                            $gst=$resourceitem['igst'];
                        else:
                            $gst=0;
                        endif;
                    endforeach;
                    if($order['order_type']==1):
                        $ordertype='Purchase Order';
                    elseif($order['order_type']==2):
                        $ordertype='Work Order';
                    elseif($order['order_type']==3):
                        $ordertype='Direct Workers Order';
                    elseif($order['order_type']==4):
                        $ordertype='Lease Order';
                    else:
                        $ordertype='Despatch Order';
                    endif;
                    $vendor=Vendors::findOne($order['vendor_id'])->Name;
                    $project=Projects::findOne($order['project_id'])->Name;
                    $cart=Cart::find()->where(['Project' => $order['project_id']])->andWhere(['Vendor_Id' => $order['vendor_id']])->one();
                    $jobcard=Jobcard::findOne($cart['Job_Id']);
                    $gstamount=($amount * $gst) / 100;
                    $amntincgst=$amount + $gstamount;
                    $jobcard['activity']='';
                    if($jobcard){
                    $datarows.='<div class="row leaseilist" id="leaseorderitemrow'.$order['order_id'].'">
                                    <div class="col-md-9" style="padding-top: 4px;">
                                        <div class="row leastitem">
                                            <div class="col-md-1 numsfst">
                                                <span class="number lease-number"><b>'.++$count.'</b></span>
                                            </div>
                                            <div class="col-md-3 type">
                                                <span class="date endsdt"><em class="cal-icon icon-calendar1"></em>'.date('d-m-Y',strtotime($order['date'])).'</span>
                                            </div>
                                            <div class="col-md-4 type">
                                                <span class="leasevendor">'.$vendor.'</span>
                                            </div>
                                            <div class="col-md-2 type text-right">
                                                <span class="leaseamnt">'.number_format((float)$amntincgst, 2).'</span>
                                            </div>
                                            <div class="col-md-2 type">
                                                <span class="leasestatus"></span>
                                            </div>
                                            
                                        </div>
                                    </div>
                                    <div class="col-md-3 icon-groups type" style="    bottom: 4px;">
                                        <a style="display:none;" href="javascript:void(0);" class="btn btn-primary addForm raise-bill-btn text-button leaseordersAdd" data-v="'.$order['order_id'].'" title="Raise Bill"><span class="icon-group_work"></span> Raise Bill</a>
                                    </div></div>';
                                }
                    $totalamount+=$amntincgst;
                endforeach;
                $datarows.='<div class="row">
                                <div class="col-md-9">
