                                    </div>
                                </div>
                                <div class="col-md-3 icon-groups type">  
                                </div>
                            </div>';
            else:
                $datarows='<div style="text-align: center;">No Lease Orders Found</div>';
            endif;
            $arr=array('result'=>$datarows,'error'=>'No','projectName' =>$projectinfo->Name);
