            $sql="SELECT a.date,a.order_id,b.resource_name,b.jobcard_id,b.order_res_id, b.date as resdate,b.resource_id,b.moveto FROM orders AS a INNER JOIN ordered_resource AS b ON a.order_id=b.order_id WHERE a.status IN(2,5) AND b.status NOT IN(3) AND a.order_type=5 AND a.despatch_status=0 AND b.movefrom='".$projuser->projectid."' AND b.despatch_status=0 ORDER BY a.order_id DESC";
