    public function actionDespatchequipment()
    {
        $orders = $_POST['orderid'];
        $orderresources = $_POST['orderres'];
        //foreach($orderresources AS $orderresource):
            $orderresmodel=OrderedResource::find()->where(['order_id' => $orders])->andWhere(['resource_id' => $orderresources])->one();
            $orderresmodel->vehicle_no=$_POST['vehiclenum'];
            $orderresmodel->despatch_status=1;
            $orderresmodel->save(false);
        //endforeach;
        $orderrescount=OrderedResource::find()->where(['order_id' => $orders])->andWhere(['despatch_status' => 0])->count();
        if($orderrescount == 0):
