    public function actionReceiveequipment()
    {
        //$orders = explode(',', urldecode($_POST['orderid']));
        //$orderresources = explode(',', urldecode($_POST['orderres']));
        $orders = $_POST['orderid'];
        $orderresources = $_POST['orderres'];
        //foreach($orderresources AS $orderresource):
            $orderresmodel=OrderedResource::find()->where(['order_id' => $orders])->andWhere(['resource_id' => $orderresources])->one();
            $orderresmodel->received_date=date('Y-m-d',strtotime($_POST['date']));
            $orderresmodel->despatch_status=2;
            $orderresmodel->save(false);
        //endforeach;
        $stat1 = [0,1];
        $orderrescount=OrderedResource::find()->where(['order_id' => $orders])->andWhere(['in','despatch_status', $stat1])->count();
        if($orderrescount==0):
            $ordermodel=Orders::findOne($orders);
            $ordermodel->despatch_status=2;
            $ordermodel->save(false);
        endif;

        $resource = Resources::findOne($orderresources);
        $resource->current_project = $orderresmodel->moveto;
        $resource->save(false);

        $arr=array('result'=>$orders,'error'=>'No');
        return json_encode($arr);
    }

