    public function actionReceiveordersave()
    {

        if(isset($_POST['Save']))
        {   
            $invoice=New Invoice();
            $invoice->Specification=$_POST['Specification'];
            $invoice->Advance=$_POST['Advance'];
            $invoice->Payment=$_POST['Payment'];
            $invoice->Contact=$_POST['Contact'];
            $invoice->DeliveryDate=date('Y-m-d',strtotime($_POST['dateofdelivery']));
            $invoice->Place=$_POST['Place'];
            $invoice->invoice_no=$_POST['Invoiceno'];
            $invoice->order_id=$_POST['orderid'];
            //$invoice->GST=$_POST['CGST'];
            //$invoice->IGST=$_POST['IGST'];
            $order=Orders::findOne($_POST['orderid']);
            $invoice->order_type=$order['order_type'];
            $invoice->project_id=$order['project_id'];
            $invoice->invoice_date=date('Y-m-d',strtotime($_POST['invoicedate']));
            $invoice->transportation_cost=$_POST['transportation'];
            $vendorid=Orders::findOne($_POST['orderid'])->vendor_id;
            $vendorname=Vendors::findOne($vendorid)->Name;
            //echo $vendorname;exit;
            $invoice->vendor=$vendorname;
            if($invoice->save(false)){
            for($i=0;$i<count($_POST['resourceid']);$i++)
            {
                $invresource=New InvoiceResources();
                $invresource->invoice_id=$invoice['invoice_id'];
                $invresource->order_id=$_POST['orderid'];
                $invresource->resource_id=$_POST['resourceid'][$i];
                $invresource->resource_qty=$_POST['resourceqnty'][$i];
                $resdetails=Resources::findOne($_POST['resourceid'][$i]);
                $invresource->resource_acnt=$resdetails['Resource_Acc_Id'];
                if($_POST['resourceqnty'][$i]!=0):
                    $invresource->save(false);
                endif;
                
                $connection = Yii::$app->db;
                //$sql = "SELECT SUM(b.resource_qty) as resqty FROM invoice AS a INNER JOIN invoice_resources AS b ON a.invoice_id=b.invoice_id WHERE a.project_id='".$invoice->project_id."' AND b.resource_id='".$invresource->resource_id."'";
                $sql = "SELECT b.order_id, b.resource_id, b.resource_qty FROM invoice AS a INNER JOIN invoice_resources AS b ON a.invoice_id=b.invoice_id WHERE a.project_id='".$invoice->project_id."' AND b.resource_id='".$invresource->resource_id."' AND a.status!=3";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $datas = $dataReader->readAll();    

                $totqty=0;
                $totamt=0;
                foreach($datas AS $key=>$data):
                 $resitems=OrderedResource::find()->where(['resource_id' => $data['resource_id']])->andWhere(['order_id' => $data['order_id']])->one();
                 $totqty+=$data['resource_qty'];
                 $amt=$resitems['rate']*$data['resource_qty'];  
                 if($resitems['igst']!=0){
                     $gstamount=($amt * $resitems['igst']) / 100;
                    $totamt+=$amt + $gstamount;
                 }
                 else if($resitems['cgst']!=0 or $resitems['sgst']!=0){
                     $gst = $resitems['cgst'] + $resitems['sgst'];
                     $gstamount=($amt * $gst) / 100;
                     $totamt+=$amt + $gstamount;
                 }
                 else{
                    $totamt+= $amt; 
                 }  
                endforeach;
                //echo "res ".$data['resource_id']."-". $totamt."<br>";

                if($totamt!=0 && $totqty!=0){

                    $average = ($totamt) / $totqty;
                    $pricingestimateress=PricingEstimateResourcesNew::find()->where(['project_Id' => $invoice->project_id])->andWhere(['resource_Id' => $invresource->resource_id])->andWhere(['pricing_status' => 0])->all();
                    /*if(count($pricingestimateress)>0):
                        foreach($pricingestimateress AS $pricingestimateres):
                             $pricingestimateres->rate = $average;
                             $pricingestimateres->save(false);
                        endforeach;
                    endif;*/

                }
                
                
            }

            //auto payment due calculation


            $order_deta = Orders::findOne($invoice['order_id']);
            $receive_date = $invoice->invoice_date;



            if($order_deta->creditperiod == "0 Days"){
                $str = 1;
            }else{

            $str = $order_deta->creditperiod;
            } 


            $credit_period = str_replace("Days","",$str);

            $dd = date('Y-m-d', strtotime($receive_date. ' + '.$credit_period.' days'));
            $d = 1;
            $payment_due = date('Y-m-d', strtotime($dd. ' - '.$d. 'days'));

            $invoice->payment_due = date('Y-m-d',strtotime($payment_due));

            

            if($invoice->save(false)){

                    if($invoice->payment_due == date('Y-m-d')){
                     
                        $orderd = orders::findOne($invoice->order_id);

                        $invoiceresources = InvoiceResources::find()->where(['invoice_id'=>$invoice->invoice_id])->andWhere(['order_id'=>$invoice->order_id])->all();
                        $totqty = 0;
                        $totamt=0;
                        foreach($invoiceresources as $invoiceresource)
                        {
                            $resitems=OrderedResource::find()->where(['resource_id' => $invoiceresource->resource_id])->andWhere(['order_id' => $invoiceresource->order_id])->one();

                            $totqty = $totqty + $invoiceresource->resource_qty;
                            $amnt=$resitems->rate*$invoiceresource->resource_qty; 


                            if($resitems['igst']!=0){
                                $gstamount=($amnt * $resitems->igst) / 100;
                                $totamt+=$amnt + $gstamount;

                            }
                            else if($resitems->cgst!=0 or $resitems->sgst!=0){
                                
                                $gst = $resitems->cgst + $resitems->sgst;
                                $gstamount=($amnt * $gst) / 100;
                                $totamt+=$amnt + $gstamount;
                            }
                            else{
                                $totamt+= $amnt; 
                            }  




                        }

                        $payment = New Paymentdue();

                        $payment->order_id = $invoice->order_id;
                        $payment->invoice_id = $invoice->invoice_id;
                        $payment->projectid = $invoice->project_id;
                        $payment->order_type = $invoice->order_type;
                        $payment->order_number = $invoice->invoice_no;
                        $payment->vendor = $invoice->vendor;
                        $payment->duedate = date('Y-m-d',strtotime($invoice->payment_due));
                        $payment->order_date = date('Y-m-d',strtotime($orderd->orderdate));
                        $payment->amount = $totamt;


                        if($payment->save(false)){
                           $invoice->due_status = 1;
                           $invoice->save(false);
                        }


                    }
                }



            //auto payment due calculation end


            $invrescount=InvoiceResources::find()->where(['invoice_id' => $invoice['invoice_id']])->count();
            if($invrescount==0):
                $model=Invoice::findOne($invoice['invoice_id']);
                $model->delete();
            endif;
            //journal entry
            $orderdet=Orders::findOne($invoice['order_id']);
            $crordertype= $invoice['order_type'];
            $crvendor= $orderdet['vendor_id'];
            $crinvoices= $invoice['invoice_id'];
            $crproject= $invoice['project_id'];
            $crorders= $invoice['order_id'];
            $creditvendors=$crvendor;
            $this->Createjournalfun($crordertype,$crvendor,$crinvoices,$crproject,$crorders,$creditvendors);
           } 
        }

        $arr=array('error'=>'No');
        return json_encode($arr); 
    }

    public function actionAutopaymentdue()
    {
       $connection = Yii::$app->db;
        $uid = Yii::$app->user->Id; 
        $usernow = User::find()->where(['id'=>$uid])->one();
        $projects = Projects::find()->where(['Status' => 0])->all();
        if(!empty($projects)){
            foreach($projects as $project){
                $invoices = invoice::find()->where(['order_type'=>1])->andWhere(['status'=>0])->andWhere(['project_id'=>$project->Project_Id])->andWhere(['due_status'=>0])->all();
                $status=0;
                foreach($invoices as $invoice)
                {
                    if($invoice->payment_due == date('Y-m-d')){
                     
                        $orderd = orders::findOne($invoice->order_id);

                        $invoiceresources = InvoiceResources::find()->where(['invoice_id'=>$invoice->invoice_id])->andWhere(['order_id'=>$invoice->order_id])->all();
                        $totqty = 0;
                        $totamt=0;
                        foreach($invoiceresources as $invoiceresource)
                        {
                            $resitems=OrderedResource::find()->where(['resource_id' => $invoiceresource->resource_id])->andWhere(['order_id' => $invoiceresource->order_id])->one();

                            $totqty = $totqty + $invoiceresource->resource_qty;
                            $amnt=$resitems->rate*$invoiceresource->resource_qty; 


                            if($resitems['igst']!=0){
                                $gstamount=($amnt * $resitems->igst) / 100;
                                $totamt+=$amnt + $gstamount;

                            }
                            else if($resitems->cgst!=0 or $resitems->sgst!=0){
                                
                                $gst = $resitems->cgst + $resitems->sgst;
                                $gstamount=($amnt * $gst) / 100;
                                $totamt+=$amnt + $gstamount;
                            }
                            else{
                                $totamt+= $amnt; 
                            }  




                        }

                        $payment = New Paymentdue();

                        $payment->order_id = $invoice->order_id;
                        $payment->invoice_id = $invoice->invoice_id;
                        $payment->projectid = $invoice->project_id;
                        $payment->order_type = $invoice->order_type;
                        $payment->order_number = $invoice->invoice_no;
                        $payment->vendor = $invoice->vendor;
                        $payment->duedate = date('Y-m-d',strtotime($invoice->payment_due));
                        $payment->order_date = date('Y-m-d',strtotime($orderd->orderdate));
                        $payment->amount = $totamt;


                        if($payment->save(false)){
                           $invoice->due_status = 1;
                           $invoice->save(false);
                        }


                    }

                }
            }
        }

    }

