    public function actionPaymentdue()
    {
        $datarows = '';

        $paymentdues = Paymentdue::find()->where(['status'=>0])->all();

        if($paymentdues){

            foreach($paymentdues as $data)
            {

                if($data->order_type == 1)
                {
                    $type = "Purchase Order";
                }
                $datarows.='<div class="row" id="paymentduess'.$data->id.'">
                                <div class="col-md-10">

                                    <div class="row">
                                        <div class="col-md-2 type">
                                            <label>Order Date</label>
                                            <span>'.date('d-m-Y',strtotime($data->order_date)).'</span>
                                        </div>
                                        <div class="col-md-2 type">
                                            <label>Order Type</label>
                                            <span>'.$type.'</span>
                                        </div>
                                        <div class="col-md-2 type">
                                            <label>Order Number</label>
                                            <span>'.$data->order_number.'</span>
                                        </div>
                                        <div class="col-md-2 type">
                                            <label>Vendor Name</label>
                                            <span>'.$data->vendor.'</span>
                                        </div>
                                        <div class="col-md-2 type" style="text-align:end;">
                                            <label>Amount</label>
                                            <span>'.number_format($data->amount,2).'</span>
                                        </div>
                                        <div class="col-md-2 type">
                                            <label>Due On</label>
                                            <span>'.date('d-m-Y',strtotime($data->duedate)).'</span>
                                        </div>

                                    </div>

                                </div>

                                <div class="col-md-2 icon-groups type">

