    public function actionPaymentduetocashbank()
    {

        $id = $_POST['id'];
        $uid = Yii::$app->user->Id;

        $datas = Paymentdue::find()->where(['id'=>$id])->one();

        if($datas->order_type == 1)
        {
            $type = "Purchase Order";
        }

        $groupid=time();

        $accountitem = AccountsItem::find()->where(['LIKE','name',$datas->vendor])->one();

        $accountid = AccountsItem::find()->where(['projectid' => $datas->projectid])->one();
        

        $model=new FinanceRequests();

        $model->User_Id = $uid;
        $model->Amount = $datas->amount;
        $model->Purpose = $type;
        $model->Requested_On = date('Y-m-d');
        $model->project_id = $datas->projectid;
        $model->group_id = $groupid;
        $model->date = date('Y-m-d');
        $model->date_tmp = date('Y-m-d');
        $model->place = $datas->projectid;
        $model->credit_account = $accountitem->id;
        $model->account_id = $accountid->id;

        $model->Status = 0;
        $model->tax = 0;
        $model->igst_tax = 0;


        $model->alloted_amount = $datas->amount;
        $model->netamount = $datas->amount;

        $model->Contra=0;
        $model->payment= $accountid->account_type;
        
        $model->purchase_advance = 0;
        $model->reqforUser = $uid;
        $model->voucher_no = 'v'.$datas->order_number;
        
        if($model->save(false))
        {
            $datas->status = 1;
            $datas->save(false);

            $arr=array('error'=>'No');
            return json_encode($arr);

        }

    }

