    }

    public function ledgerbalance($place,$accountid)
    {
        $connection = Yii::$app->db;
        $initialdate='2013-04-01';
        $enddate=date('Y-m-d');
        $sql1="(SELECT id,account_id,creditacnt,amount,narration,type,contra FROM voucher WHERE (account_id='".$accountid."' OR creditacnt='".$accountid."') AND place='".$place."' AND date BETWEEN '$initialdate' AND '$enddate')
                    UNION
                    (SELECT id,debitacnt AS account_id,creditacnt,amount,narration,type,contra FROM journalvoucher WHERE (debitacnt='".$accountid."' OR creditacnt='".$accountid."') AND project_id='".$place."' AND date BETWEEN '$initialdate' AND '$enddate')";
        //echo $sql1;exit;
        $command=$connection->createCommand($sql1);
        $dataReader=$command->query();
        $databalance=$dataReader->readAll();
        if(count($databalance)>0):
            $credittotal=0;
            $debittotal=0;
            foreach($databalance AS $databal):
                if($databal['contra']==0):
                    if($databal['creditacnt']==$accountid):
                        $credittotal=$credittotal + $databal['amount'];
                    elseif($databal['account_id']==$accountid):
                        $debittotal=$debittotal + $databal['amount'];
                    endif;
                else:
                    if($databal['type']=='Payment' && $databal['creditacnt']==$accountid):
                        $credittotal=$credittotal + $databal['amount'];
                    elseif($databal['type']=='Receipt' && $databal['account_id']==$accountid):
                        $debittotal=$debittotal + $databal['amount'];
                    endif;
                endif;
            endforeach;
            $acountbal=$credittotal - $debittotal;
            if($acountbal<0):
                $db=$acountbal;
            else:
                $db=0;
            endif;
            return $db;
        else:
            $acountbal=0;
            return $acountbal;
        endif;

    }
