            elseif($data['Resource_group_Id']==4):
                $datarows.="<option value='4'>Logistics</option>";
            elseif($data['Resource_group_Id']==5):
                $datarows.="<option value='5'>Construction</option>";
            elseif($data['Resource_group_Id']==8):
                $datarows.="<option value='8'>Overheads</option>";
            endif;
        endforeach;
        if($_POST['date']!=''):
            $date=date('Y-m-d',strtotime($_POST['date']));
        else:
            $date=date('Y-m-d');
        endif;

       
