    public function actionDirectworkersearch()
    {
        $invoices=Invoice::model()->findAll(array('condition'=>'project_id='.$_POST['projectid'].' AND order_type=3 AND status!=2','order'=>'invoice_id DESC'));
        $datarows='';
        if(count($invoices)>0):
            foreach($invoices AS $invoice):
                $resourceitems=InvoiceResources::model()->findAll(array('condition'=>'invoice_id='.$invoice['invoice_id'].' '));
                $total=0;
                foreach($resourceitems AS $resourceitem):
                    $resdetails=Resources::model()->findByPk($resourceitem['resource_id']);
                    $amount=$resdetails['Price'] * $resourceitem['resource_qty'];
                    $total=$total + $amount;
                endforeach;
                $orderdet=Orders::model()->findByPk($invoice['order_id']);
                $vendor=Vendors::model()->findByPk($orderdet['vendor_id'])->Name;
                $project=Projects::model()->findByPk($orderdet['project_id'])->Name;
                $cart=Cart::model()->find(array('condition'=>'Project='.$orderdet['project_id'].' AND Vendor_Id='.$orderdet['vendor_id'].' '));
                $jobcard=Jobcard::model()->findByPk($cart['Job_Id']);
                $datarows.='<tr id="invoicerow'.$invoice['invoice_id'].'">
                    <td>'.date('d-m-Y',strtotime($invoice['invoice_date'])).'</td>
                    <td>'.$project.'</td>
                    <td>'.$vendor.'</td>
                    <td>'.$jobcard['activity'].'</td>
                    <td>'.number_format((float)$total, 2).'</td>
                    <td><button type="button" class="btn btn-danger" id="addmuster" data-id="'.$jobcard['app_activity'].'" value="'.$invoice['invoice_id'].'">Raise Muster Roll</button></td>
                    </tr>';
            endforeach;
        else:
            $datarows='<tr><td colspan="9" style="text-align: center">No Direct Work Orders Found</td></tr>';
        endif;
        $arr=array('result'=>$datarows,'error'=>'No');
        echo json_encode($arr);

    }

    public function actionWorkorderbillshistory()
    {

        $uid = Yii::$app->user->Id; 
        $usernow = User::find()->where(['id'=>$uid])->one();
        $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();

        if(!empty($projuser)){

            $invoices=WorkorderBills::find()->where(['place' => $projuser->projectid])->andWhere(['order_type' => 2])->andWhere(['delete_status' => 0])->andWhere(['status' => 1])->orderBy(['bill_id' => SORT_DESC])->all();

            $datarows='';

            if(count($invoices)>0):

                $totalgrossamt=0;
                $totalgstamt=0;
                $totalnetamt=0;

                foreach($invoices AS $key=>$invoice):

                    if($invoice['status']==0):
                        $style="disabled";
                    else:
                        $style="";
                    endif;


                    $resourceitems=WorkorderItems::find()->where(['bill_id' => $invoice['bill_id']])->andWhere(['delete_status' => 0])->all();
                    $total=0;
                    $grossamount=0;
                    $gst_amount=0;

                    foreach($resourceitems AS $resourceitem):

                        $resdetails=Resources::findOne($resourceitem['resource_id']);
                        $orderitems=OrderedResource::find()->where(['order_id' => $resourceitem['order_id']])->andWhere(['resource_id' => $resourceitem['resource_id']])->one();
                        $resource_qty = $resourceitem['resource_qty'];
                        $amount=$orderitems['rate'] * $resourceitem['resource_qty'];
                        //$amount=$resdetails['Price'] * $resourceitem['resource_qty'];
                        if($orderitems['cgst']!=0 & $orderitems['sgst']!=0):
                            $gstvalue=$orderitems['cgst'] + $orderitems['sgst'];
                        elseif($orderitems['igst']!=0):
                            $gstvalue=$orderitems['igst'];
                        else:
                            $gstvalue=0;
                        endif;
