     public function actionWorkorderbills(){

        $connection = \Yii::$app->db;
        $uid = Yii::$app->user->Id; 
        $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();


        //$orders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->orderBy(['order_id'=> 'SORT_DESC'])->groupBy(['project_id'])->all();
        $datarows='';
        
        //foreach ($orders as $order):
            //$projectorders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->andWhere(['project_id'=>$order['project_id']])->all();
            $_POST['type'] = 'dewrkr';

            if($_POST['type'] == 'depor')
            {
                $projectorders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->andWhere(['project_id'=>$projuser->projectid])->andWhere(['order_type'=>1])->orderBy(['order_id'=>SORT_DESC])->all();

            }else if($_POST['type'] == 'dewrkr')
            {
                $projectorders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->andWhere(['complete_status'=>0])->andWhere(['project_id'=>$projuser->projectid])->andWhere(['order_type'=>2])->orderBy(['order_id'=>SORT_DESC])->all();

            }else if($_POST['type'] == 'dedir')
            {
                $projectorders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->andWhere(['project_id'=>$projuser->projectid])->andWhere(['order_type'=>3])->orderBy(['order_id'=>SORT_DESC])->all();

            }else if($_POST['type'] == 'delease')
            {
                $projectorders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->andWhere(['project_id'=>$projuser->projectid])->andWhere(['order_type'=>4])->orderBy(['order_id'=>SORT_DESC])->all();

            }else if($_POST['type'] == 'dedesp')
            {
                $projectorders=Orders::find()->Where(['in','status',[1,2]])->andWhere(['in','des_status',[0,1]])->andWhere(['delete_status'=>0])->andWhere(['project_id'=>$projuser->projectid])->andWhere(['order_type'=>5])->orderBy(['order_id'=>SORT_DESC])->all();

            }else {
                
            }


            $projects=Projects::findOne($projuser->projectid);
            $project=$projects['Name'];
            $datarows.='<tr><td colspan="10" style="background-color: #f7f8fc;"><b>'.$project.'</b></td></tr>';

            $count=0;
            if($projectorders):

            foreach ($projectorders as $projectorder):
                if($projectorder['order_type']==1):
                    $ordertype='Purchase Order';
                elseif($projectorder['order_type']==2):
                    $ordertype='Work Order';
                elseif($projectorder['order_type']==3):
                    $ordertype='Direct Workers Order';
                elseif($projectorder['order_type']==4):
                    $ordertype='Lease Order';
                else:
                    $ordertype='Despatch Order';
                endif;
                $resourceitems=OrderedResource::find()->Where(['order_id'=>$projectorder['order_id']])->all();

                $amount=0;
                $gst=0;


                foreach($resourceitems AS $resourceitem):
                    $amount=$amount + $resourceitem['amount'];
                    if($resourceitem['cgst']!=0 & $resourceitem['sgst']!=0):
                        $gst=$resourceitem['cgst'] + $resourceitem['sgst'];
                    elseif($resourceitem['igst']!=0):
                        $gst=$resourceitem['igst'];
                    else:
                        $gst=0;
                    endif;
                endforeach;

                //activity name

                $connection = \Yii::$app->db; 
                $sql="SELECT resource_id, COUNT(*) as count FROM ordered_resource where order_id=".$projectorder['order_id']." GROUP BY rate,resource_id HAVING COUNT(*) > 1";
                $command = $connection->createCommand($sql);
                $dataReader = $command->query();
                $dataProvider = $dataReader->read();

                if($dataProvider):
                    if($dataProvider['count']==0):
                        $resourceitems=OrderedResource::find()->Where(['order_id'=>$projectorder['order_id']])->all();
                    else:
                        /*$resourceitems=OrderedResource::find()->Where(['order_id'=>$projectorder['order_id']])->andWhere(['group' => 'resource_id'])->all();*/

                        $resourceitems=OrderedResource::find()->Where(['order_id'=>$projectorder['order_id']])->all();
                    endif;
                endif;

                
                    $jobcardid='';
                    $activityName='';
                    foreach($resourceitems AS $key=>$orderre):
                        if($key==0):
                            $jobcardid.=$orderre['jobcard_id'];
                        else:
                            $jobcardid.=",".$orderre['jobcard_id'];
                        endif;
                    endforeach;
                    $jobcard = Jobcard::find()->where(['in','job_id',$jobcardid])->one();
                    if($jobcard):
                        $activityName = $jobcard['activity'];
                    endif;

                //end

                $vendors=Vendors::findOne($projectorder['vendor_id']); 
                $vendor= $vendors['Name'];


                $gstamount=($amount * $gst) / 100;
                $amntincgst=$amount + $gstamount;
                $datarows.='<tr id="orderitemrow'.$projectorder['order_id'].'">
                    <td><span class="number despatch-number">'.++$count.'</span></td>
                    <td><span class="date"><em class="cal-icon icon-calendar1"></em>'.date('d-m-Y',strtotime($projectorder['date'])).'</span></td>
                    <td>'.$activityName.'</td>
                    
                    <td>'.$vendor.'</td>
                    <td style="text-align: right;">'.number_format((float)$amntincgst, 2).'</td>
                    <td class="icon-groups icon-order">
                    ';
                    if($projectorder['order_type'] == 3 ||$projectorder['order_type'] == 2 ||$projectorder['order_type'] == 4 || $projectorder['order_type'] == 1 )
                    {
                        $datarows.='<a href="javascript:;" class="btn btn-primary viewworkbillitems" data-value="'.$projectorder['order_id'].'" data-id="'.$projectorder['order_type'].'"  title="View" style="min-width: min-content;">Raise Bills</a>';
                    }
                else{
                    // despatch order - no view link
                    }
                $datarows.='</td>';
                    
                $datarows.='</tr>';
            endforeach;
            else:
            $datarows='<tr><td colspan="9" style="text-align: center">No Orders Found</td></tr>';
            endif;
            //endforeach;
            $arr=array('result'=>$datarows,'error'=>'No');
            //echo json_encode($arr);
            return json_encode($arr);
     }


