    public function actionApproveorderbills()
    {
        $ordid = $_POST['ordid'];
        $bill_id = $_POST['ordbillid'];
        $count = count($_POST['resourceid']);

        for($i=0;$i<$count;$i++)
        {
            $wbillitems = WorkorderItems::find()->where(['bill_id'=>$bill_id])->andWhere(['order_id'=>$ordid])->andWhere(['resource_id'=>$_POST['resourceid'][$i]])->andWhere(['delete_status'=>0])->one();
            $wbillitems->resource_qty = $_POST['resourceqnty'][$i]; 
            $wbillitems->save(false);

            /*$wbills=WorkorderBills::find()->andWhere(['order_id'=>$ordid])->andWhere(['order_type'=>2])->andWhere(['delete_status'=>0])->one();
            if(isset($_POST['billno']))
                $wbills->bill_no = $_POST['billno'];
            $wbills->status =1;
            $wbills->save(false);*/
        }

        $wbills=WorkorderBills::find()->where(['bill_id'=>$bill_id])->one();
        if(isset($_POST['billno']))
            $wbills->bill_no = $_POST['billno'];
        if(isset($_POST['no_of_workers']))
            $wbills->no_of_workers = $_POST['no_of_workers'];
        if(isset($_POST['no_of_equipments']))
            $wbills->no_of_equipments = $_POST['no_of_equipments'];
        $wbills->status = 1;
        $wbills->other_deductions = $_POST['other_deductions']; 
        $wbills->save(false);

        //$wbills=WorkorderBills::find()->andWhere(['order_id'=>$ordid])->andWhere(['order_type'=>2])->andWhere(['delete_status'=>0])->one();

        //journal entry
        $orderdet=Orders::findOne($wbills['order_id']);
        $crordertype= $wbills['order_type'];
        $crvendor= $orderdet['vendor_id'];
        $crinvoices= $wbills['bill_id'];
        $crproject= $wbills['place'];
        $crorders= $wbills['order_id'];
        $creditvendors=$crvendor;
        $this->Createjournalfun($crordertype,$crvendor,$crinvoices,$crproject,$crorders,$creditvendors);  

        $arr=array('error'=>'No');
        return json_encode($arr); 
    }

     public function actionCloseorderbills()
    {
        $ordid = $_POST['orderid'];

        $order = Orders::findOne($ordid);
        $order->complete_status = 1;
        $order->save(false);

        $arr=array('error'=>'No');
        return json_encode($arr); 
    }

    public function actionPurchasehostory()
    {
        $uid = Yii::$app->user->Id; 
        
        $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
        if(!empty($projuser)){
            $projectinfo = Projects::findOne($projuser->projectid);
            $vendor="";
            if($_POST['vendor']!=''){
                $connection = \Yii::$app->db;
                $sqlser ="SELECT inv.* FROM `invoice` as inv INNER JOIN invoice_resources as inr on inv.invoice_id=inr.invoice_id INNER JOIN resources as r on r.Resource_Id=inr.resource_id WHERE inv.`project_id`='".$projuser->projectid."' AND inv.`order_type`=1 AND r.Name LIKE '%".$_POST['vendor']."%' ORDER BY inv.`invoice_id` DESC";
                $command=$connection->createCommand($sqlser);
                $dataReader=$command->query();
                $invoices=$dataReader->readAll();

            }else{
                $invoices=Invoice::find()->where(['project_id' => $projuser->projectid])->andWhere(['order_type' => 1])->orderBy(['invoice_id' => SORT_DESC])->all();
            }
            $datarows='';
