                                        <label></label>
                                    </div>
                                    
                                </div>
                            </div>
                    ';
                foreach($invoices AS $invoice):
                    $resourceitems=InvoiceResources::find()->where(['invoice_id' => $invoice['invoice_id']])->all();
                    $total=0;
                    $jobids = array();
                    $jobids_string = '';
