                        $resdetails=OrderedResource::find()->where(['order_id' => $resourceitem['order_id']])->andWhere(['resource_id' => $resourceitem['resource_id']])->one();

                        if (in_array($resdetails->jobcard_id, $jobids))
                        {
                            $resdetails=OrderedResource::find()->where(['order_id' => $resourceitem['order_id']])->andWhere(['resource_id' => $resourceitem['resource_id']])->andWhere('jobcard_id NOT IN('.$jobids_string.')')->one();
                            if($key==0):
                                $jobids_string.=$resdetails->jobcard_id;
                            else:
                                $jobids_string.=','.$resdetails->jobcard_id; 
                            endif;
                            array_push($jobids,$resdetails->jobcard_id);
                        }
                        else{
                            if($key==0):
                                $jobids_string.=$resdetails->jobcard_id;
                            else:
                                $jobids_string.=','.$resdetails->jobcard_id;
                            endif;
                            array_push($jobids,$resdetails->jobcard_id);
                        }
                        
                        $amount=$resdetails['rate'] * $resourceitem['resource_qty'];
                        if($resdetails['cgst']!=0 & $resdetails['sgst']!=0):
                            $gstvalue=$resdetails['cgst'] + $resdetails['sgst'];
                        elseif($resdetails['igst']!=0):
