                        endif;
                        $gstamount=($amount * $gstvalue) / 100;
                        $amntincgst=$amount + $gstamount;
                        $total=$total + $amntincgst;
                    endforeach;
                    $orderdet=Orders::findOne($invoice['order_id']);
                    $vendor=Vendors::findOne($orderdet['vendor_id'])->Name;

                    $resName = Resources::findOne($resourceitem['resource_id'])->Name;
                    
                    //$cart=Cart::model()->find(array('condition'=>'Project='.$orderdet['project_id'].' AND Vendor_Id='.$orderdet['vendor_id'].' '));
                    $orderres=OrderedResource::find()->where(['order_id' => $invoice['order_id']])->all();
                    $jobcardid='';
                    foreach($orderres AS $key=>$orderre):
                        if($key==0):
                            $jobcardid.=$orderre['jobcard_id'];
                        else:
                            $jobcardid.=",".$orderre['jobcard_id'];
                        endif;
                    endforeach;
                    if($jobcardid!='' && $jobcardid!=0):
