                                    </div>
                                </div>
                       
                    
                    
                            </div> ';
                endforeach;
            else:
                $datarows='<div class="row"><div class="col-md-12"><div class="text-center">No Purchase History Found</div></div></div>';
            endif;
            $arr=array('result'=>$datarows,'projectinfo'=>$projectinfo->Name,'error'=>'No');
            return json_encode($arr);
        }else{
            $datarows='<div style="text-align: center;">No Project Selected</div>';
            $arr=array('result'=>$datarows,'error'=>'No');
            return json_encode($arr);
        }    
