    public function actionListestimateitems()
    {
        $connection = CActiveRecord::getDbConnection();
        $sqltemvals = "SELECT * FROM workgroup_activities WHERE project_Id='".$_POST['projectid']."' AND estimate=1 AND pricing_status=0 GROUP BY process_Id ORDER BY process_Id ASC ";
        $command = $connection->createCommand($sqltemvals);
        $dataReader = $command->query();
        $dataProvider = $dataReader->readAll();
