    public function actionPricingestimate()
    {
        if (isset($_POST['itemid'])) {
            $connection = CActiveRecord::getDbConnection();
            $estimatecount=PricingEstimate::model()->count(array('condition'=>'project_Id='.$_POST['Project_Id'].''));
            //echo $estimatecount;exit;
            if($estimatecount > 0):
                for ($i = 0; $i < count($_POST['itemid']); $i++) {
                    $itemid = $_POST['itemid'][$i];
                    $activityid = $_POST['activityid'][$i];
                    $processid = $_POST['processid'][$i];
                    $estimateactcount=PricingEstimate::model()->count(array('condition'=>'project_Id='.$_POST['Project_Id'].' AND activity_Id='.$itemid.''));
                    if($estimateactcount > 0):
                        $sql="UPDATE pricing_estimate SET activity_qty='".$_POST['quantity'][$i]."',est_activity_Id='".$activityid."' WHERE activity_Id='".$itemid."' ";
                        $command = $connection->createCommand($sql);
                        $dataReader = $command->query();
                        $estrescount=PricingEstimateResources::model()->count(array('condition'=>'project_id='.$_POST['Project_Id'].' AND activity_id='.$itemid.' '));
                        if($estrescount==0):
                            if($processid==2):
                                $sqltemvals="SELECT a.Resource_Id,a.Name AS resource,a.Unit,a.ResourceType_Id,a.Resource_Location,b.PSR_Quantity AS Quantity,b.PSR_Price AS Price,b.PSR_Actual_Price AS actual_price FROM resources AS a
                                INNER JOIN project_setup_resources AS b ON  a.Resource_Id=b.PSR_Resource_Id
                                WHERE b.PSR_PS_Id='".$activityid."' ORDER BY a.Resource_Id";
                            elseif($processid==3):
                                $sqltemvals="SELECT a.Resource_Id,a.Name AS resource,a.Unit,a.ResourceType_Id,a.Resource_Location,b.Quantity,b.Price,b.actual_price FROM resources AS a
                                INNER JOIN product_resources AS b ON  a.Resource_Id=b.Resource_Id
                                WHERE b.Product_Id='".$activityid."' ORDER BY a.Resource_Id";
                            elseif($processid==4):
                                $sqltemvals="SELECT a.Resource_Id,a.Name AS resource,a.Unit,a.ResourceType_Id,a.Resource_Location,b.Quantity,b.Price,b.actual_price FROM resources AS a
                                INNER JOIN logistics_resources AS b ON  a.Resource_Id=b.Resource_Id
