                            $command=$connection->createCommand($sqltemvals);
                            $dataReader=$command->query();
                            $resourcesadded=$dataReader->readAll();
                            foreach($resourcesadded AS $resource):
                                $sql = "INSERT INTO pricing_estimate_resources (activity_id,resource_Id,resourcetype_Id,quantity,rate,project_id,est_activity_Id,process_Id) VALUES('" . $itemid . "','" . $resource['Resource_Id'] . "','".$resource['ResourceType_Id']."','" . $resource['Quantity'] . "','" . $resource['actual_price'] . "','" . $_POST['Project_Id'] . "','".$activityid."','".$processid."')";
