    public function actionGetprocess()
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "SELECT DISTINCT(process_Id) FROM pricing_estimate WHERE project_Id='".$_POST['projectid']."' AND activity_qty!=0 ORDER BY process_Id ASC ";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $dataProvider = $dataReader->readAll();
        $datarows="<option value='none'>Select Process</option>";
        foreach($dataProvider AS $data):
            if($data['process_Id']==2):
                $datarows.="<option value='".$data['process_Id']."'>Project Set-up</option>";
            elseif($data['process_Id']==3):
                $datarows.="<option value='".$data['process_Id']."'>Production</option>";
            elseif($data['process_Id']==4):
                $datarows.="<option value='".$data['process_Id']."'>Logistic</option>";
            elseif($data['process_Id']==5):
                $datarows.="<option value='".$data['process_Id']."'>Construction</option>";
            elseif($data['process_Id']==8):
                $datarows.="<option value='".$data['process_Id']."'>Overheads</option>";
            endif;
        endforeach;

        $arr = array('result' => $datarows, 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionGetactivities()
    {
        $connection = CActiveRecord::getDbConnection();
        $sql = "SELECT * FROM pricing_estimate WHERE project_Id='".$_POST['projectid']."' AND process_Id='".$_POST['processid']."' AND activity_qty!=0 ORDER BY process_Id ASC ";
        //echo $sql;exit;
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $dataProvider = $dataReader->readAll();
        $datarows="<option value='none'>Select Activity</option>";
        foreach($dataProvider AS $data):
            $activityname=WorkgroupActivities::model()->findByPk($data['activity_Id'])->activity_Name;
            $activity_Id=WorkgroupActivities::model()->findByPk($data['activity_Id'])->activity_Id;
            if($data['process_Id']==2):
                if($activityname==''):
                    $name= ProjectSetup::model()->findByPk($activity_Id)->PS_Name;
                else:
                    $name=$activityname;
                endif;
                $datarows.="<option value='".$data['activity_Id']."'>".$name."</option>";
            elseif($data['process_Id']==3):
                if($activityname==''):
                    $name= Products::model()->findByPk($activity_Id)->Name;
                else:
                    $name=$activityname;
                endif;
                $datarows.="<option value='".$data['activity_Id']."'>".$name."</option>";
            elseif($data['process_Id']==4):
                if($activityname==''):
                    $name= Logistics::model()->findByPk($activity_Id)->Name;
                else:
                    $name=$activityname;
                endif;
                $datarows.="<option value='".$data['activity_Id']."'>".$name."</option>";
            elseif($data['process_Id']==5):
                if($activityname==''):
                    $name= Construction::model()->findByPk($activity_Id)->CO_Name;
                else:
                    $name=$activityname;
                endif;
                $datarows.="<option value='".$data['activity_Id']."'>".$name."</option>";
            elseif($data['process_Id']==8):
                if($activityname==''):
                    $name= Overheads::model()->findByPk($activity_Id)->Name;
                else:
                    $name=$activityname;
                endif;
                $datarows.="<option value='".$data['activity_Id']."'>".$name."</option>";
            endif;
        endforeach;

        $arr = array('result' => $datarows, 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionGetresources()
    {
        $connection = CActiveRecord::getDbConnection();
        $sqltemvals = "SELECT a.Name AS resource,a.Unit,a.Resource_Id,a.ResourceType_Id,b.* FROM resources AS a
                INNER JOIN pricing_estimate_resources AS b ON  a.Resource_Id=b.resource_Id
                WHERE b.activity_id='" . $_POST['activity'] . "' ORDER BY a.Name";
