        echo json_encode($arr);
    }

    public function actionSaveCashbill()
    {
        if(isset($_POST['cashbillitem'])){
            for($i=0;$i<count($_POST['cashbillitem']);$i++){
                $model=New Cashbills();
                $model->date=date('Y-m-d');
                $model->created_by=Yii::app()->user->id;
                //$model->activity=$_POST['cashactivity'];
                //$model->resource=$_POST['cashresource'];
                $model->accounthead=$_POST['cashbillaccount'];
                $model->balance=$_POST['balance'];
                $model->bill_no=$_POST['invoicenum'][$i];
                $model->vendor=$_POST['cashbillparty'][$i];
                $model->purpose=$_POST['cashbillitem'][$i];
                $model->rate=$_POST['cashbillrate'][$i];
                $model->quantity=$_POST['cashbillqty'][$i];
                $model->amount=$_POST['cashbillamount'][$i];
                $model->sgst=$_POST['cashbillgst'][$i];
                $model->igst=$_POST['cashbilligst'][$i];
                //$model->project_id=$_POST['cashprojectlist'];
                $model->advance_id=$_POST['advanceid'];
                $model->isNewRecord = true;
                $model->save(false);
            }
        }
        $arr = array('result' => $model->cashbill_id, 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionSaveCashadvance()
    {
        if(isset($_POST['Amount'])){
            $mode=$_POST['mode'];
            if($mode=='draft'):
                $status=5;
            else:
                $status=0;
            endif;
            $groupid=time();
            $userid=Yii::app()->user->id;
            $userproj=UserProjects::model()->find(array('condition'=>'userid='.$userid.' '))->projectid;
            $useracnt=UserAccounts::model()->find(array('condition'=>'user_id='.$userid.' '))->account_id;
            //echo "proj: ".$userproj." acnt: ".$useracnt;exit;
            for($i=0;$i<count($_POST['Amount']);$i++){
                $model=new Cashadvance();
                $model->date=date('Y-m-d',strtotime($_POST['Advance_Date']));
                $model->created_by=$userid;
                //$model->accounthead=$useracnt;
                $model->accounthead=$_POST['schedule'][$i];
                $model->purpose=$_POST['Purpose'][$i];
                $model->amount=$_POST['Amount'][$i];
                //$model->paymenttype=$_POST['paymenttype'][$i];
                $model->project_id=$userproj;
                //$model->project_id=$_POST['advanceprojlist'];
                $model->group_id=$groupid;
                $model->status=$status;
                $model->isNewRecord = true;
                $model->save(false);
            }
        }
        $arr = array('result' => $model->cashadvance_id, 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionUpdateCashadvance()
    {
        if(isset($_POST['Amount'])){
            $mode=$_POST['mode'];
            if($mode=='draft'):
                $status=5;
            else:
                $status=0;
            endif;
            $advancemodel=Cashadvance::model()->find(array('condition'=>'group_id='.$_POST['groupid'].' '));
            $userid=Yii::app()->user->id;
            $userproj=UserProjects::model()->find(array('condition'=>'userid='.$userid.' '))->projectid;
            for($i=0;$i<count($_POST['Amount']);$i++){
                $model=Cashadvance::model()->findByPk($_POST['advanceid'][$i]);
                $model->date=date('Y-m-d',strtotime($_POST['Advance_Date']));
                $model->accounthead=$_POST['schedule'];
                $model->purpose=$_POST['Purpose'][$i];
                $model->amount=$_POST['Amount'][$i];
                $model->project_id=$userproj;
                $model->status=$status;
                $model->save(false);
            }
            for($i=0;$i<count($_POST['newAmount']);$i++){
                $model=new Cashadvance();
                $model->date=date('Y-m-d',strtotime($_POST['Advance_Date']));
                $model->created_by=$advancemodel['created_by'];
                $model->accounthead=$_POST['schedule'];
                $model->purpose=$_POST['newPurpose'][$i];
                $model->amount=$_POST['newAmount'][$i];
                $model->project_id=$userproj;
                $model->group_id=$_POST['groupid'];
                $model->status=$status;
                $model->isNewRecord = true;
                $model->save(false);
            }
        }
        $arr = array('result' => $_POST['groupid'], 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionCashbillsearch()
    {
        $cashbills=Cashbills::model()->findAll(array('condition'=>'project_id='.$_POST['projectid'].' '));
        $datarows='';
        if(count($cashbills)>0):
            foreach($cashbills AS $key=>$cashbill):
                $user=User::model()->findByPk($cashbill['created_by'])->username;
                $activity=WorkgroupActivities::model()->findByPk($cashbill['activity']);
                $activity_Id=WorkgroupActivities::model()->findByPk($cashbill['activity'])->activity_Id;
                if($activity['process_Id']==2):
                    if($activity['activity_Name']==''):
                        $name= ProjectSetup::model()->findByPk($activity_Id)->PS_Name;
