                    else:
                        $name=$activity['activity_Name'];
                    endif;
                elseif($activity['process_Id']==8):
                    if($activity['activity_Name']==''):
                        $name= Overheads::model()->findByPk($activity_Id)->Name;
                    else:
                        $name=$activity['activity_Name'];
                    endif;
                endif;
                $datarows.='<tr>
                            <td>'.($key + 1).'</td>
                            <td>'.date('d-m-Y',strtotime($cashbill['date'])).'</td>
                            <td>'.$user.'</td>
                            <td>'.$name.'</td>
                            <td>'.$cashbill['purpose'].'</td>
                            <td>'.AccountsItem::model()->findByPk($cashbill['accounthead'])->name.'</td>
                            <td>'.number_format($cashbill['amount'], 2).'</td>

                            </tr>';
            endforeach;
        else:
            $datarows.='<tr><td colspan="7" style="text-align: center;">No Cashbills Found</td></tr>';
        endif;
        $arr = array('result' => $datarows, 'error' => 'No');
        echo json_encode($arr);
    }

    public function actionDespatchorder()
    {
        $connection = CActiveRecord::getDbConnection();
        $sqltemvals = "SELECT a.Name AS resource,a.Unit,a.Resource_Id,a.ResourceType_Id,b.* FROM resources AS a
                INNER JOIN pricing_estimate_resources AS b ON  a.Resource_Id=b.resource_Id
                WHERE b.project_id='" . $_GET['project'] . "' AND a.ResourceType_Id='26' ORDER BY a.Name";
        $command = $connection->createCommand($sqltemvals);
        $dataReader = $command->query();
        $resourcesadded = $dataReader->readAll();
        $options='<option value="none">Select Item</option>';
        foreach($resourcesadded AS $resources):
            $options.='<option value="'.$resources['Resource_Id'].'">'.$resources['resource'].'</option>';
        endforeach;
        $sql = "SELECT Project_Id,Name FROM projects where status IN (0,111) AND Project_Delete_Status IN (0,111) ORDER BY Project_Id ASC, Name ASC ";
        $command = $connection->createCommand($sql);
        $dataReader = $command->query();
        $projects = $dataReader->readAll();
        $projoptions='<option value="none">Select Project</option>';
        foreach($projects AS $project):
            $projoptions.='<option value="'.$project['Project_Id'].'">'.$project['Name'].'</option>';
        endforeach;
        $sql="SELECT id,username FROM users ORDER BY username ASC ";
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $users=$dataReader->readAll();
        $useroptions='<option value="none">Select User</option>';
        foreach($users AS $user):
            $useroptions.='<option value="'.$user['id'].'">'.$user['username'].'</option>';
        endforeach;
        if(isset($_POST['submit'])){
            $model=New Orders();
            $model->vendor_id=$_POST['vendor'];
            $model->project_id=$_GET['project'];
            $model->date=date('Y-m-d');
            $model->order_type=$_POST['ordertype'];
            $model->gstn_no=$_POST['gstn_no'];
            $receivedby=User::model()->findByPk($_POST['receivedby'])->username;
            $raisedby=User::model()->findByPk($_POST['raisedby'])->username;
            $model->receivedby=$receivedby;
            $model->raisedby=$raisedby;
            $model->status=5;
            //print_r($model);exit;
            $model->save(false);
            for($i=0;$i<count($_POST['resource']);$i++)
            {
                $orderres=New OrderedResource();
                $orderres->order_id=$model->order_id;
                $res=Resources::model()->findByPk($_POST['resource'][$i]);
                $orderres->resource_id=$_POST['resource'][$i];
                $orderres->resource_name=$res['Name'];
                $orderres->unit=$res['Unit'];
                $orderres->rate=$res['Price'];
                //$orderres->qnty=$cart['Qnty'];
                $orderres->amount=$res['Price'];
                $orderres->date=date('Y-m-d',strtotime($_POST['date'][$i]));
                $movefrom=Projects::model()->findByPk($_POST['from'][$i])->Name;
                $moveto=Projects::model()->findByPk($_POST['to'][$i])->Name;
                $orderres->movefrom=$movefrom;
                $orderres->moveto=$moveto;
                $orderres->vehicle_no=$_POST['vehicle_no'][$i];
                $orderres->status=5;
                $orderres->save(false);
            }
            $this->redirect(array('projects/report'));
        }
        $this->render('despatch',array(
            'options'=>$options,
            'projoptions'=>$projoptions,
            'useroptions'=>$useroptions,
        ));
    }

