                $datarows.="<tr><th></th><th colspan='4'>Group Total</th><th  id='totaliow".str_replace(' ','',$process)."cost' style='text-align: right'>" . number_format($subtot,2) . "</th><th colspan='2'></th><th colspan='2'></th></tr>";
            endif;
            $pricesum=$pricesum + $subtot;
