                    ";
        $arr=array('result'=>$datarows,'wbsname'=>$wbsname,'error'=>'No');
        echo json_encode($arr);
    }

    public function actionPrintmuster($id)
    {
        $connection = \Yii::$app->db;
        $sql1="SELECT a.name,a.trade_id,a.hours,a.order_id,a.othours,a.deduction,a.wages,";
        $sql1.="c.Name,a.rate FROM musterroll as a left join resources as c on a.trade_id=c.Resource_Id WHERE groupid='$id'";
        //echo $sql1;
        $command=$connection->createCommand($sql1);
        $dataReader=$command->query();
        $dataProvider=$dataReader->readAll();
        $sql="SELECT DATE_FORMAT(a.date,'%d %b %y') AS date,a.process,a.activity_id,a.order_id,b.username FROM musterroll as a left join user as b on a.userid=b.id WHERE groupid='".$id."' ";
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $muster=$dataReader->read();
        $orders=OrderedResource::find()->where(['order_id' => $muster['order_id']])->all();
        $jobids='';
        foreach($orders AS $key=>$order):
            if($key==0):
                $jobids.=$order['jobcard_id'];
            else:
                $jobids.=','.$order['jobcard_id'];
            endif;
        endforeach;
        if($jobids!=''):
            $jobmodel=Jobcard::find()->where(['in','job_id',$jobids])->one();
            $actname=$jobmodel['activity'];
        else:
            $actname='';
        endif;

        $datarows="";
        $totalwages=0;
        $totalded=0;
        $totalnet=0;
        $date=$muster['date'];
        foreach($dataProvider AS $key=>$data):
            $orderres=OrderedResource::find()->where(['order_id' => $data['order_id']])->andWhere(['resource_id' => $data['trade_id']])->one();
            $rate=$orderres['rate'];
            $otrate=$orderres['ot_rate'];
            $netwages=$data['wages'] - $data['deduction'];
            $datarows.="<tr>
                        <td style='text-align: center'>".($key + 1)."</td>
                        <td>".$data['name']."</td>
                        <td>".$data['Name']."</td>
                        <td style='text-align: center'>".$data['hours']."</td>
                        <td style='text-align: center'>".$data['rate']."</td>
                        <td style='text-align: center'>".$data['othours']."</td>
                        <td style='text-align: center'>".$otrate."</td>
                        <td style='text-align: center'>".number_format((float)$data['wages'], 2)."</td>
                        <td style='text-align: center'>".number_format((float)$data['deduction'], 2)."</td>
                        <td style='text-align: center'>".number_format((float)$data['wages'], 2)."</td>
                        <td></td>
                        </tr>";
            $totalwages=$totalwages + $data['wages'];
            $totalded=$totalded + $data['deduction'];
            $totalnet=$totalnet + $netwages;
        endforeach;
        $datarows.="<tr><td><b>Total</b></td><td colspan='6'></td>
                    <td><b>".number_format((float)$totalwages, 2)."</b></td>
                    <td><b>".number_format((float)$totalded, 2)."</b></td>
                    <td><b>".number_format((float)$totalnet, 2)."</b></td>
                    <td></td></tr>";
        $html="<style>table,td{border:1px solid black;border-collapse:collapse}</style><br>
                <table width='900' cellpadding='5px' class='table table-bordered' style='display: table;font-size: 10pt;'><tbody>
                <tr>
                  <th colspan='8' align='center' style='padding-top: 15px;padding-left: 200px'>GEO-TECH OFFSHORE STRUCTURES.(P) LTD<br><span style='font-weight: normal;font-size: 12px'>8th Floor, KSHB Office Complex, Panampilly Nagar<br>Phone: 0484 231 9161</span><br><br><h3>Muster Roll</h3><br></th>
                  <th colspan='3' align='right' style='padding-right: 25px;'><img src=".Yii::$app->request->baseUrl."/images/logo_geotech.jpg alt='logo' style='width: 100px;'></th>
                </tr>
                <tr>
                <th colspan='8' align='center' style='padding-top: 15px;padding-left: 200px'>".$actname."</th>
                <th colspan='3'></th>
                </tr>
                <tr>
                <th colspan='8' align='center' style='padding-top: 15px;padding-left: 200px'></th>
                <th colspan='3' align='right' style='padding-right: 25px'>Date : ".date('d-m-Y',strtotime($date))."</th>
                </tr>";
        $html.="<tr>
                <td style='text-align: center;padding-left: 25px;width: 5%'><b>Sl.No.</b></td>
                <td style='text-align: center'><b>Name of the Employee</b></td>
                <td style='text-align: center'><b>Trade</b></td>
                <td style='width: 10%;text-align: center'><b>Days Worked</b></td>
                <td style='width: 10%;text-align: center'><b>Rate (Rs)</b></td>
                <td style='width: 10%;text-align: center'><b>Overtime Hours</b></td>
                <td style='width: 10%;text-align: center'><b>OT Rate (Rs)</b></td>
                <td style='width: 10%;text-align: center'><b>Wages Earned (Rs)</b></td>
                <td style='width: 10%;text-align: center'><b>Deductions (Rs)</b></td>
                <td style='width: 10%;text-align: center'><b>Net Wages Earned (Rs)</b></td>
                <td style='text-align: center'><b>Signature</b></td>
                </tr>";
        $html.=$datarows;
        $html.='</tbody></table>';
        //echo $html;exit;
        $pdf = new Pdf();
        $mpdf = $pdf->api;
        $mpdf->WriteHtml($html); 
        $mpdf->Output('musterroll.pdf','I');
    }

