    public function actionIowestimate()
    {
        if (isset($_POST['itemid'])) {
            $connection = CActiveRecord::getDbConnection();
            for ($i = 0; $i < count($_POST['itemid']); $i++) {
                $itemid = $_POST['itemid'][$i];
                $activityid = $_POST['activityid'][$i];
                $processid = $_POST['processid'][$i];
                $estimateactcount=IowEstimate::model()->count(array('condition'=>'project_Id='.$_POST['Project_Id'].' AND est_activity_Id='.$itemid.''));
                if($estimateactcount > 0):
                    $sql="UPDATE iow_estimate SET activity_qty='".$_POST['quantity'][$i]."' WHERE est_activity_Id='".$itemid."' ";
                    $command = $connection->createCommand($sql);
                    $dataReader = $command->query();
                else:
                    $sql="INSERT INTO iow_estimate (project_Id,activity_Id,activity_qty,process_Id,est_activity_Id,iow_id) VALUES ('".$_POST['Project_Id']."','".$activityid."','".$_POST['quantity'][$i]."','".$processid."','".$itemid."','".$_POST['IOW_Id']."')";
                    $command = $connection->createCommand($sql);
                    $dataReader = $command->query();
                endif;
            }
            $arr=array('result'=>$_POST['Project_Id'],'error'=>'No');
            echo json_encode($arr);
        }
    }

    public function actionupdateinvoice()
    {
        $invoices=Invoice::model()->findAll(array('condition'=>'order_type=1','order'=>'invoice_id DESC'));
        foreach($invoices AS $key=>$invoice):
            $order=Orders::model()->findByPk($invoice['order_id']);
            if(count($order)>0):
                $vendor=Vendors::model()->findByPk($order['vendor_id']);
                if(count($vendor)>0):
                    $name=$vendor['Name'];
                    $invoice->vendor=$name;
                    $invoice->save(false);
                    echo ($key + 1)."sucess"."<br>";
                endif;
            endif;
        endforeach;
    }

    public function actionDeleteworkorder()
    {
        $orderres=OrderedResource::find()->where(['order_id'=>$_POST['orderid']])->all();
        foreach($orderres AS $orderre):
            $orderre->delete_status=1;
            $orderre->save(false);
        endforeach;
        $order=Orders::find()->where(['order_id'=>$_POST['orderid']])->one();
        $order->delete_status=1;
        $order->save(false);
        $arr=array('result'=>$_POST['orderid'].' deleted','error'=>'No');
        return json_encode($arr);
    }

    public function actionDeleteworkorderbill()
    {
        $wbillitems=WorkorderItems::find()->where(['bill_id'=>$_POST['billid']])->andWhere(['delete_status'=>0])->all();
        foreach($wbillitems AS $wbillitem):
            $wbillitem->delete_status=1;
            $wbillitem->save(false);
        endforeach;
        $worderbill=WorkorderBills::findOne($_POST['billid']);
        $worderbill->delete_status=1;
        $worderbill->save(false);
        $arr=array('result'=>$_POST['billid'].' deleted','error'=>'No');
        return json_encode($arr);
    }

    public function actionListiow()
    {
        $connection = CActiveRecord::getDbConnection();
        $sql="SELECT Workgroup_Id,Project_Id,Name,worktype FROM workgroups WHERE status='0' AND pricing_status=0 ";
        $sql.="AND  Project_Id='".$_POST['projectid']."' ORDER BY sortorder ASC, Workgroup_Id ASC, Name ASC";
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $dataProvider=$dataReader->readAll();
        $iowlist='<option value="none">Select IOW</option>';
        if(count($dataProvider)>0):
            foreach($dataProvider AS $key=>$data):
                $iowlist.='<option value="'.$data['Workgroup_Id'].'">'.$data['Name'].'</option>';
            endforeach;
        endif;
        $arr=array('result'=>$iowlist,'error'=>'No');
        echo json_encode($arr);
    }
    public function actionListactivity()
    {
        $iowid=$_POST['wbsid'];
        $projid=$_POST['projectid'];
        $wbsactivities=WorkgroupActivities::model()->findAll(array('condition'=>'wbs_id='.$iowid.' AND pricing_status=0','order'=>'sortorder ASC'));
        $activitylist='<option value="none">Select Activity</option>';
        if(count($wbsactivities)>0):
            foreach($wbsactivities AS $key=>$wbsactivity):
                if($wbsactivity['process_Id']==2):
                    $process="Project Setup";
                    $activity=ProjectSetup::model()->findByPk($wbsactivity['activity_Id']);
                    $name=$activity->PS_Name;
                elseif($wbsactivity['process_Id']==3):
                    $process="Production";
                    $activity=Products::model()->findByPk($wbsactivity['activity_Id']);
                    $name=$activity->Name;
                elseif($wbsactivity['process_Id']==4):
                    $process="Logistics";
                    $activity=Logistics::model()->findByPk($wbsactivity['activity_Id']);
                    $name=$activity->Name;
                elseif($wbsactivity['process_Id']==5):
                    $process="Construction";
                    $activity=Construction::model()->findByPk($wbsactivity['activity_Id']);
                    $name=$activity->CO_Name;
                elseif($wbsactivity['process_Id']==8):
                    $process="Overheads";
                    $activity=Overheads::model()->findByPk($wbsactivity['activity_Id']);
                    $name=$activity->Name;
                endif;
                if($wbsactivity['activity_Name']!=''):
                    $activityname=$wbsactivity['activity_Name'];
                else:
                    $activityname=$name;
                endif;
                $activitylist.='<option value="'.$wbsactivity['id'].'">'.$activityname.'</option>';
            endforeach;
        endif;
        $arr=array('result'=>$activitylist,'error'=>'No');
        echo json_encode($arr);
    }
