        endif;
        $wbsactivities=WorkgroupActivities::model()->findByPk($_POST['activity']);
        $unit=$wbsactivities['activity_Unit'];
        $arr=array('result'=>$resourcelist,'unit'=>$unit,'error'=>'No');
        echo json_encode($arr);
    }
