    public function actionPrintworkorder($id)
    {
        $invoice=WorkorderBills::findOne($id);
        $project = Projects::findOne($invoice['place'])->Name;
        $vendoracnt=Vendors::findOne($invoice['party']);
        $resourceitems=WorkorderItems::find()->where(['bill_id' => $id])->andWhere(['delete_status' => 0])->all();
        $ordered_resource=OrderedResource::find()->where(['order_id' => $invoice['order_id']])->one();
        $jobcard=Jobcard::findOne($ordered_resource['jobcard_id']);
        $datarows = '';
        $datarows .= "<style>table,td{border:1px solid black;border-collapse:collapse}</style>
                        <table width='100%' cellpadding='7px' class='table table-bordered' id='projectexptable' style='display: table; overflow: hidden;font-size: 8pt;'>
                            <tbody>
                                <tr>
                                    <th colspan='10' style='border-bottom:solid 1px #000000;'><b>".$vendoracnt->Name."</b></th>
                                </tr>
                                <tr>
