                                    <th style='border-right:solid 1px #000000;'>Previous</th>
                                    <th style='border-right:solid 1px #000000;'>Present</th>
                                    <th>Cumulative</th>
                                </tr>";
        
        $total=0;
        $lasttotal=0;
        foreach($resourceitems AS $key=>$resourceitem):
            $orderid = $resourceitem['order_id'];
            $resdetails=Resources::findOne($resourceitem['resource_id']);
            $orderdet=OrderedResource::find()->where(['order_id' => $resourceitem['order_id']])->andWhere(['resource_id' => $resourceitem['resource_id']])->one();
            //$amount=$resdetails['Price'] * $resourceitem['resource_qty'];
            $amount=$orderdet['rate'] * $resourceitem['resource_qty'];
            //$amount=$orderdet['rate'] * $resourceitem['resource_qty'];
            $invoiceresqty=WorkorderItems::find()->where(['!=','bill_id', $id])->andWhere(['order_id' => $resourceitem['order_id']])->andWhere(['resource_id' => $resourceitem['resource_id']])->andWhere(['delete_status' => 0])->all();
            $totbillresqty=0;
            foreach($invoiceresqty AS $item):
                $totbillresqty=$totbillresqty + $item['resource_qty'];
            endforeach;
            $amountlast=($orderdet['rate'] * $totbillresqty);
