                        </tr>";
        
        if($invoice['cgst']!=0):
            $gst=$invoice['cgst'] + $invoice['sgst'];
        else:
            $gst=$invoice['igst'];
        endif;
        if($invoice['cgst']!=0 & $invoice['sgst']!=0):
            $gstper=$invoice['cgst'] + $invoice['sgst'];
            $gsttype=1;
        elseif($invoice['igst']!=0):
            $gstper=$invoice['igst'];
            $gsttype=2;
        else:
            $gstper=0;
            $gsttype=0;
        endif;
        
        if($gsttype==1 && $gstper!=0):
            $sgst=$gstper / 2;
            $gstamount=($total * $sgst) / 100;
            $gstamount1=($lasttotal * $sgst) / 100;

