                            </tr>
                            <tr style='background: #ffffff;'>
                            <td colspan='8' style='text-align: right'><b>CGST (".$sgst."%)</b></td>
                            <td style='text-align: right'>
                                <span id='cgstamount'><b>".number_format((float)$gstamount1, 2)."</b></span>
                            </td>
                            <td style='text-align: right'>
                                <span id='cgstamount'><b>".number_format((float)$gstamount, 2)."</b></span>
                            </td>
                        </tr>";

            $totalgst=$total + $gstamount + $gstamount;
            $totalgst1=$lasttotal + $gstamount1 + $gstamount1;
        
        elseif($gsttype==2 & $gstper!=0):
            $igstamount=($total * $gstper) / 100;
            $igstamount1=($lasttotal * $gstper) / 100;
        
            $datarows .= "<tr style='background: #ffffff;'>
                            <td colspan='8' style='text-align: right'><b>IGST (".$gstper."%)</b></td>
                            <td style='text-align: right'>
                                <span id='igstamount'><b>".number_format((float)$igstamount1, 2)."</b></span>
                            </td>
                            <td style='text-align: right'>
                                <span id='igstamount'><b>".number_format((float)$igstamount, 2)."</b></span>
                            </td>
                        </tr>";

            $totalgst=$total + $igstamount;
            $totalgst1=$lasttotal + $igstamount1;
        
        else:
                $totalgst=$total;
                $totalgst1=$lasttotal;
        endif;
        
        $order=Orders::findOne($orderid);
        $retamount = ($total * $order['Retention']) / 100;
        $amountinc=$totalgst;
        $netamount=$amountinc - $retamount;
        $netamount_new=$netamount - $invoice['other_deductions'];
        
        $retamount1 = ($lasttotal * $order['Retention']) / 100;
        $amountinc1=$totalgst1;
        $netamount1=$amountinc1 - $retamount1;
        $netamount_new1=$netamount1 - $invoice['other_deductions'];
        
        $datarows .= "<tr style='background: #ffffff;'>
                        <td colspan='8' style='text-align: right'><b>Amount Including Taxes</b></td>
                        <td style='text-align: right'><span id='amountinclusive'><b>".number_format((float)$amountinc1, 2)."</span></b></td>
                        <td style='text-align: right'><span id='amountinclusive'><b>".number_format((float)$amountinc, 2)."</span></b></td>
                    </tr>";
        
        if($retamount1!=0):
        
            $datarows .= "<tr style='background: #ffffff;'>
                            <td colspan='8' style='text-align: right'><b>Retention (".$order['Retention']."%)</b></td>
                            <td style='text-align: right'>
                                <span id='billretention'><b>".number_format((float)$retamount1, 2)."</b></span>
                            </td>
                            <td style='text-align: right'>
                                <span id='billretention'><b>".number_format((float)$retamount, 2)."</b></span>
                            </td>
                        </tr>";
        
        endif;
        
        if($invoice['other_deductions']!=0):
        
            $datarows .= "<tr style='background: #ffffff;'>
                            <td colspan='8' style='text-align: right'><b>Other deductions</b></td>
                            <td style='text-align: right'>
                               ".number_format((float)$invoice['other_deductions'], 2)." 
                            </td>
                            <td style='text-align: right'>
                               ".number_format((float)$invoice['other_deductions'], 2)." 
                            </td>
                        </tr>";
        
        endif;
        
        $datarows .= "<tr style='background: #ffffff;'>
                        <td colspan='8' style='text-align: right'><b>Net Amount</b></td>
                        <td style='text-align: right'>
                            <span id='billnetamount'><b>".number_format((float)$netamount_new1, 2)."</b></span>
                        </td>
                        <td style='text-align: right'>
                            <span id='billnetamount'><b>".number_format((float)$netamount_new, 2)."</b></span>
                        </td>
                    </tr>";
        
        $vendor=Vendors::findOne($invoice['party']);
        //$account=AccountsItem::model()->findByPk($vendor['account_id']);
        //echo $vendor['account_id'];exit;
        if($vendor['account_id']!=0):
            $ledgerbal = $this->vendorledgerbalance($invoice['place'], $vendor['account_id']);
        else:
            $ledgerbal=0;
        endif;
        
        $datarows .= "<tr style='background: #ffffff;'>
                        <td colspan='8' style='text-align: right'><b>Amount paid till today</b></td>
                        <td style='text-align: right'>
                            <span id='billadvance'><b>".number_format((float)$ledgerbal, 2)."</b></span>
                        </td>
                        <td style='text-align: right'>
                            <span id='billadvance'><b>".number_format((float)$ledgerbal, 2)."</b></span>
                        </td>
                    </tr>";
        
        
        $datarows .= "<tr style='background: #ffffff;'>
                        <td colspan='8' style='text-align: right'><b>Total Balance Payable</b></td>
                        <td style='text-align: right'>
                            <span id='amountpayabe'><b>".number_format((float)($netamount1 - $ledgerbal), 2)."</b></span>
                        </td>
                        <td style='text-align: right'>
                            <span id='amountpayabe'><b>".number_format((float)($netamount - $ledgerbal), 2)."</b></span>
                        </td>
                    </tr>";
        
        $datarows .= "</tbody>
                        </table>";
        
        //echo $datarows; exit;
        $pdf = new Pdf();
        $mpdf = $pdf->api;
        $mpdf->WriteHtml($datarows); 
        $mpdf->Output('billreports.pdf','I');
    }

