    public function actionListworktype()
    {
        \Yii::$app->response->format = \yii\web\Response::FORMAT_JSON;
        $connection = \Yii::$app->db;
        $search = isset($_POST['worktypename']) ? trim($_POST['worktypename']) : '';
        $sql = "SELECT estworktype_id, estworktype_name FROM estimateworktypes WHERE estworktype_status = 0";
        if ($search !== '') {
            $sql .= " AND estworktype_name LIKE '%" . addslashes($search) . "%'";
        }
        $sql .= " ORDER BY sortorder ASC";
        $rows = $connection->createCommand($sql)->queryAll();
        if (empty($rows)) {
            return ['error' => 'No', 'result' => '<p style="color:#aaa;font-size:13px;text-align:center;padding:30px 0;">No project types found.</p>'];
        }
        $html = '<table style="width:100%;border-collapse:collapse;font-size:13px;">'
              . '<thead><tr>'
              . '<th style="background:#555;color:#fff;font-weight:bold;padding:8px 12px;border:1px solid #444;text-align:center;width:42px;">#</th>'
              . '<th style="background:#555;color:#fff;font-weight:bold;padding:8px 12px;border:1px solid #444;">Project Type</th>'
              . '<th style="background:#555;color:#fff;font-weight:bold;padding:8px 12px;border:1px solid #444;text-align:center;width:80px;"></th>'
              . '</tr></thead><tbody>';
        foreach ($rows as $i => $data) {
            $safeName = htmlspecialchars($data['estworktype_name'], ENT_QUOTES);
            $html .= '<tr class="projtypes" data-id="' . $data['estworktype_id'] . '">'
                   . '<td style="padding:8px 12px;border:1px solid #ddd;text-align:center;color:#999;">' . ($i + 1) . '</td>'
                   . '<td style="padding:8px 12px;border:1px solid #ddd;">' . $safeName
                   .     '<input type="hidden" id="protype' . $data['estworktype_id'] . '" value="' . $safeName . '"></td>'
                   . '<td style="padding:6px 8px;border:1px solid #ddd;text-align:center;white-space:nowrap;">'
                   .     '<button class="editForm btn btn-default btn-xs" data-id="' . $data['estworktype_id'] . '" value="' . $data['estworktype_id'] . '" style="border-radius:50%;width:28px;height:28px;padding:0;margin-right:4px;" title="Edit"><span class="icon-pencil"></span></button>'
                   .     '<button class="deleteestworktypebutton btn btn-danger btn-xs" id="deleteestworktypebutton' . $data['estworktype_id'] . '" data-id="' . $data['estworktype_id'] . '" style="border-radius:50%;width:28px;height:28px;padding:0;" title="Delete"><span class="icon-trash1"></span></button>'
                   . '</td></tr>';
        }
        $html .= '</tbody></table>';
        $items = array_map(function($r){ return ['id' => $r['estworktype_id'], 'name' => $r['estworktype_name']]; }, $rows);
        return ['error' => 'No', 'result' => $html, 'items' => $items];
    }

