    public function actionListestactivity()
    {
        $connection  = \Yii::$app->db;
        $actTypeId   = (int)($_POST['estactivitytype'] ?? 0);
        $searchName  = isset($_POST['estactivityname']) ? trim($_POST['estactivityname']) : '';
        $workType    = isset($_POST['estworktype']) ? (int)$_POST['estworktype'] : 0;

        $displaywt     = 'hide';
        $estactypename = '';
        if ($actTypeId > 0) {
            $typeObj = EstimateActivityType::findOne($actTypeId);
            if ($typeObj) {
                $estactypename = $typeObj->activitytype_name;
                if (strcasecmp('Construction Activities', $estactypename) == 0) {
                    $displaywt = 'show';
                }
            }
        }

        $sql = "SELECT ea.*, eat.activitytype_name, ewt.estworktype_name
                FROM estimateactivities ea
                LEFT JOIN estimateactivitytypes eat ON eat.activitytype_id = ea.activity_type
                LEFT JOIN estimateworktypes ewt ON ewt.estworktype_id = ea.work_type
                WHERE ea.activity_status = 0";
        if ($actTypeId > 0) {
            $sql .= " AND ea.activity_type = " . $actTypeId;
        }
        if ($searchName !== '') {
            $sql .= " AND ea.activity_name LIKE '%" . addslashes($searchName) . "%'";
        }
        if ($workType > 0) {
            $sql .= " AND ea.work_type = " . $workType;
        }
        $sql .= " ORDER BY ea.sortorder ASC, ea.activity_id ASC";

        $estimateworktypes = $connection->createCommand($sql)->queryAll();
        if (empty($estimateworktypes)) {
            $html = '<p style="color:#aaa;font-size:13px;text-align:center;padding:30px 0;">No activities found.</p>';
        } else {
            $html = '<table style="width:100%;border-collapse:collapse;font-size:13px;">'
                  . '<thead><tr>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;text-align:center;width:42px;">#</th>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;">Project Type</th>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;">Type</th>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;">Activity</th>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;text-align:center;width:70px;">Unit</th>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;text-align:right;width:80px;">Rate</th>'
                  . '<th style="background:#555;color:#fff;font-weight:600;font-size:11px;line-height:1;padding:3px 6px;border:1px solid #444;text-align:center;width:120px;"></th>'
                  . '</tr></thead><tbody>';
            foreach ($estimateworktypes as $i => $data) {
                $safeName = htmlspecialchars($data['activity_name'], ENT_QUOTES);
                $safeUnit = htmlspecialchars($data['activity_unit'], ENT_QUOTES);
                $safeType = htmlspecialchars($data['activitytype_name'] ?? '—', ENT_QUOTES);
                $safeWType = htmlspecialchars($data['estworktype_name'] ?? '—', ENT_QUOTES);
                $html .= '<tr class="esttypesort" id="estactivityrow' . $data['activity_id'] . '" data-id="' . $data['activity_id'] . '" data-type="' . $data['activity_type'] . '">'
                       . '<td style="padding:8px 12px;border:1px solid #ddd;text-align:center;color:#999;">' . ($i + 1) . '</td>'
                       . '<td style="padding:8px 12px;border:1px solid #ddd;font-size:12px;color:#555;">' . $safeWType . '</td>'
                       . '<td style="padding:8px 12px;border:1px solid #ddd;font-size:12px;color:#555;">' . $safeType . '</td>'
                       . '<td style="padding:8px 12px;border:1px solid #ddd;">' . $safeName
                       .     '<input type="hidden" value="' . $safeName . '" id="activity' . $data['activity_id'] . '">'
                       .     '<input type="hidden" value="' . $safeUnit . '" id="activityunit' . $data['activity_id'] . '"></td>'
                       . '<td style="padding:8px 12px;border:1px solid #ddd;text-align:center;">' . $safeUnit . '</td>'
                       . '<td style="padding:8px 12px;border:1px solid #ddd;text-align:right;">' . number_format((float)$data['activity_rate'], 2) . '</td>'
                       . '<td style="padding:6px 8px;border:1px solid #ddd;text-align:center;white-space:nowrap;">'
                       .     '<button type="button" id="resourceallocation" data-id="' . $data['activity_id'] . '" class="btn btn-default btn-xs allocate-resosurces-btn res_actlibrary_' . $data['activity_id'] . '" style="border-radius:50%;width:28px;height:28px;padding:0;margin-right:2px;" title="Allocate Resources"><span class="icon-library_books"></span></button>'
                       .     '<button type="button" class="al-edit-activity-btn" data-actid="' . $data['activity_id'] . '" style="border-radius:50%;width:28px;height:28px;padding:0;margin-right:2px;background:#e8f0fe;border:1px solid #b0c4f8;cursor:pointer;" title="Edit"><span class="icon-pencil" style="color:#3a7bd5;font-size:13px;"></span></button>'
                       .     '<button type="button" class="deleteestactivitybutton btn btn-danger btn-xs" data-id="' . $data['activity_id'] . '" style="border-radius:50%;width:28px;height:28px;padding:0;" title="Delete"><span class="icon-trash1"></span></button>'
                       . '</td></tr>';
            }
            $html .= '</tbody></table>';
        }
        return json_encode(['estactypename' => $estactypename, 'displaywt' => $displaywt, 'result' => $html, 'error' => 'No']);
    }
