    public function actionUpdateactivitywithtasks()
    {
        $connection = \Yii::$app->db;
        $activityId = (int)$_POST['activity_id'];
        $workingHours = (int)($_POST['working_hours'] ?? 8);
        $connection->createCommand()->update('estimateactivities', [
            'activity_type' => (int)($_POST['activitytypeid'] ?? 0),
            'work_type'     => (int)($_POST['worktypeid'] ?? 0),
            'iow_group_id'  => (int)($_POST['iow_group_id'] ?? 0),
            'activity_name' => $_POST['estactivityname'][0],
            'activity_unit' => $_POST['estactivityunit'][0],
            'working_hours' => $workingHours,
        ], 'activity_id = ' . $activityId)->execute();
        $submittedIds = [];
        if (!empty($_POST['task_name'])) {
            foreach ($_POST['task_name'] as $j => $taskName) {
                if (trim($taskName) === '') continue;
                $existingId = (int)($_POST['task_id'][$j] ?? 0);
                if ($existingId > 0) {
                    $connection->createCommand()->update('activity_tasks', [
                        'task_name'    => $taskName,
                        'task_unit'    => $_POST['task_unit'][$j] ?? '',
                        'productivity' => $_POST['task_productivity'][$j] ?? 0,
                        'sort_order'   => $j,
                    ], 'id = ' . $existingId)->execute();
                    $submittedIds[] = $existingId;
                } else {
                    $connection->createCommand()->insert('activity_tasks', [
                        'activity_id'  => $activityId,
                        'task_name'    => $taskName,
                        'task_unit'    => $_POST['task_unit'][$j] ?? '',
                        'productivity' => $_POST['task_productivity'][$j] ?? 0,
                        'sort_order'   => $j,
                    ])->execute();
                    $submittedIds[] = (int)$connection->lastInsertID;
                }
            }
        }
        // Delete only tasks that were removed (not in submitted list)
        if (!empty($submittedIds)) {
            $connection->createCommand(
                "DELETE FROM activity_tasks WHERE activity_id = $activityId AND id NOT IN (" . implode(',', $submittedIds) . ")"
            )->execute();
        } else {
            $connection->createCommand("DELETE FROM activity_tasks WHERE activity_id = $activityId")->execute();
        }
        return json_encode(['error' => 'No']);
    }

    /* TEMP diagnostic — remove once the duplicate-activity-in-dropdown gap is root-caused. */
    public function actionDebugactrows()
    {
        Yii::$app->response->format = \yii\web\Response::FORMAT_JSON;
        $db = \Yii::$app->db;
        $name = \Yii::$app->request->get('name');
        $rows = $db->createCommand(
            "SELECT activity_id, activity_name, activity_status, work_type, activity_type, iow_group_id
             FROM estimateactivities WHERE activity_name LIKE :n",
            [':n' => '%' . $name . '%']
        )->queryAll();
        foreach ($rows as &$r) {
            $r['allocated'] = (bool) $db->createCommand(
                "SELECT 1 FROM workgroup_activities_new w
                 JOIN scheduleactivities sa ON sa.activity_id = w.id AND sa.status = 0
                 WHERE w.activity_Id = :id AND w.pricing_status = 0 LIMIT 1",
                [':id' => $r['activity_id']]
            )->queryScalar();
        }
        return ['rows' => $rows];
    }

    /* TEMP diagnostic — remove once the Planned Duration mismatch is root-caused. */
    public function actionDebugactdur()
    {
        Yii::$app->response->format = \yii\web\Response::FORMAT_JSON;
        $db = \Yii::$app->db;
        $name = \Yii::$app->request->get('name');
        $rows = $db->createCommand(
            "SELECT sa.id, sa.name, sa.activity_id AS wan_id, sa.start_date, sa.end_date,
                    sa.actual_start_date, sa.actual_end_date, sa.duration, sa.old_duration,
                    sa.quantity, sa.status, sa.projectId, w.duration AS wan_duration
             FROM scheduleactivities sa
             LEFT JOIN workgroup_activities_new w ON w.id = sa.activity_id
             WHERE sa.name LIKE :n",
            [':n' => '%' . $name . '%']
        )->queryAll();
        $holidays = [];
        foreach ($rows as $r) {
            $pid = $r['projectId'];
            if (!isset($holidays[$pid])) {
                $h = $db->createCommand("SELECT dates, weeks FROM holidays WHERE project_id = :p", [':p' => $pid])->queryOne();
                $holidays[$pid] = $h ?: ['dates' => '', 'weeks' => ''];
            }
        }
        return ['rows' => $rows, 'holidays' => $holidays];
    }

    public function actionDeleteactivity()
    {
        $connection = \Yii::$app->db;
        $activityid = (int) $_POST['activityid'];

        /* "Allocated" means visible in a project's Gantt chart, full stop —
           a workgroup_activities_new row can be pricing_status=0 ("active")
           while every wbsscheduleitems/scheduleactivities row under it was
           already soft-deleted (status=1) via the Gantt/WBS delete flow,
           leaving an orphaned allocation that no longer shows anywhere.
           Only count it as allocated if it still has a live schedule row —
           i.e. an actual Gantt bar — same status=0 convention actionGanttitems()
           requires to render one. */
        $projectNames = $connection->createCommand(
            "SELECT DISTINCT p.Name
             FROM workgroup_activities_new w
             JOIN projects p ON p.Project_Id = w.project_Id
             JOIN scheduleactivities sa ON sa.activity_id = w.id AND sa.status = 0
             WHERE w.activity_Id = :id
               AND w.pricing_status = 0",
            [':id' => $activityid]
        )->queryColumn();

        if (!empty($projectNames)) {
            $activity = $connection->createCommand(
                "SELECT activity_name FROM estimateactivities WHERE activity_id = :id",
                [':id' => $activityid]
            )->queryOne();
            $activityname = $activity ? $activity['activity_name'] : '';
            $projectList = implode(', ', array_filter($projectNames));

            return json_encode([
                'error'     => 'Yes',
                'errortext' => 'Activity "' . $activityname . '" is already allocated to project(s) "' . $projectList . '" and cannot be deleted.',
                'Id'        => $activityid,
            ]);
        }

        $sql = "UPDATE `estimateactivities` SET `activity_status`=1 WHERE `activity_id`=" . $activityid . " ";
        $command = $connection->createCommand($sql);
        $command->query();
        $arr = array('error' => 'No', 'Id' => $activityid);
        return json_encode($arr);
    }

