    public function actionResources()
    {
        $connection = $connection = \Yii::$app->db;
        $sql="SELECT * FROM estimateactivities WHERE activity_id=".$_GET['id']." ";
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $model=$dataReader->read();
        $sqltemvals="SELECT a.Name AS resource,a.Unit,a.Resource_Id,a.ResourceType_Id,a.Resource_Location,b.* FROM resources AS a
                INNER JOIN estactivity_resources AS b ON  a.Resource_Id=b.est_resource_id
                WHERE b.estactivity_id='".$_GET['id']."' ORDER BY a.Resource_Id";
        $command=$connection->createCommand($sqltemvals);
        $dataReader=$command->query();
        $resourcesadded=$dataReader->readAll();
        $sql="SELECT Name FROM resources  WHERE status='0' ORDER BY Resource_Id ASC, Name ASC";
        $command=$connection->createCommand($sql);
        $dataReader=$command->query();
        $resources=$dataReader->readAll();
        foreach($resources AS $key=>$res):
            if($key==0):
                $dataProvider="'".$res['Name']."'";
            else:
                $dataProvider.=",'".$res['Name']."'";
            endif;
        endforeach;
        // Uncomment the following line if AJAX validation is needed
        // $this->performAjaxValidation($model);
        if(isset($_POST['Activity_Name']))
        {
            $sql="UPDATE estimateactivities SET activity_name='".$_POST['Activity_Name']."',activity_unit='".$_POST['Activity_Unit']."',activity_rate='".$_POST['Activity_Rate']."' WHERE activity_id='".$_GET['id']."' ";
            $command=$connection->createCommand($sql);
            $dataReader=$command->query();
            for($i=0;$i<count($_POST['resourceid']);$i++)
            {
                $amount=($_POST['resourceqty'][$i] * $_POST['resourcerate'][$i]);
                $sql="UPDATE estactivity_resources SET est_resource_quantity='".$_POST['resourceqty'][$i]."',est_resource_amount='".$amount."',est_resource_rate='".$_POST['resourcerate'][$i]."' WHERE estactres_id='".$_POST['resourceid'][$i]."' ";
                $command=$connection->createCommand($sql);
                $dataReader=$command->query();
            }
            $this->redirect(array('projects/resources?id='.$_GET['id'].''));
        }
        $this->render('activityresources',array(
                'model'=>$model,
                'resourcesadded'=>$resourcesadded,
                'dataProvider'=>$dataProvider,
        ));
    }
