                                                <button type="button" class="btn btn-primary" style="border-color: green;background: green;display: none;" id="electlogbookreportsaved"><span class="icon-check"></span> Saved</button>                                         
                                            </div>
                                        </div>
                                    </div></form>';
            endif;
        endif;
        if($totaldes==0):
            $datarows.='<div style="text-align: center;">No Despatch Orders Found</div>';
        endif;
        $arr=array('result'=>$datarows,'error'=>'No');
        return json_encode($arr);
    }
    public function actionReportpowerbook()
    {
        $connection = Yii::$app->db;
        $userid=Yii::$app->user->id;
        for ($i=0; $i < count($_POST['resourceid']); $i++) {
            $sql = "SELECT COUNT(log_hours) hours FROM `electrical_logbook` WHERE `log_resource` = ".$_POST['resourceid'][$i]." AND log_project=".$_POST['electlogbookproject']." AND log_date = '".date('Y-m-d',strtotime($_POST['ElectLogbook_Date']))."' ";
            //echo $sql;exit;
            $command=$connection->createCommand($sql);
            $dataReader=$command->query();
            $currreportdata=$dataReader->read();
            //echo $currreportdata['hours'];exit;
            if($currreportdata['hours']==0): 
                $sql = "INSERT INTO `electrical_logbook` (`log_date`,`log_project`,`log_consumption`,`log_resource`,`log_hours`,`log_amount`,`log_status`,`log_reported_user`) VALUES ('".date('Y-m-d',strtotime($_POST['ElectLogbook_Date']))."','".$_POST['electlogbookproject']."','".$_POST['electcurrentcons']."','".$_POST['resourceid'][$i]."','".$_POST['eq_noofhrs'][$i]."','".$_POST['equipmentamount'][$i]."','0','".$userid."')";
            else:
                $sql = "UPDATE `electrical_logbook` SET log_consumption='".$_POST['electcurrentcons']."',log_hours='".$_POST['eq_noofhrs'][$i]."',log_amount='".$_POST['equipmentamount'][$i]."' WHERE log_date = '".date('Y-m-d',strtotime($_POST['ElectLogbook_Date']))."' AND `log_resource` = ".$_POST['resourceid'][$i]." AND log_project=".$_POST['electlogbookproject']."";
            endif;
            //echo $sql;exit;
            $command=$connection->createCommand($sql);
            $dataReader=$command->query();
        }
        $arr=array('error'=>'No','projectid'=>$_POST['electlogbookproject']);
        return json_encode($arr);
    }
