    public function actionCreateuserrole()
    {
        $usrid = Yii::$app->user->Id;
        $model=new Userrole();
 
        $model->role_name=$_POST['rolename'];
        $model->status=$_POST['rolestatus'];
        $model->userid=$usrid;

        $model->save(false);

        $functions=$_POST['User']['functions'];

        if(count($functions)>0){
            $fnids='';
            foreach($functions as $key=>$function){
                if($key==0){
                    $fnids.=$function;
                }
                else{
                    $fnids.=",".$function;
                }
                if(isset($_POST['User']['functiontabs'.$function.''])){
                    $functiontabs=$_POST['User']['functiontabs'.$function.''];
               
                if(count($functiontabs)>0){
                    foreach($functiontabs as $key1=>$functiontab){
                         $tabpermissions='';
                        if(isset($_POST['User']['tabspermission'.$functiontab.''])){
                        $tabpermissions=$_POST['User']['tabspermission'.$functiontab.''];
                    
                        foreach ($tabpermissions as $key => $tabpermission) {
                           
                        $usertabs=New UserTabs();
                        $usertabs->user_id=$usrid;
                        $usertabs->function_id=$function;
                        $usertabs->tab_id=$functiontab;
                        $usertabs->micro_id=$tabpermission;
                        $usertabs->role_id=$model->role_id;
                        $usertabs->save(false);
                            }
                        }else{
                            $usertabs=New UserTabs();
                            $usertabs->user_id=$usrid;
                            $usertabs->function_id=$function;
                            $usertabs->tab_id=$functiontab;
                            $usertabs->micro_id=0;
                            $usertabs->role_id=$model->role_id;
                            $usertabs->save(false);

                        }
                        }
                    }
                }
                }
            }

            $connection = \Yii::$app->db;
            $sql="SELECT * from user_role";
            $command=$connection->createCommand($sql);
            $dataReader=$command->query();
            $roles=$dataReader->readAll();
            foreach ($roles as $key => $role) {
            $dropdwn=$role['role_name'];
            $values = $role['role_id'];
            }


            $arr=array('error'=>'No','dropdwn'=>$dropdwn,'values'=>$values);
        return json_encode($arr);
        }

       
     public function actionCreateuser()
     {

        $model=new User();

        $model->username=$_POST['Username'];
        //$model->activkey=Yii::$app->user->encrypt(microtime().$model->password);
        $model->createtime=time();
        $model->lastvisit=time();
        $model->password=$_POST['Password'];
        if(isset($_POST['email'])){
            $model->email=$_POST['email'];
        }
        $model->role_id=$_POST['role'];
        $model->account_type=$_POST['account_type'];
        $model->status=1;
        $model->superuser=1;
        if(isset($_POST['project'])){
            $projects=$_POST['project'];
        }
        if(isset($_POST['accounthd'])){
            $accounts=$_POST['accounthd'];
        }
        

        if($model->save(false)){

            if(isset($_POST['project'])){


                for($i=0;$i<count($projects);$i++)
                {
                        $connection = Yii::$app->db;
                        $userid=$model->id;
                        $projectid=$_POST['project'][$i];

                        $roleid=$model->role_id;

                        $sql="INSERT INTO user_projects (userid,projectid,role_id) VALUES (".$userid.",".$projectid.",".$roleid.")";
                           
                            $command=$connection->createCommand($sql);
                            $dataReader=$command->query();
                }
            }
            if(isset($_POST['accounthd'])){


                for($i=0;$i<count($accounts);$i++)
                {
                    $connection = Yii::$app->db;
                    $userid=$model->id;
                    //echo $userid; 
                    $accountid=$_POST['accounthd'][$i];
                    //echo $accountid;exit;
                    $roleid=$model->role_id;
                    $acntmodel=AccountsItem::find($accountid)->one();
                    //print_r($acntmodel);exit;
                  
                   
                   /* $sql="INSERT INTO user_accounts (user_id,account_id,role_id,account_type,schedule) VALUES ($userid,$accountid,$roleid,$acntmodel->account_type,$acntmodel->schedule)";*/
                    $sql="INSERT INTO `user_accounts` (`user_acnt_id`, `user_id`, `account_id`, `role_id`, `account_type`, `schedule`) VALUES (NULL, ".$userid.", ".$accountid.", ".$roleid.", ".$acntmodel->account_type.", ".$acntmodel->schedule.") ";
                        //echo $sql;exit;
                        $command=$connection->createCommand($sql);
                        $dataReader=$command->query();
                    }
                }
            





            $profile=New UserProfile();
            $profile->user_id=$model->id;
            $profile->role_id=$model->role_id;
            $profile->firstname=$_POST['firstname'];
            if(isset($_POST['lastname'])){
                $profile->lastname=$_POST['lastname'];
            }
            
            
            $profile->save(false);

        }
        $arr=array('error'=>'No');
        return json_encode($arr);
     }

