     public function actionCheckusername()
     {
        if (isset($_POST['name'])):
            $connection = \Yii::$app->db;
            $sql = "SELECT COUNT(*) AS total FROM user WHERE username='" . $_POST['name'] . "' AND status=1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $data = $dataReader->read();
            if ($data['total'] > 0):
                return 'Yes';
            else:
                return 'No';
            endif;

        endif;
     }
     public function actionCheckusernameupdate()
     {
        if (isset($_POST['name'])):
            $connection = \Yii::$app->db;
            $sql = "SELECT COUNT(*) AS total FROM user WHERE username='" . $_POST['name'] . "' AND id!='".$_POST['id']."' AND status=1";
            $command = $connection->createCommand($sql);
            $dataReader = $command->query();
            $data = $dataReader->read();
            if ($data['total'] > 0):
                return 'Yes';
            else:
                return 'No';
            endif;

        endif;
     }

     public function actionLeaseordersbill_old()
     {

        $uid = Yii::$app->user->Id; 
        $usernow = User::find()->where(['id'=>$uid])->one();
        $projuser = ProjuserSelection::find()->where(['userid' => $uid])->one();
        $datarows='';

        if(!empty($projuser)){

            $invoices=WorkorderBills::find()->where(['place' => $projuser->projectid])->andWhere(['order_type' => 4])->andWhere(['status'=>0])->andWhere(['delete_status' => 0])->orderBy(['bill_id' => SORT_DESC])->all();

            if(count($invoices)>0):


                $totalgrossamt=0;
                $totalgstamt=0;
                $totalnetamt=0;

                $datarows.='<div class="col-md-12"><div class="row workprderlist">
                            <div class="col-md-9">
                            <div class="row leassorders">
