                                <label>Date </label>
                            </div>
                            <div class="col-md-4" style="text-align:left;padding-left: 22px;padding-right: 22px;">
                                <label>Vendor </label>
                            </div>
                            <div class="col-md-2 text-right" style="text-align:left;">
                                <label>Bill No.</label>
                            </div>
                            <div class="col-md-2 text-center" style="text-align:right;">
                                <label>Amount</label>
                            </div>
                            </div></div>
                            <div class="col-md-3 type">
                            </div></div></div>';
                    $count=0;

                    foreach($invoices AS $key=>$invoice):

                    if($invoice['status']==0):
                        $style="disabled";
                    else:
                        $style="";
                    endif;


                    $resourceitems=WorkorderItems::find()->where(['bill_id' => $invoice['bill_id']])->andWhere(['delete_status' => 0])->all();
                    $total=0;
                    $grossamount=0;
                    $gst_amount=0;

                    foreach($resourceitems AS $resourceitem):

                        $resdetails=Resources::findOne($resourceitem['resource_id']);
                        $orderitems=OrderedResource::find()->where(['order_id' => $resourceitem['order_id']])->andWhere(['resource_id' => $resourceitem['resource_id']])->one();

                        $amount=$orderitems['rate'] * $resourceitem['resource_qty'];
                        //$amount=$resdetails['Price'] * $resourceitem['resource_qty'];
                        if($orderitems['cgst']!=0 & $orderitems['sgst']!=0):
                            $gstvalue=$orderitems['cgst'] + $orderitems['sgst'];
                        elseif($orderitems['igst']!=0):
                            $gstvalue=$orderitems['igst'];
                        else:
                            $gstvalue=0;
                        endif;
                        $gstamount=($amount * $gstvalue) / 100;
                        $amntincgst=$amount + $gstamount;
                        $total=$total + $amntincgst;
                        $grossamount= $grossamount + $amount;
                        $gst_amount= $gst_amount + $gstamount;

                    endforeach;


                    $orderdet=Orders::findOne($invoice['order_id']);
                    $vendor=Vendors::findOne($orderdet['vendor_id'])->Name;
                    $project=Projects::findOne($orderdet['project_id'])->Name;
                    if($invoice['amount_pay']!=0):
                        $billaamount=$invoice['amount_pay'];
                    else:
                        $billaamount=$total;
                    endif;
                    $netamount = $grossamount + $gst_amount;

                    $datarows.='<div class="col-md-12"><div class="row" id="workorderbillrow'.$invoice['bill_id'].'" style="margin: 0px !important;padding-top: 10px;">
                                  
                                    <div class="col-md-9">
                                        <div class="row">
                                            
                                            <div class="col-md-1">
                                                <span class="number workt-number"><b>'.++$count.'</b></span>
                                            </div>
                                            <div class="col-md-3 type">
                                                
                                                <span class="date"><em class="cal-icon icon-calendar1"></em>'.date('d-m-Y',strtotime($invoice['date'])).'</span>
                                            </div> 
                                            <div class="col-md-4 type">
                                               
                                                <span>'.$vendor.'</span>
                                            </div>
                                            <div class="col-md-2 type">
                                                
                                                <span>'.$invoice['bill_no'].'</span>
                                            </div>
                                            
