    public function actionViewleaseorderbills()
    {
        $id = $_POST['orderid'];
        

        if(!$invoice = WorkorderBills::find()->where(['order_id' => $id])->andwhere(['status' => 0])->one()){
            /*Billing Automation for work orders*/

            $ordersbil=Orders::findOne($id);
            if($ordersbil['order_type']==4){

                $total=0;
                $billtotal=0;
                $key = 0;
                $status = 0;
                $sgst = 0;
                $cgst = 0;
                $igst = 0;


                    $connection = Yii::$app->db;
                    $sql="SELECT resource_id, COUNT(*) as count FROM ordered_resource where order_id=".$ordersbil->order_id." GROUP BY rate,resource_id HAVING COUNT(*) > 1";
                    $command = $connection->createCommand($sql);
                    $dataReader = $command->query();
                    $dataProvider = $dataReader->read();


                    if(empty($dataProvider)):
                        $resourceitems=OrderedResource::find()->where(['order_id' => $ordersbil->order_id])->all();
                    else:
                        $resourceitems=OrderedResource::find()->where(['order_id' => $ordersbil->order_id])->andWhere(['group' => 'resource_id'])->all();
                    endif;

                    foreach($resourceitems AS $resourceitem):

                        $app_activityids = jobcard::find()->where(['resource'=>$resourceitem['resource_id']])->andWhere(['delete_status'=>0])->andWhere(['project_id'=>$ordersbil->project_id])->all();

                        foreach($app_activityids as $app_activityid){

                            $actId = $app_activityid->app_activity;

                                $sql = "SELECT MIN(date) as f_date FROM `activity_report_wrkactvty` WHERE `activity_id`=".$actId."";

                                $command = $connection->createCommand($sql);
                                $dataReader = $command->query();
                                $actreprt = $dataReader->read();

                                    
                                if($actreprt['f_date'] != null){

                                    $first_date = $actreprt['f_date'];
                                    if($ordersbil->bilingcycle == "0 Days"){
                                        //$str = $ordersbil->bilingcycle + 1;
                                        $str = 1;
                                    }else{

                                    $str = $ordersbil->bilingcycle;
                                }
                                
                                $billcycle = str_replace("Days","",$str);
                                $dd = date('Y-m-d', strtotime($first_date. ' + '.$billcycle.' days'));
                                $d = 1;
                                $billduedate = date('Y-m-d', strtotime($dd. ' - '.$d. 'days'));
                               

                        
                                $allqtys = ActivityReportWrkactvty::find()->where(['activity_id'=>$actId])->andWhere(['between', 'date', $first_date , $billduedate])->all();

                                $cum_qty = 0;
                                foreach($allqtys as $allqty){
                                    if($allqty){
                                        $cum_qty = $cum_qty + $allqty->quantity; 
                                    }else{
                                        $cum_qty = 0; 
                                    }
                                }   

                                if($billduedate <= date('Y-m-d')){
                                    
                                    $status = 1;
                                }
                            }
                        }


                        if($resourceitem['resource_name']==''):
                            $resname=Resources::findOne($resourceitem['resource_id'])->Name;
                        else:
                            $resname=$resourceitem['resource_name'];
                        endif;
                        $resitems=OrderedResource::find()->where(['resource_id' => $resourceitem['resource_id']])->andWhere(['order_id' => $id])->all();
                        $totalqty=0;
                        foreach($resitems AS $resitem):
                            $totalqty=$totalqty + $resitem['qnty'];
                        endforeach;
                        if(empty($dataProvider)):
                            $orderresqty=$resourceitem['qnty'];
                        else:
                            $orderresqty=$totalqty;
                        endif;
                        $invoiceresqty=InvoiceResources::find()->where(['order_id' => $ordersbil->order_id])->andWhere(['resource_id' => $resourceitem['resource_id']])->all();
                        $totresqty=0;


                        if(!empty($invoiceresqty)){
                            foreach($invoiceresqty AS $item):
                                $totresqty=$totresqty + $item['resource_qty'];
                            endforeach;
                            if($invoiceresqty['resource_qty']==''):
                                $resqty=$resourceitem['qnty'];
                            else:
                                $resqty=$invoiceresqty['resource_qty'];
                            endif;
                        }else{
                            $totresqty=0;
                            $resqty='';
                        }

                        $rate=$resourceitem['rate'];
                        $remqty=$orderresqty - $totresqty;
                        $amount=$rate * $remqty;
                        if($resourceitem['cgst']!=0):
                            $gst=$resourceitem['cgst'] + $resourceitem['sgst'];
                        else:
                            $gst=$resourceitem['igst'];
                        endif;
                        if($resourceitem['cgst']!=0 & $resourceitem['sgst']!=0):
                            $gstper=$resourceitem['cgst'] + $resourceitem['sgst'];
                            $gsttype=1;
                        elseif($resourceitem['igst']!=0):
                            $gstper=$resourceitem['igst'];
                            $gsttype=2;
                        else:
                            $gstper=0;
                            $gsttype=0;
                        endif;
                        //var_dump($gsttype);exit;
                        $gstamount=($amount * $gstper) / 100;
                        $amntincgst=$amount + $gstamount;

                        if($gsttype==1 && $gstper!=0):
                            $sgst=$gstper / 2;
                            $cgst=$gstper / 2;
                            

                        elseif($gsttype==2 & $gstper!=0):
                            $igst=$gstper;
                      
                        endif;


                    endforeach;

                    //-----DIRECTLY GIVING AS 1 TO AVOID CONDITIONS--------
                    $status = 1;
                    $billduedate = date('Y-m-d');
                    $cum_qty = (isset($cum_qty)) ? $cum_qty : 0;
                    $allqtys = (isset($allqtys)) ? $allqtys : 1;
                    //-----------------------------------------


                    if($status == 1){


                        $workorder=New WorkorderBills();
                        $workorder->order_id=$ordersbil->order_id;
                        
                        $workorder->date=date('Y-m-d',strtotime($billduedate));
                        $workorder->place=$ordersbil->project_id;
                        $workorder->party=$ordersbil->vendor_id;
