     public function actionApproveleaseorderbills()
     {
        $ordid = $_POST['lordid'];
        $bill_id = $_POST['lordbillid'];

        $count = count($_POST['resourceid']);

        for($i=0;$i<$count;$i++)
        {
            $lbillitems=WorkorderItems::find()->where(['bill_id'=>$bill_id])->andWhere(['order_id'=>$ordid])->andWhere(['resource_id'=>$_POST['resourceid'][$i]])->andWhere(['delete_status'=>0])->one();
            $lbillitems->resource_qty = $_POST['resourceqnty'][$i];
            $lbillitems->save(false);

            /*$lbills=WorkorderBills::find()->andWhere(['order_id'=>$ordid])->andWhere(['order_type'=>4])->andWhere(['delete_status'=>0])->one();
            $lbills->status =1;
            $lbills->save(false);*/
        }

        $wbills=WorkorderBills::find()->where(['bill_id'=>$bill_id])->one();
        if(isset($_POST['billno']))
            $wbills->bill_no = $_POST['billno'];
        $wbills->status = 1;
        $wbills->other_deductions = $_POST['other_deductions']; 
        $wbills->save(false);


        $arr=array('error'=>'No');
        return json_encode($arr); 

     }
