                            $gstvalue=$orderitems['igst'];
                        else:
                            $gstvalue=0;
                        endif;
                        $gstamount=($amount * $gstvalue) / 100;
                        $amntincgst=$amount + $gstamount;
                        $total=$total + $amntincgst;
                        $grossamount= $grossamount + $amount;
                        $gst_amount= $gst_amount + $gstamount;

                    endforeach;


                    $orderdet=Orders::findOne($invoice['order_id']);
                    $vendor=Vendors::findOne($orderdet['vendor_id'])->Name;
                    $project=Projects::findOne($orderdet['project_id'])->Name;
                    if($invoice['amount_pay']!=0):
                        $billaamount=$invoice['amount_pay'];
                    else:
                        $billaamount=$total;
                    endif;
                    $netamount = $grossamount + $gst_amount;

                    $datarows.='<div class="row" id="workorderbillrow'.$invoice['bill_id'].'">
                                  
                                    <div class="col-md-10">
                                        <div class="row">
                                            <div class="col-md-2 type">
                                                <label>Vendor </label>
                                                <span>'.$vendor.'</span>
                                            </div>
                                            <div class="col-md-2 type">
                                                <label>Project</label>
                                                <span>'.$project.'</span>
                                            </div>
                                            <div class="col-md-2 type">
                                                <label>Date</label>
                                                <span class="date"><em class="cal-icon icon-calendar1"></em>'.date('d-m-Y',strtotime($invoice['date'])).'</span>
                                            </div> 
                                            <div class="col-md-1 type">
                                                <label>Bill No.</label>
                                                <span>'.$invoice['bill_no'].'</span>
                                            </div>
                                            <div class="col-md-1 type">
                                                <label>Qty.</label>
                                                <span>'.$resource_qty.'</span>
                                            </div>
                                            <div class="col-md-1 type" style="text-align:right;">
                                                <label>Amount</label>
                                                <span>'.number_format((float)$grossamount, 2).'</span>
                                            </div>
                                            <div class="col-md-1 type" style="text-align:right;">
                                                <label>GST</label>
                                                <span>'.number_format((float)$gst_amount, 2).'</span>
                                            </div>
                                            <div class="col-md-2 type" style="text-align:right;">
                                                <label>Net Amount</label>
                                                <span>'.number_format((float)$netamount, 2).'</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div class="col-md-2 icon-groups type">
                                        <a href="javascript:;" class="btn btn-primary icon-eye viewleasehistbillitems" data-v="'.$invoice['bill_id'].'" title="View"></a>
                                       <!-- <a href="'.Yii::$app->request->baseUrl.'/projects/printworkorder?id='.$invoice['bill_id'].'" class="btn btn-primary icon-print" title="Print" target="_blank"></a>
                                        <a href="javascript:;" class="btn btn-danger icon-trash1 deleteworkordbill" data-v="'.$invoice['bill_id'].'" value="'.$invoice['bill_id'].'" id="deleteworkordbill'.$invoice['bill_id'].'" title="Delete Bill"></a>-->
                                    </div>
                                </div>';
                    $totalgrossamt+= $grossamount;
                    $totalgstamt+= $gst_amount;
                    $totalnetamt+= $netamount;


                endforeach;

                $datarows.='<div class="row" id="workorderbillrow'.$invoice['bill_id'].'">
                                    
                                    <div class="col-md-10">
                                        <div class="row">
                                            <div class="col-md-2 type">
                                                <label>&nbsp</label>
                                                <span><b>Total :</b</span>
                                            </div>
                                            <div class="col-md-2"></div>
                                            <div class="col-md-2"></div>
                                            <div class="col-md-1"></div>

                                            <div class="col-md-2 type" style="text-align:right;">
                                                <label>&nbsp;</label>
                                                <span>'.number_format((float)$totalgrossamt, 2).'</span>
                                            </div>
                                            <div class="col-md-1 type" style="text-align:right;">
                                                <label>&nbsp;</label>
                                                <span>'.number_format((float)$totalgstamt, 2).'</span>
                                            </div>
                                            <div class="col-md-2 type" style="text-align:right;">
                                                <label>&nbsp;</label>
                                                <span>'.number_format((float)$totalnetamt, 2).'</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div class="col-md-2 icon-groups type">
                                    </div>
                                </div>';

            else:
                $datarows='<div style="text-align: center;">No Bill History Found</div>';
            endif;

            $arr=array('result'=>$datarows,'error'=>'No');
            return json_encode($arr);


        }else{

            $datarows='<div style="text-align: center;">No Project Selected</div>';
            $arr=array('result'=>$datarows,'error'=>'No');
            return json_encode($arr);

        }
    }
